37	var _ runnerv1connect.RunnerServiceClient = (*Service)(nil)
38	
39	type Service struct{}
40	
41	// Register for new runner.
42	func (s *Service) Register(
43		ctx context.Context,
44		req *connect.Request[runnerv1.RegisterRequest],
45	) (*connect.Response[runnerv1.RegisterResponse], error) {
46		if req.Msg.Token == "" || req.Msg.Name == "" {
47			return nil, errors.New("missing runner token, name")
48		}
49	
50		runnerToken, err := actions_model.GetRunnerToken(ctx, req.Msg.Token)
51		if err != nil {
52			return nil, errors.New("runner registration token not found")
53		}
54	
55		if !runnerToken.IsActive {
56			return nil, errors.New("runner registration token has been invalidated, please use the latest one")
57		}
58	
59		if runnerToken.OwnerID > 0 {
60			if _, err := user_model.GetUserByID(ctx, runnerToken.OwnerID); err != nil {
61				return nil, errors.New("owner of the token not found")
62			}
63		}
64	
65		if runnerToken.RepoID > 0 {
66			if _, err := repo_model.GetRepositoryByID(ctx, runnerToken.RepoID); err != nil {
67				return nil, errors.New("repository of the token not found")
68			}
69		}
70	
71		labels := req.Msg.Labels
72		hasCancellingSupport := slices.Contains(req.Msg.GetCapabilities(), runnerCapabilityCancelling)
73	
74		// create new runner
75		name := util.EllipsisDisplayString(req.Msg.Name, 255)
76		runner := &actions_model.ActionRunner{
77			UUID:                 gouuid.New().String(),
78			Name:                 name,
79			OwnerID:              runnerToken.OwnerID,
80			RepoID:               runnerToken.RepoID,
81			Version:              req.Msg.Version,
82			AgentLabels:          labels,
83			Ephemeral:            req.Msg.Ephemeral,
84			HasCancellingSupport: hasCancellingSupport,
85		}
86		runner.GenerateAndFillToken()
87	
88		// create new runner
89		if err := actions_model.CreateRunner(ctx, runner); err != nil {
90			return nil, errors.New("can't create new runner")
91		}
92	
93		// update token status
94		runnerToken.IsActive = true
95		if err := actions_model.UpdateRunnerToken(ctx, runnerToken, "is_active"); err != nil {
96			return nil, errors.New("can't update runner token status")
97		}
98	
99		res := connect.NewResponse(&runnerv1.RegisterResponse{
100			Runner: &runnerv1.Runner{
101				Id:        runner.ID,
102				Uuid:      runner.UUID,
103				Token:     runner.Token,
104				Name:      runner.Name,
105				Version:   runner.Version,
106				Labels:    runner.AgentLabels,
107				Ephemeral: runner.Ephemeral,
108			},
109		})
110	
111		return res, nil
112	}
113	
114	// runnerCapabilityCancelling is the wire string the runner advertises in its
115	// capabilities list to indicate it understands the transitional cancelling
116	// state and will run post-step cleanup before finalizing the task.
117	const runnerCapabilityCancelling = "cancelling"
118	
119	type declareRequest interface {
120		proto.Message
121		GetVersion() string
122		GetLabels() []string
123		GetCapabilities() []string
124	}
125	
126	func applyDeclareRequestToRunner(runner *actions_model.ActionRunner, req declareRequest) []string {
127		runner.AgentLabels = req.GetLabels()
128		runner.Version = req.GetVersion()
129	
130		cols := []string{"agent_labels", "version"}
131		hasCancellingSupport := slices.Contains(req.GetCapabilities(), runnerCapabilityCancelling)
132		if runner.HasCancellingSupport != hasCancellingSupport {
133			runner.HasCancellingSupport = hasCancellingSupport
134			cols = append(cols, "has_cancelling_support")
135		}
136	
137		return cols
138	}
