156			return nil, err
157		} else if !has {
158			return nil, fmt.Errorf("task with id %d: %w", id, util.ErrNotExist)
159		}
160	
161		return &task, nil
162	}
163	
164	func GetRunningTaskByToken(ctx context.Context, token string) (*ActionTask, error) {
165		errNotExist := fmt.Errorf("task with token %q: %w", token, util.ErrNotExist)
166		if token == "" {
167			return nil, errNotExist
168		}
169		// A token is defined as being SHA1 sum these are 40 hexadecimal bytes long
170		if len(token) != 40 {
171			return nil, errNotExist
172		}
173		for _, x := range []byte(token) {
174			if x < '0' || (x > '9' && x < 'a') || x > 'f' {
175				return nil, errNotExist
176			}
177		}
178	
179		lastEight := token[len(token)-8:]
180	
181		if id := getTaskIDFromCache(token); id > 0 {
182			task := &ActionTask{
183				TokenLastEight: lastEight,
184			}
185			// Re-get the task from the db in case it has been deleted in the intervening period
186			has, err := db.GetEngine(ctx).ID(id).Get(task)
187			if err != nil {
188				return nil, err
189			}
190			if has {
191				return task, nil
192			}
193			successfulTokenTaskCache.Remove(token)
194		}
195	
196		var tasks []*ActionTask
197		// Cancelling tasks are still authenticating — post-run cleanup steps need API access (artifact uploads, cache saves, etc.) before the runner finalizes the task.
198		err := db.GetEngine(ctx).Where("token_last_eight = ? AND status IN (?, ?)", lastEight, StatusRunning, StatusCancelling).Find(&tasks)
199		if err != nil {
200			return nil, err
201		} else if len(tasks) == 0 {
202			return nil, errNotExist
203		}
204	
205		for _, t := range tasks {
206			tempHash := auth_model.HashToken(token, t.TokenSalt)
207			if subtle.ConstantTimeCompare([]byte(t.TokenHash), []byte(tempHash)) == 1 {
208				if successfulTokenTaskCache != nil {
209					successfulTokenTaskCache.Add(token, t.ID)
210				}
211				return t, nil
212			}
213		}
214		return nil, errNotExist
215	}
216	
217	func makeTaskStepDisplayName(step *jobparser.Step, limit int) (name string) {
218		if step.Name != "" {
219			name = step.Name // the step has an explicit name
220		} else {
221			// for unnamed step, its "String()" method tries to get a display name by its "name", "uses",
222			// "run" or "id" (last fallback), we add the "Run " prefix for unnamed steps for better display
223			// for multi-line "run" scripts, only use the first line to match GitHub's behavior
224			// https://github.com/actions/runner/blob/66800900843747f37591b077091dd2c8cf2c1796/src/Runner.Worker/Handlers/ScriptHandler.cs#L45-L58
225			runStr, _, _ := strings.Cut(strings.TrimSpace(step.Run), "\n")
226			name = "Run " + util.IfZero(strings.TrimSpace(runStr), step.String())
227		}
228		return util.EllipsisDisplayString(name, limit) // database column has a length limit
229	}
230	
231	// errJobAlreadyClaimed is a sentinel used inside claimJobForRunner to signal that
232	// another runner won the optimistic-lock race; it is never returned to callers.
233	var errJobAlreadyClaimed = errors.New("job already claimed by another runner")
234	
235	// pickTaskBatchSize bounds how many waiting jobs each CreateTaskForRunner query loads,
236	// so a large backlog is not fetched into memory on every runner poll.
237	// It is a var only so tests can shrink it to exercise pagination cheaply.
238	var pickTaskBatchSize = 100
239	
240	// CreateTaskForRunner finds a waiting job that matches the runner's labels and
241	// atomically claims it. It iterates through all matching jobs so that a
242	// concurrent claim by another runner (which would lose the optimistic lock on
243	// job #1) does not leave the remaining jobs permanently unassigned.
244	func CreateTaskForRunner(ctx context.Context, runner *ActionRunner) (*ActionTask, bool, error) {
245		if db.InTransaction(ctx) {
246			return nil, false, errors.New("CreateTaskForRunner must not be called within a database transaction")
247		}
248		e := db.GetEngine(ctx)
249	
250		jobCond := builder.NewCond()
251		if runner.RepoID != 0 {
252			jobCond = builder.Eq{"repo_id": runner.RepoID}
253		} else if runner.OwnerID != 0 {
254			jobCond = builder.In("repo_id", builder.Select("`repository`.id").From("repository").
255				Join("INNER", "repo_unit", "`repository`.id = `repo_unit`.repo_id").
256				Where(builder.Eq{"`repository`.owner_id": runner.OwnerID, "`repo_unit`.type": unit.TypeActions}))
257		}
258		baseCond := builder.Eq{"task_id": 0, "status": StatusWaiting, "is_reusable_caller": false}.And(jobCond)
259	
260		// TODO: a more efficient way to filter labels
261		log.Trace("runner labels: %v", runner.AgentLabels)
262	
263		// Page through the waiting jobs oldest-first instead of loading the whole backlog into memory on every poll.
264		// Keyset pagination on (updated, id) is safe under concurrent claims:
265		// updated only moves forward, so the advancing cursor never skips a still-waiting job even as claimed jobs drop out.
266		var cursorUpdated timeutil.TimeStamp
267		var cursorID int64
268		for {
269			cond := baseCond
270			if cursorID > 0 {
271				cond = cond.And(builder.Or(
272					builder.Gt{"updated": cursorUpdated},
273					builder.And(builder.Eq{"updated": cursorUpdated}, builder.Gt{"id": cursorID}),
274				))
275			}
276	
277			var jobs []*ActionRunJob
278			if err := e.Where(cond).Asc("updated", "id").Limit(pickTaskBatchSize).Find(&jobs); err != nil {
279				return nil, false, err
280			}
281	
282			for _, v := range jobs {
283				if !runner.CanMatchLabels(v.RunsOn) {
284					continue
285				}
286				task, ok, err := claimJobForRunner(ctx, runner, v)
287				if err != nil {
288					return nil, false, err
289				}
290				if ok {
291					return task, true, nil
292				}
293				// Another runner claimed this job concurrently; try the next one.
294			}
295	
296			// A short page means no waiting jobs remain beyond it.
297			if len(jobs) < pickTaskBatchSize {
298				return nil, false, nil
299			}
300			last := jobs[len(jobs)-1]
301			cursorUpdated, cursorID = last.Updated, last.ID
302		}
303	}
304	
305	// claimJobForRunner attempts to atomically claim job for runner inside its own
306	// transaction. Returns (task, true, nil) on success, or (nil, false, nil) when
307	// another runner wins the optimistic-lock race (the caller should try the next
308	// candidate job).
309	func claimJobForRunner(ctx context.Context, runner *ActionRunner, job *ActionRunJob) (*ActionTask, bool, error) {
310		var resultTask *ActionTask
311	
312		err := db.WithTx(ctx, func(ctx context.Context) error {
313			e := db.GetEngine(ctx)
314	
315			if err := job.LoadAttributes(ctx); err != nil {
316				return err
317			}
318	
319			now := timeutil.TimeStampNow()
320			job.Started = now
321			job.Status = StatusRunning
322	
323			task := &ActionTask{
324				JobID:             job.ID,
325				Attempt:           job.Attempt,
326				RunnerID:          runner.ID,
327				Started:           now,
328				Status:            StatusRunning,
329				RepoID:            job.RepoID,
330				OwnerID:           job.OwnerID,
331				CommitSHA:         job.CommitSHA,
332				IsForkPullRequest: job.IsForkPullRequest,
333			}
334			task.GenerateAndFillToken()
335	
336			workflowJob, err := job.ParseJob()
337			if err != nil {
338				return fmt.Errorf("load job %d: %w", job.ID, err)
339			}
340	
341			if _, err := e.Insert(task); err != nil {
342				return err
343			}
344	
345			task.LogFilename = logFileName(job.Run.Repo.FullName(), task.ID)
346			if err := UpdateTask(ctx, task, "log_filename"); err != nil {
347				return err
348			}
349	
350			if len(workflowJob.Steps) > 0 {
351				steps := make([]*ActionTaskStep, len(workflowJob.Steps))
352				for i, v := range workflowJob.Steps {
353					steps[i] = &ActionTaskStep{
354						Name:   makeTaskStepDisplayName(v, 255),
355						TaskID: task.ID,
356						Index:  int64(i),
357						RepoID: task.RepoID,
358						Status: StatusWaiting,
359					}
360				}
361				if _, err := e.Insert(steps); err != nil {
362					return err
363				}
364				task.Steps = steps
365			}
366	
367			job.TaskID = task.ID
368			n, err := UpdateRunJob(ctx, job, builder.And(builder.Eq{"task_id": 0}, builder.Eq{"status": StatusWaiting}))
369			if err != nil {
370				return err
371			}
372			if n != 1 {
373				// Another runner claimed this job between our scan and this update;
374				// signal the outer loop to move on without treating this as an error.
375				return errJobAlreadyClaimed
376			}
377	
378			task.Job = job
379			resultTask = task
380			return nil
381		})
382	
383		if errors.Is(err, errJobAlreadyClaimed) {
384			return nil, false, nil
385		}
386		if err != nil {
387			return nil, false, err
388		}
389		return resultTask, true, nil
390	}
391	
392	// ReleaseTaskForRunner reverts a freshly-claimed but undelivered task: it deletes
393	// the task together with its steps and returns the job to the waiting queue. It is
394	// used when assembling the runner response fails after the job was already claimed,
395	// so the job is not stranded in running state with no runner ever executing it.
396	func ReleaseTaskForRunner(ctx context.Context, task *ActionTask) error {
397		return db.WithTx(ctx, func(ctx context.Context) error {
398			e := db.GetEngine(ctx)
399	
400			job, err := GetRunJobByRepoAndID(ctx, task.RepoID, task.JobID)
401			if err != nil {
402				return err
403			}
404	
405			job.Status = StatusWaiting
406			job.Started = 0
407			job.TaskID = 0
408			// Guard on task_id and status so we only release while the job still
409			// references this task and has not progressed past running.
410			n, err := UpdateRunJob(ctx, job, builder.Eq{"task_id": task.ID, "status": StatusRunning}, "status", "started", "task_id")
411			if err != nil {
412				return err
413			}
414			if n != 1 {
415				return fmt.Errorf("release task %d: job %d no longer references it", task.ID, task.JobID)
416			}
417	
418			if _, err := e.Delete(&ActionTaskStep{TaskID: task.ID}); err != nil {
419				return err
420			}
421			if _, err := e.ID(task.ID).Delete(&ActionTask{}); err != nil {
422				return err
423			}
424			return nil
425		})
426	}
427	
428	func UpdateTask(ctx context.Context, task *ActionTask, cols ...string) error {
429		sess := db.GetEngine(ctx).ID(task.ID)
430		if len(cols) > 0 {
431			sess.Cols(cols...)
432		}
433		_, err := sess.Update(task)
434	
435		// Automatically delete the ephemeral runner if the task is done
436		if err == nil && task.Status.IsDone() && util.SliceContainsString(cols, "status") {
437			return DeleteEphemeralRunner(ctx, task.RunnerID)
438		}
439		return err
440	}
441	
442	func getRunIDByTaskID(ctx context.Context, taskID int64) (runID int64, _ error) {
443		if has, err := db.GetEngine(ctx).Cols("action_run_job.run_id").
444			Table("action_task").
445			Join("INNER", "action_run_job", "action_run_job.id = action_task.job_id").
446			Where(builder.Eq{"action_task.id": taskID}).Get(&runID); err != nil {
447			return runID, err
448		} else if !has {
449			return runID, util.ErrNotExist
450		}
451		return runID, nil
452	}
453	
454	// UpdateTaskByState updates the task by the state.
455	// It will always update the task if the state is not final, even there is no change.
456	// So it will update ActionTask.Updated to avoid the task being judged as a zombie task.
457	func UpdateTaskByState(ctx context.Context, runnerID int64, state *runnerv1.TaskState) (*ActionTask, error) {
458		stepStates := map[int64]*runnerv1.StepState{}
459		for _, v := range state.Steps {
460			stepStates[v.Id] = v
461		}
462	
463		// Only one request can update the task because the final state needs to be calculated with all job states.
464		// Otherwise, concurrent requests with transaction will make the SQL read stale job state and result in wrong final state.
465		taskID := state.Id
466		runID, err := getRunIDByTaskID(ctx, taskID)
467		if err != nil {
468			return nil, err
469		}
470		task := &ActionTask{}
471		err = globallock.LockAndDo(ctx, fmt.Sprintf("UpdateTaskByState-run-%d", runID), func(ctx context.Context) error {
472			if has, err := db.GetEngine(ctx).ID(taskID).Get(task); err != nil {
473				return err
474			} else if !has {
475				return util.ErrNotExist
476			} else if runnerID != task.RunnerID {
477				return errors.New("invalid runner for task")
478			}
479	
480			if task.Status.IsDone() {
481				// the state is final, do nothing
482				return nil
483			}
484	
485			// state.Result is not unspecified means the task is finished
486			if state.Result != runnerv1.Result_RESULT_UNSPECIFIED {
487				if task.Status == StatusCancelling {
488					// The runner may report SUCCESS/FAILURE for the cleanup phase; preserve user intent.
489					task.Status = StatusCancelled
490				} else {
491					task.Status = StatusFromResult(state.Result)
492				}
493				task.Stopped = timeutil.TimeStamp(state.StoppedAt.AsTime().Unix())
494				if err := UpdateTask(ctx, task, "status", "stopped"); err != nil {
495					return err
496				}
497				if _, err := UpdateRunJob(ctx, &ActionRunJob{
498					ID:      task.JobID,
499					RepoID:  task.RepoID,
500					Status:  task.Status,
501					Stopped: task.Stopped,
502				}, nil, "status", "stopped"); err != nil {
503					return err
504				}
505			} else {
506				// Force update ActionTask.Updated to avoid the task being judged as a zombie task
507				task.Updated = timeutil.TimeStampNow()
508				if err := UpdateTask(ctx, task, "updated"); err != nil {
509					return err
510				}
511			}
512	
513			if err := task.LoadAttributes(ctx); err != nil {
514				return err
515			}
516	
517			for _, step := range task.Steps {
518				var result runnerv1.Result
519				if v, ok := stepStates[step.Index]; ok {
520					result = v.Result
521					step.LogIndex = v.LogIndex
522					step.LogLength = v.LogLength
523					step.Started = convertTimestamp(v.StartedAt)
524					step.Stopped = convertTimestamp(v.StoppedAt)
525				}
526				if result != runnerv1.Result_RESULT_UNSPECIFIED {
527					step.Status = StatusFromResult(result)
528				} else if step.Started != 0 {
529					step.Status = StatusRunning
530				}
531				if _, err := db.GetEngine(ctx).ID(step.ID).Update(step); err != nil {
532					return err
533				}
534			}
535			return nil
536		})
537		return task, err
538	}
539	
540	func StopTask(ctx context.Context, taskID int64, status Status) error {
541		if !status.IsDone() && status != StatusCancelling {
542			return fmt.Errorf("cannot stop task with status %v", status)
543		}
544		e := db.GetEngine(ctx)
545	
546		task := &ActionTask{}
547		if has, err := e.ID(taskID).Get(task); err != nil {
548			return err
549		} else if !has {
550			return util.ErrNotExist
551		}
552		if task.Status.IsDone() {
553			return nil
554		}
555	
556		now := timeutil.TimeStampNow()
557		if status == StatusCancelling {
558			runner, err := GetRunnerByID(ctx, task.RunnerID)
559			if err != nil {
560				if !errors.Is(err, util.ErrNotExist) {
561					return err
562				}
563				status = StatusCancelled
564			} else if !runner.HasCancellingSupport {
565				status = StatusCancelled
566			}
567		}
568	
569		if status == StatusCancelling {
570			task.Status = StatusCancelling
571	
572			if _, err := UpdateRunJob(ctx, &ActionRunJob{
573				ID:     task.JobID,
574				RepoID: task.RepoID,
575				Status: StatusCancelling,
576			}, nil, "status"); err != nil {
577				return err
578			}
579	
580			return UpdateTask(ctx, task, "status")
581		}
582	
583		task.Status = status
584		task.Stopped = now
585		if _, err := UpdateRunJob(ctx, &ActionRunJob{
586			ID:      task.JobID,
587			RepoID:  task.RepoID,
588			Status:  task.Status,
589			Stopped: task.Stopped,
590		}, nil); err != nil {
591			return err
592		}
593	
594		if err := UpdateTask(ctx, task, "status", "stopped"); err != nil {
595			return err
596		}
597	
598		if err := task.LoadAttributes(ctx); err != nil {
599			return err
600		}
601	
602		for _, step := range task.Steps {
603			if !step.Status.IsDone() {
604				step.Status = status
605				if step.Started == 0 {
606					step.Started = now
607				}
608				step.Stopped = now
609			}
610			if _, err := e.ID(step.ID).Update(step); err != nil {
611				return err
612			}
613		}
614	
615		return nil
616	}
617	
618	func FindOldTasksToExpire(ctx context.Context, olderThan timeutil.TimeStamp, limit int) ([]*ActionTask, error) {
619		e := db.GetEngine(ctx)
620	
621		tasks := make([]*ActionTask, 0, limit)
622		// Check "stopped > 0" to avoid deleting tasks that are still running
623		return tasks, e.Where("stopped > 0 AND stopped < ? AND log_expired = ?", olderThan, false).
624			Limit(limit).
625			Find(&tasks)
626	}
627	
628	func convertTimestamp(timestamp *timestamppb.Timestamp) timeutil.TimeStamp {
629		if timestamp.GetSeconds() == 0 && timestamp.GetNanos() == 0 {
630			return timeutil.TimeStamp(0)
631		}
632		return timeutil.TimeStamp(timestamp.AsTime().Unix())
633	}
634	
635	func logFileName(repoFullName string, taskID int64) string {
636		ret := fmt.Sprintf("%s/%02x/%d.log", repoFullName, taskID%256, taskID)
637	
638		if setting.Actions.LogCompression.IsZstd() {
639			ret += ".zst"
640		}
641	
642		return ret
643	}
644	
645	func getTaskIDFromCache(token string) int64 {
646		if successfulTokenTaskCache == nil {
647			return 0
648		}
649		tInterface, ok := successfulTokenTaskCache.Get(token)
650		if !ok {
651			return 0
652		}
653		t, ok := tInterface.(int64)
654		if !ok {
655			return 0
656		}
657		return t
658	}
