126	func applyDeclareRequestToRunner(runner *actions_model.ActionRunner, req declareRequest) []string {
127		runner.AgentLabels = req.GetLabels()
128		runner.Version = req.GetVersion()
129	
130		cols := []string{"agent_labels", "version"}
131		hasCancellingSupport := slices.Contains(req.GetCapabilities(), runnerCapabilityCancelling)
132		if runner.HasCancellingSupport != hasCancellingSupport {
133			runner.HasCancellingSupport = hasCancellingSupport
134			cols = append(cols, "has_cancelling_support")
135		}
136	
137		return cols
