428	func UpdateTask(ctx context.Context, task *ActionTask, cols ...string) error {
429		sess := db.GetEngine(ctx).ID(task.ID)
430		if len(cols) > 0 {
431			sess.Cols(cols...)
432		}
433		_, err := sess.Update(task)
434	
435		// Automatically delete the ephemeral runner if the task is done
436		if err == nil && task.Status.IsDone() && util.SliceContainsString(cols, "status") {
437			return DeleteEphemeralRunner(ctx, task.RunnerID)
438		}
439		return err
440	}
