454	// UpdateTaskByState updates the task by the state.
455	// It will always update the task if the state is not final, even there is no change.
456	// So it will update ActionTask.Updated to avoid the task being judged as a zombie task.
457	func UpdateTaskByState(ctx context.Context, runnerID int64, state *runnerv1.TaskState) (*ActionTask, error) {
458		stepStates := map[int64]*runnerv1.StepState{}
459		for _, v := range state.Steps {
460			stepStates[v.Id] = v
461		}
462	
463		// Only one request can update the task because the final state needs to be calculated with all job states.
464		// Otherwise, concurrent requests with transaction will make the SQL read stale job state and result in wrong final state.
465		taskID := state.Id
466		runID, err := getRunIDByTaskID(ctx, taskID)
467		if err != nil {
468			return nil, err
469		}
470		task := &ActionTask{}
471		err = globallock.LockAndDo(ctx, fmt.Sprintf("UpdateTaskByState-run-%d", runID), func(ctx context.Context) error {
472			if has, err := db.GetEngine(ctx).ID(taskID).Get(task); err != nil {
473				return err
474			} else if !has {
475				return util.ErrNotExist
476			} else if runnerID != task.RunnerID {
477				return errors.New("invalid runner for task")
478			}
479	
480			if task.Status.IsDone() {
481				// the state is final, do nothing
482				return nil
483			}
484	
485			// state.Result is not unspecified means the task is finished
486			if state.Result != runnerv1.Result_RESULT_UNSPECIFIED {
487				if task.Status == StatusCancelling {
488					// The runner may report SUCCESS/FAILURE for the cleanup phase; preserve user intent.
489					task.Status = StatusCancelled
490				} else {
491					task.Status = StatusFromResult(state.Result)
492				}
493				task.Stopped = timeutil.TimeStamp(state.StoppedAt.AsTime().Unix())
494				if err := UpdateTask(ctx, task, "status", "stopped"); err != nil {
495					return err
496				}
497				if _, err := UpdateRunJob(ctx, &ActionRunJob{
498					ID:      task.JobID,
499					RepoID:  task.RepoID,
500					Status:  task.Status,
501					Stopped: task.Stopped,
502				}, nil, "status", "stopped"); err != nil {
503					return err
504				}
505			} else {
506				// Force update ActionTask.Updated to avoid the task being judged as a zombie task
507				task.Updated = timeutil.TimeStampNow()
508				if err := UpdateTask(ctx, task, "updated"); err != nil {
509					return err
510				}
511			}
512	
513			if err := task.LoadAttributes(ctx); err != nil {
514				return err
515			}
516	
517			for _, step := range task.Steps {
518				var result runnerv1.Result
519				if v, ok := stepStates[step.Index]; ok {
520					result = v.Result
521					step.LogIndex = v.LogIndex
522					step.LogLength = v.LogLength
523					step.Started = convertTimestamp(v.StartedAt)
524					step.Stopped = convertTimestamp(v.StoppedAt)
525				}
526				if result != runnerv1.Result_RESULT_UNSPECIFIED {
527					step.Status = StatusFromResult(result)
528				} else if step.Started != 0 {
529					step.Status = StatusRunning
530				}
531				if _, err := db.GetEngine(ctx).ID(step.ID).Update(step); err != nil {
532					return err
533				}
534			}
535			return nil
536		})
537		return task, err
538	}
