178	// ParseJob parses the job structure from the ActionRunJob.WorkflowPayload
179	func (job *ActionRunJob) ParseJob() (*jobparser.Job, error) {
180		// job.WorkflowPayload is a SingleWorkflow created from an ActionRun's workflow, which exactly contains this job's YAML definition.
181		// Ideally it shouldn't be called "Workflow", it is just a job with global workflow fields + trigger
182		parsedWorkflows, err := jobparser.Parse(job.WorkflowPayload)
183		if err != nil {
184			return nil, fmt.Errorf("job %d single workflow: unable to parse: %w", job.ID, err)
185		} else if len(parsedWorkflows) != 1 {
186			return nil, fmt.Errorf("job %d single workflow: not single workflow", job.ID)
187		}
188		_, workflowJob := parsedWorkflows[0].Job()
189		if workflowJob == nil {
190			// it shouldn't happen, and since the callers don't check nil, so return an error instead of nil
191			return nil, util.ErrorWrap(util.ErrNotExist, "job %d single workflow: payload doesn't contain a job", job.ID)
192		}
193		return workflowJob, nil
194	}
