269	// GetPriorAttemptChildrenByParent returns the children of the most recent prior attempt where
270	// the parent (identified by parentAttemptJobID) actually had children, indexed by child JobID then child Name.
271	// Returns (nil, nil) when no such attempt exists.
272	// The (JobID, Name) key disambiguates both reusable-workflow subtrees and matrix-expanded instances (whose Name carries the matrix suffix).
273	func GetPriorAttemptChildrenByParent(ctx context.Context, runID, currentAttemptID, parentAttemptJobID int64) (map[string]map[string]*ActionRunJob, error) {
274		// query every prior caller row sharing this AttemptJobID, newest first.
275		var priorCallers []*ActionRunJob
276		if err := db.GetEngine(ctx).
277			Where("run_id = ? AND attempt_job_id = ? AND run_attempt_id < ?", runID, parentAttemptJobID, currentAttemptID).
278			Desc("run_attempt_id").
279			Find(&priorCallers); err != nil {
280			return nil, fmt.Errorf("find prior callers: %w", err)
281		}
282		if len(priorCallers) == 0 {
283			return nil, nil //nolint:nilnil // caller is brand new in this attempt
284		}
285	
286		// query for every child of every prior caller
287		callerIDs := make([]int64, len(priorCallers))
288		for i, c := range priorCallers {
289			callerIDs[i] = c.ID
290		}
291		var allChildren []*ActionRunJob
292		if err := db.GetEngine(ctx).
293			Where("run_id = ?", runID).
294			In("parent_job_id", callerIDs).
295			Find(&allChildren); err != nil {
296			return nil, fmt.Errorf("find prior children: %w", err)
297		}
298	
299		childrenByCallerID := make(map[int64][]*ActionRunJob, len(callerIDs))
300		for _, c := range allChildren {
301			childrenByCallerID[c.ParentJobID] = append(childrenByCallerID[c.ParentJobID], c)
302		}
303	
304		// Walk priorCallers in run_attempt_id-desc order and return the children of the first caller that actually had any.
305		// Skipped attempts (caller exists but no children) are bypassed.
306		for _, caller := range priorCallers {
307			children := childrenByCallerID[caller.ID]
308			if len(children) == 0 {
309				continue
310			}
311			out := make(map[string]map[string]*ActionRunJob)
312			for _, c := range children {
313				if out[c.JobID] == nil {
314					out[c.JobID] = make(map[string]*ActionRunJob)
315				}
316				out[c.JobID][c.Name] = c
317			}
318			return out, nil
319		}
320	
321		return nil, nil //nolint:nilnil // every prior attempt skipped this caller
322	}
