336	// CollectAllDescendantJobs returns every job in `allJobs` that lives under parent's subtree (recursively), excluding `parent` itself
337	func CollectAllDescendantJobs(parent *ActionRunJob, allJobs []*ActionRunJob) []*ActionRunJob {
338		parents := map[int64]bool{parent.ID: true}
339		for {
340			grew := false
341			for _, j := range allJobs {
342				if j.ParentJobID == 0 {
343					continue
344				}
345				if parents[j.ParentJobID] && !parents[j.ID] {
346					parents[j.ID] = true
347					grew = true
348				}
349			}
350			if !grew {
351				break
352			}
353		}
354		out := make([]*ActionRunJob, 0)
355		for _, j := range allJobs {
356			if j.ID == parent.ID || !parents[j.ID] {
357				continue
358			}
359			out = append(out, j)
360		}
361		return out
362	}
