372	func UpdateRunJob(ctx context.Context, job *ActionRunJob, cond builder.Cond, cols ...string) (int64, error) {
373		e := db.GetEngine(ctx)
374	
375		sess := e.ID(job.ID)
376		if len(cols) > 0 {
377			sess.Cols(cols...)
378		}
379	
380		if cond != nil {
381			sess.Where(cond)
382		}
383	
384		affected, err := sess.Update(job)
385		if err != nil {
386			return 0, err
387		}
388	
389		// xorm's Update writes only non-zero fields when cols is empty, so a zero job.Status
390		// with empty cols means status isn't actually being persisted — skip aggregation.
391		statusUpdated := slices.Contains(cols, "status") || (len(cols) == 0 && job.Status != 0)
392		if affected == 0 || !statusUpdated {
393			return affected, nil
394		}
395	
396		if job.RunID == 0 {
397			var err error
398			if job, err = GetRunJobByRepoAndID(ctx, job.RepoID, job.ID); err != nil {
399				return 0, err
400			}
401		}
402	
403		// Reusable workflow caller jobs are never picked up by runners, so they don't need a task-version bump.
404		if statusUpdated && !job.IsReusableCaller {
405			switch {
406			case job.Status.IsWaiting():
407				// A job returning to the waiting queue is work a runner can pick up, so bump the
408				// version to wake idle runners whose tasksVersion already equals latestVersion.
409				if err := IncreaseTaskVersion(ctx, job.OwnerID, job.RepoID); err != nil {
410					return 0, err
411				}
412			case job.Status.IsDone():
413				// When a job finishes, bump the version so that idle runners — whose
414				// tasksVersion already equals the current latestVersion — learn that
415				// remaining waiting jobs are still available and attempt PickTask again.
416				// Without this bump, runners that completed their tasks would see
417				// tasksVersion==latestVersion and skip PickTask, leaving the other jobs
418				// permanently unassigned until the version changes for another reason.
419				// Only bump when waiting work actually remains for this repo, otherwise
420				// every job completion would needlessly bump the global version and wake
421				// every idle runner instance-wide for nothing.
422				hasWaiting, err := hasWaitingJobsToPick(ctx, job.RepoID)
423				if err != nil {
424					return 0, err
425				}
426				if hasWaiting {
427					if err := IncreaseTaskVersion(ctx, job.OwnerID, job.RepoID); err != nil {
428						return 0, err
429					}
430				}
431			}
432		}
433	
434		if statusUpdated && job.ParentJobID > 0 {
435			// Reusable workflow caller's children cascade their status changes upward to the parent caller.
436			parent, err := GetRunJobByRunAndID(ctx, job.RunID, job.ParentJobID)
437			if err != nil {
438				return affected, fmt.Errorf("load parent caller %d: %w", job.ParentJobID, err)
439			}
440			return affected, RefreshReusableCallerStatus(ctx, parent)
441		}
442	
443		{
444			// Other goroutines may aggregate the status of the attempt/run and update it too.
445			// So we need to load the current jobs before updating the aggregate state.
446			if job.RunAttemptID > 0 {
447				attempt, err := GetRunAttemptByRepoAndID(ctx, job.RepoID, job.RunAttemptID)
448				if err != nil {
449					return 0, err
450				}
451				jobs, err := GetRunJobsByRunAndAttemptID(ctx, job.RunID, job.RunAttemptID)
452				if err != nil {
453					return 0, err
454				}
455				attempt.Status = AggregateJobStatus(jobs)
456				if attempt.Started.IsZero() && attempt.Status.IsRunning() {
457					attempt.Started = timeutil.TimeStampNow()
458				}
459				if attempt.Stopped.IsZero() && attempt.Status.IsDone() {
460					attempt.Stopped = timeutil.TimeStampNow()
461				}
462				if err := UpdateRunAttempt(ctx, attempt, "status", "started", "stopped"); err != nil {
463					return 0, fmt.Errorf("update run attempt %d: %w", attempt.ID, err)
464				}
465			} else {
466				// TODO: Remove this fallback in the future.
467				// Legacy fallback: jobs created before migration v331 have RunAttemptID=0 and are NOT backfilled.
468				// This path keeps those runs' status consistent when their jobs finish, including:
469				//   - jobs created before migration v331 and complete on the new version starts
470				//   - zombie/abandoned cleanup cron tasks that call UpdateRunJob on legacy jobs
471				run, err := GetRunByRepoAndID(ctx, job.RepoID, job.RunID)
472				if err != nil {
473					return 0, err
474				}
475				jobs, err := GetLatestAttemptJobsByRepoAndRunID(ctx, job.RepoID, job.RunID)
476				if err != nil {
477					return 0, err
478				}
479				run.Status = AggregateJobStatus(jobs)
480				if run.Started.IsZero() && run.Status.IsRunning() {
481					run.Started = timeutil.TimeStampNow()
482				}
483				if run.Stopped.IsZero() && run.Status.IsDone() {
484					run.Stopped = timeutil.TimeStampNow()
485				}
486				if err := UpdateRun(ctx, run, "status", "started", "stopped"); err != nil {
487					return 0, fmt.Errorf("update run %d: %w", run.ID, err)
488				}
489			}
490		}
491	
492		return affected, nil
493	}
494	
495	// RefreshReusableCallerStatus recomputes a reusable workflow caller's Status, Started and Stopped from its current direct children and persists the change.
496	// No-op if caller is not a reusable caller.
497	//
498	// Concurrency: two sibling children finishing at roughly the same time can each invoke this for the same parent caller.
499	// No row-level lock is taken because AggregateJobStatus is a pure function of the children's statuses (order-independent), so racing callers arrive at the same Status.
500	func RefreshReusableCallerStatus(ctx context.Context, caller *ActionRunJob) error {
501		if !caller.IsReusableCaller {
502			return nil
503		}
504		children, err := GetDirectChildJobsByParent(ctx, caller)
505		if err != nil {
506			return err
507		}
508	
509		newStatus := AggregateJobStatus(children)
510		cols := make([]string, 0, 3)
511		if caller.Status != newStatus {
512			caller.Status = newStatus
513			cols = append(cols, "status")
514		}
515		if newStatus != StatusSkipped {
516			now := timeutil.TimeStampNow()
517			if caller.Started.IsZero() && newStatus == StatusRunning {
518				caller.Started = now
519				cols = append(cols, "started")
520			}
521			if caller.Stopped.IsZero() && newStatus.IsDone() {
522				caller.Stopped = now
523				cols = append(cols, "stopped")
524			}
525		}
526		if len(cols) == 0 {
527			return nil
528		}
529		_, err = UpdateRunJob(ctx, caller, nil, cols...)
530		return err
531	}
532	
533	func AggregateJobStatus(jobs []*ActionRunJob) Status {
534		allSuccessOrSkipped := len(jobs) != 0
535		allSkipped := len(jobs) != 0
536		var hasFailure, hasCancelled, hasCancelling, hasWaiting, hasRunning, hasBlocked bool
537		for _, job := range jobs {
538			// A failed job with continue-on-error:true does not fail the workflow run.
539			// It counts as a "continued failure" and is treated like success for aggregation.
540			isContinuedFailure := job.ContinueOnError && job.Status == StatusFailure
541			allSuccessOrSkipped = allSuccessOrSkipped && (job.Status == StatusSuccess || job.Status == StatusSkipped || isContinuedFailure)
542			allSkipped = allSkipped && job.Status == StatusSkipped
543			hasFailure = hasFailure || (job.Status == StatusFailure && !job.ContinueOnError)
544			hasCancelled = hasCancelled || job.Status == StatusCancelled
545			hasCancelling = hasCancelling || job.Status == StatusCancelling
546			hasWaiting = hasWaiting || job.Status == StatusWaiting
547			hasRunning = hasRunning || job.Status == StatusRunning
548			hasBlocked = hasBlocked || job.Status == StatusBlocked
549		}
550		switch {
551		case allSkipped:
552			return StatusSkipped
553		case allSuccessOrSkipped:
554			return StatusSuccess
555		case hasCancelling:
556			return StatusCancelling
557		case hasRunning:
558			return StatusRunning
559		case hasWaiting:
560			return StatusWaiting
561		case hasBlocked:
562			// Blocked is still a pending state, so it should outrank terminal
563			// statuses like cancelled/failure when no job is waiting or running.
564			return StatusBlocked
565		case hasCancelled:
566			return StatusCancelled
567		case hasFailure:
568			return StatusFailure
569		default:
570			return StatusUnknown // it shouldn't happen
571		}
572	}
