324	// GetDirectChildJobsByParent returns the direct child jobs of a parent job (e.g. a reusable workflow caller).
325	func GetDirectChildJobsByParent(ctx context.Context, parentJob *ActionRunJob) (ActionJobList, error) {
326		var jobs []*ActionRunJob
327		if err := db.GetEngine(ctx).
328			Where("run_id=? AND parent_job_id=?", parentJob.RunID, parentJob.ID).
329			OrderBy("id").
330			Find(&jobs); err != nil {
331			return nil, err
332		}
333		return jobs, nil
