32		Title             string
33		RepoID            int64                  `xorm:"unique(repo_index)"`
34		Repo              *repo_model.Repository `xorm:"-"`
35		OwnerID           int64                  `xorm:"index"`
36		WorkflowID        string                 `xorm:"index"`                    // the name of workflow file
37		Index             int64                  `xorm:"index unique(repo_index)"` // a unique number for each run of a repository
38		TriggerUserID     int64                  `xorm:"index"`
39		TriggerUser       *user_model.User       `xorm:"-"`
40		ScheduleID        int64
41		Ref               string `xorm:"index"` // the commit/tag/… that caused the run
42		IsRefDeleted      bool   `xorm:"-"`
43		CommitSHA         string
44		IsForkPullRequest bool                         // If this is triggered by a PR from a forked repository or an untrusted user, we need to check if it is approved and limit permissions when running the workflow.
45		NeedApproval      bool                         // may need approval if it's a fork pull request
46		ApprovedBy        int64                        `xorm:"index"` // who approved
47		Event             webhook_module.HookEventType // the webhook event that causes the workflow to run
48		EventPayload      string                       `xorm:"LONGTEXT"`
49		TriggerEvent      string                       // the trigger event defined in the `on` configuration of the triggered workflow
50		Status            Status                       `xorm:"index"`
