52		RawConcurrency    string                       // raw concurrency
53	
54		// WorkflowRepoID/WorkflowCommitSHA record the (repo, commit) the run's workflow file content came from.
55		// Always filled (repo-level run = the repo itself; scoped run = the source repo).
56		WorkflowRepoID    int64  `xorm:"NOT NULL DEFAULT 0"`
57		WorkflowCommitSHA string `xorm:"VARCHAR(64) NOT NULL DEFAULT ''"`
58	
59		IsScopedRun bool `xorm:"NOT NULL DEFAULT false"` // IsScopedRun explicitly classifies scoped runs.
60	
61		// Started and Stopped are identical to the latest attempt after ActionRunAttempt was introduced.
62		// When a rerun creates a new latest attempt, they are reset until the new attempt starts and stops.
63		Started timeutil.TimeStamp
64		Stopped timeutil.TimeStamp
