66		// PreviousDuration is kept only for legacy runs created before ActionRunAttempt existed.
67		// New runs and reruns no longer update this field and use attempt-scoped durations instead.
68		PreviousDuration time.Duration
69	
70		LatestAttemptID int64 `xorm:"index NOT NULL DEFAULT 0"`
71	
72		Created timeutil.TimeStamp `xorm:"created"`
73		Updated timeutil.TimeStamp `xorm:"updated"`
