270	/*
271	LogIndexes is the index for mapping log line number to buffer offset.
272	Because it uses varint encoding, it is impossible to predict its size.
273	But we can make a simple estimate with an assumption that each log line has 200 byte, then:
274	| lines     | file size           | index size         |
275	|-----------|---------------------|--------------------|
276	| 100       | 20 KiB(20000)       | 258 B(258)         |
277	| 1000      | 195 KiB(200000)     | 2.9 KiB(2958)      |
278	| 10000     | 1.9 MiB(2000000)    | 34 KiB(34715)      |
279	| 100000    | 19 MiB(20000000)    | 386 KiB(394715)    |
280	| 1000000   | 191 MiB(200000000)  | 4.1 MiB(4323626)   |
281	| 10000000  | 1.9 GiB(2000000000) | 47 MiB(49323626)   |
282	| 100000000 | 19 GiB(20000000000) | 490 MiB(513424280) |
283	*/
284	type LogIndexes []int64
285	
286	func (indexes *LogIndexes) FromDB(b []byte) error {
287		reader := bytes.NewReader(b)
288		for {
289			v, err := binary.ReadVarint(reader)
290			if err != nil {
291				if errors.Is(err, io.EOF) {
292					return nil
293				}
294				return fmt.Errorf("binary ReadVarint: %w", err)
295			}
296			*indexes = append(*indexes, v)
297		}
298	}
299	
300	func (indexes *LogIndexes) ToDB() ([]byte, error) {
301		buf, i := make([]byte, binary.MaxVarintLen64*len(*indexes)), 0
302		for _, v := range *indexes {
303			n := binary.PutVarint(buf[i:], v)
304			i += n
305		}
306		return buf[:i], nil
307	}
308	
309	var timeSince = time.Since
310	
311	// calculateDuration computes wall time for a run, job, task, or step. When status is terminal
312	// but stopped is missing or inconsistent with started, fallbackEnd (typically the row Updated
313	// time) is used so duration still reflects approximate elapsed time instead of 0 or a negative.
314	func calculateDuration(started, stopped timeutil.TimeStamp, status Status, fallbackEnd timeutil.TimeStamp) time.Duration {
315		if started == 0 {
316			return 0
317		}
318		s := started.AsTime()
319		if status.IsDone() {
320			end := stopped
321			if stopped.IsZero() || stopped < started {
322				if !fallbackEnd.IsZero() && fallbackEnd >= started {
323					end = fallbackEnd
324				} else {
325					log.Trace("actions: invalid duration timestamps (started=%d, stopped=%d, fallbackEnd=%d, status=%s)", started, stopped, fallbackEnd, status)
326					return 0
327				}
328			}
329			return end.AsTime().Sub(s)
330		}
331		return timeSince(s).Truncate(time.Second)
332	}
