334	// best effort function to convert an action schedule to action run, to be used in GenerateGiteaContext
335	func (s *ActionSchedule) ToActionRun() *ActionRun {
336		return &ActionRun{
337			Title:         s.Title,
338			RepoID:        s.RepoID,
339			Repo:          s.Repo,
340			OwnerID:       s.OwnerID,
341			WorkflowID:    s.WorkflowID,
342			TriggerUserID: s.TriggerUserID,
343			TriggerUser:   s.TriggerUser,
344			Ref:           s.Ref,
345			CommitSHA:     s.CommitSHA,
346			Event:         s.Event,
347			EventPayload:  s.EventPayload,
348			Created:       s.Created,
349			Updated:       s.Updated,
350		}
351	}

