234	// checkJobsOfCurrentRunAttempt resolves blocked jobs of the run's latest attempt.
235	func checkJobsOfCurrentRunAttempt(ctx context.Context, run *actions_model.ActionRun) (*jobsCheckResult, error) {
236		jobs, err := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, run.LatestAttemptID)
237		if err != nil {
238			return nil, err
239		}
240		result := &jobsCheckResult{Jobs: jobs}
241	
242		var attempt *actions_model.ActionRunAttempt
243		if run.LatestAttemptID > 0 {
244			attempt, err = actions_model.GetRunAttemptByRepoAndID(ctx, run.RepoID, run.LatestAttemptID)
245			if err != nil {
246				return nil, err
247			}
248		}
249	
250		// The resolver below only considers needs and job-level concurrency, so a run blocked
251		// solely by run-level concurrency would have its jobs unblocked here. checkRunConcurrency
252		// re-evaluates when the holding run finishes.
253		if run.Status.IsBlocked() && attempt != nil {
254			shouldBlock, err := shouldBlockRunByConcurrency(ctx, attempt)
255			if err != nil {
256				return nil, fmt.Errorf("shouldBlockRunByConcurrency: %w", err)
257			}
258			if shouldBlock {
259				return result, nil
260			}
261		}
262		vars, err := actions_model.GetVariablesOfRun(ctx, run)
263		if err != nil {
264			return nil, err
265		}
266		resolver := newJobStatusResolver(jobs, vars)
267	
268		expandedAnyCaller := false
269		if err = db.WithTx(ctx, func(ctx context.Context) error {
270			for _, job := range jobs {
271				job.Run = run
272			}
273	
274			updates := resolver.Resolve(ctx)
275			for _, job := range jobs {
276				status, ok := updates[job.ID]
277				if !ok {
278					continue
279				}
280	
281				if job.IsReusableCaller {
282					switch status {
283					case actions_model.StatusWaiting:
284						if err := expandReusableWorkflowCaller(ctx, run, attempt, job, vars); err != nil {
285							return fmt.Errorf("trigger caller-ready %d: %w", job.ID, err)
286						}
287						// expandReusableWorkflowCaller inserts children as Blocked. They need a follow-up resolver pass.
288						expandedAnyCaller = true
289					case actions_model.StatusSkipped:
290						job.Status = actions_model.StatusSkipped
291						if _, err := actions_model.UpdateRunJob(ctx, job, nil, "status"); err != nil {
292							return err
293						}
294					}
295					continue
296				}
297	
298				// Non-caller: standard status update.
299				job.Status = status
300				if n, err := actions_model.UpdateRunJob(ctx, job, builder.Eq{"status": actions_model.StatusBlocked}, "status"); err != nil {
301					return err
302				} else if n != 1 {
303					return fmt.Errorf("no affected for updating blocked job %v", job.ID)
304				}
305				result.UpdatedJobs = append(result.UpdatedJobs, job)
306			}
307			return nil
308		}); err != nil {
309			return nil, err
310		}
311	
312		if expandedAnyCaller {
313			result.RunIDsToReEmit = append(result.RunIDsToReEmit, run.ID)
314		}
315		result.CancelledJobs = resolver.cancelledJobs
316		return result, nil
317	}
