209	// EvaluateRunConcurrencyFillModel evaluates the expressions in a run-level (workflow) concurrency,
210	// and fills the run attempt model with the evaluated `concurrency.group` and `concurrency.cancel-in-progress` values.
211	// Workflow-level concurrency doesn't depend on the job outputs, so it can always be evaluated if there is no syntax error.
212	// See https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax#concurrency
213	func EvaluateRunConcurrencyFillModel(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, wfRawConcurrency *act_model.RawConcurrency, vars map[string]string, inputs map[string]any) error {
214		if err := run.LoadAttributes(ctx); err != nil {
215			return fmt.Errorf("run LoadAttributes: %w", err)
216		}
217	
218		actionsRunCtx := GenerateGiteaContext(ctx, run, attempt, nil)
219		jobResults := map[string]*jobparser.JobResult{"": {}}
220		if inputs == nil {
221			var err error
222			inputs, err = getWorkflowDispatchInputsFromRun(run)
223			if err != nil {
224				return fmt.Errorf("get inputs: %w", err)
225			}
226		}
227	
228		var err error
229		attempt.ConcurrencyGroup, attempt.ConcurrencyCancel, err = jobparser.EvaluateConcurrency(wfRawConcurrency, "", nil, actionsRunCtx, jobResults, vars, inputs)
230		if err != nil {
231			return fmt.Errorf("evaluate concurrency: %w", err)
232		}
233		return nil
234	}
235	
236	// EvaluateJobConcurrencyFillModel evaluates the expressions in a job-level concurrency,
237	// and fills the job's model fields with `concurrency.group` and `concurrency.cancel-in-progress`.
238	// Job-level concurrency may depend on other job's outputs (via `needs`): `concurrency.group: my-group-${{ needs.job1.outputs.out1 }}`
239	// If the needed jobs haven't been executed yet, this evaluation will also fail.
240	// See https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax#jobsjob_idconcurrency
241	func EvaluateJobConcurrencyFillModel(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, actionRunJob *actions_model.ActionRunJob, vars map[string]string, inputs map[string]any) error {
242		if err := actionRunJob.LoadAttributes(ctx); err != nil {
243			return fmt.Errorf("job LoadAttributes: %w", err)
244		}
245	
246		var rawConcurrency act_model.RawConcurrency
247		if err := yaml.Unmarshal([]byte(actionRunJob.RawConcurrency), &rawConcurrency); err != nil {
248			return fmt.Errorf("unmarshal raw concurrency: %w", err)
249		}
250	
251		actionsJobCtx := GenerateGiteaContext(ctx, run, attempt, actionRunJob)
252	
253		jobResults, err := findJobNeedsAndFillJobResults(ctx, actionRunJob)
254		if err != nil {
255			return fmt.Errorf("find job needs and fill job results: %w", err)
256		}
257	
258		if inputs == nil {
259			var err error
260			inputs, err = getInputsForJob(ctx, run, actionRunJob)
261			if err != nil {
262				return fmt.Errorf("get inputs: %w", err)
263			}
264		}
265	
266		workflowJob, err := actionRunJob.ParseJob()
267		if err != nil {
268			return fmt.Errorf("load job %d: %w", actionRunJob.ID, err)
269		}
270	
271		actionRunJob.ConcurrencyGroup, actionRunJob.ConcurrencyCancel, err = jobparser.EvaluateConcurrency(&rawConcurrency, actionRunJob.JobID, workflowJob, actionsJobCtx, jobResults, vars, inputs)
272		if err != nil {
273			return fmt.Errorf("evaluate concurrency: %w", err)
274		}
275		actionRunJob.IsConcurrencyEvaluated = true
276		return nil
277	}

