 20	// PrepareRunAndInsert prepares a run and inserts it into the database
 21	// It parses the workflow content, evaluates concurrency if needed, and inserts the run and its jobs into the database.
 22	// The title will be cut off at 255 characters if it's longer than 255 characters.
 23	func PrepareRunAndInsert(ctx context.Context, content []byte, run *actions_model.ActionRun, inputsWithDefaults map[string]any) error {
 24		if run.WorkflowRepoID == 0 {
 25			return fmt.Errorf("WorkflowRepoID must be set before insert (repo %d, workflow %q)", run.RepoID, run.WorkflowID)
 26		}
 27	
 28		if err := run.LoadAttributes(ctx); err != nil {
 29			return fmt.Errorf("LoadAttributes: %w", err)
 30		}
 31	
 32		vars, err := actions_model.GetVariablesOfRun(ctx, run)
 33		if err != nil {
 34			return fmt.Errorf("GetVariablesOfRun: %w", err)
 35		}
 36	
 37		wfRawConcurrency, err := jobparser.ReadWorkflowRawConcurrency(content)
 38		if err != nil {
 39			return fmt.Errorf("ReadWorkflowRawConcurrency: %w", err)
 40		}
 41	
 42		if err = InsertRun(ctx, run, content, vars, inputsWithDefaults, wfRawConcurrency); err != nil {
 43			return fmt.Errorf("InsertRun: %w", err)
 44		}
 45	
 46		// Load the newly inserted jobs with all fields from database (the job models in InsertRun are partial, so load again)
 47		allJobs, err := db.Find[actions_model.ActionRunJob](ctx, actions_model.FindRunJobOptions{RunID: run.ID})
 48		if err != nil {
 49			return fmt.Errorf("FindRunJob: %w", err)
 50		}
 51	
 52		CreateCommitStatusForRunJobs(ctx, run, allJobs...)
 53	
 54		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, allJobs)
 55	
 56		return nil
 57	}
