 90			runAttempt := &actions_model.ActionRunAttempt{
 91				RepoID:        run.RepoID,
 92				RunID:         run.ID,
 93				Attempt:       1,
 94				TriggerUserID: run.TriggerUserID,
 95				Status:        actions_model.StatusWaiting,
 96			}
 97	
 98			if wfRawConcurrency != nil {
 99				if err := EvaluateRunConcurrencyFillModel(ctx, run, runAttempt, wfRawConcurrency, vars, inputs); err != nil {
100					return fmt.Errorf("EvaluateRunConcurrencyFillModel: %w", err)
101				}
102				// check run (workflow-level) concurrency
103				var jobsToCancel []*actions_model.ActionRunJob
104				runAttempt.Status, jobsToCancel, err = PrepareToStartRunWithConcurrency(ctx, runAttempt)
105				if err != nil {
106					return err
107				}
108				cancelledConcurrencyJobs = append(cancelledConcurrencyJobs, jobsToCancel...)
109			}
110	
111			if err := db.Insert(ctx, runAttempt); err != nil {
112				return err
113			}
114			run.LatestAttemptID = runAttempt.ID
115	
116			giteaCtx := GenerateGiteaContext(ctx, run, runAttempt, nil)
117			jobs, err := jobparser.Parse(content, jobparser.WithVars(vars), jobparser.WithGitContext(giteaCtx.ToGitHubContext()), jobparser.WithInputs(inputs))
118			if err != nil {
119				return fmt.Errorf("parse workflow: %w", err)
120			}
121			titleChanged := len(jobs) > 0 && jobs[0].RunName != ""
122			if titleChanged {
123				run.Title = util.EllipsisDisplayString(jobs[0].RunName, 255)
124			}
125	
126			cols := []string{"latest_attempt_id"}
127			if titleChanged {
128				cols = append(cols, "title")
129			}
130			if err := actions_model.UpdateRun(ctx, run, cols...); err != nil {
131				return err
132			}
133	
134			runJobs := make([]*actions_model.ActionRunJob, 0, len(jobs))
135			var hasWaitingJobs bool
136	
137			for _, v := range jobs {
138				id, job := v.Job()
139				needs := job.Needs()
140				if err := v.SetJob(id, job.EraseNeeds()); err != nil {
141					return err
142				}
143				payload, _ := v.Marshal()
144	
145				isReusableWorkflowCaller := job.Uses != ""
146				shouldBlockJob := runAttempt.Status == actions_model.StatusBlocked || len(needs) > 0 || run.NeedApproval
147	
148				attemptJobID, err := actions_model.GetNextAttemptJobID(ctx, run.ID)
149				if err != nil {
150					return fmt.Errorf("alloc attempt_job_id: %w", err)
151				}
152	
153				job.Name = util.EllipsisDisplayString(job.Name, 255)
154				runJob := &actions_model.ActionRunJob{
155					RunID:                   run.ID,
156					RunAttemptID:            runAttempt.ID,
157					RepoID:                  run.RepoID,
158					OwnerID:                 run.OwnerID,
159					CommitSHA:               run.CommitSHA,
160					IsForkPullRequest:       run.IsForkPullRequest,
161					Name:                    job.Name,
162					Attempt:                 runAttempt.Attempt,
163					WorkflowPayload:         payload,
164					JobID:                   id,
165					AttemptJobID:            attemptJobID,
166					Needs:                   needs,
167					RunsOn:                  job.RunsOn(),
168					Status:                  util.Iif(shouldBlockJob, actions_model.StatusBlocked, actions_model.StatusWaiting),
169					WorkflowSourceRepoID:    run.WorkflowRepoID,
170					WorkflowSourceCommitSHA: run.WorkflowCommitSHA,
171					ContinueOnError:         job.GetContinueOnError(),
172				}
173				// Parse workflow/job permissions (no clamping here)
174				if perms := ExtractJobPermissionsFromWorkflow(v, job); perms != nil {
175					runJob.TokenPermissions = perms
176				}
177	
178				if isReusableWorkflowCaller {
179					runJob.IsReusableCaller = true
180					runJob.CallUses = job.Uses
181				}
182	
183				// check job concurrency
184				if job.RawConcurrency != nil {
185					rawConcurrency, err := yaml.Marshal(job.RawConcurrency)
186					if err != nil {
187						return fmt.Errorf("marshal raw concurrency: %w", err)
188					}
189					runJob.RawConcurrency = string(rawConcurrency)
190	
191					// do not evaluate job concurrency when it requires `needs`, the jobs with `needs` will be evaluated later by job emitter
192					if len(needs) == 0 {
193						err = EvaluateJobConcurrencyFillModel(ctx, run, runAttempt, runJob, vars, inputs)
194						if err != nil {
195							return fmt.Errorf("evaluate job concurrency: %w", err)
196						}
197					}
198	
199					// If a job needs other jobs ("needs" is not empty), its status is set to StatusBlocked at the entry of the loop
200					// No need to check job concurrency for a blocked job (it will be checked by job emitter later)
201					if runJob.Status == actions_model.StatusWaiting {
202						var jobsToCancel []*actions_model.ActionRunJob
203						runJob.Status, jobsToCancel, err = PrepareToStartJobWithConcurrency(ctx, runJob)
204						if err != nil {
205							return fmt.Errorf("prepare to start job with concurrency: %w", err)
206						}
207						cancelledConcurrencyJobs = append(cancelledConcurrencyJobs, jobsToCancel...)
208					}
209				}
210	
211				// A reusable caller is never dispatched to a runner, so it must not drive the task-version bump.
212				hasWaitingJobs = hasWaitingJobs || (runJob.Status == actions_model.StatusWaiting && !isReusableWorkflowCaller)
213				if err := db.Insert(ctx, runJob); err != nil {
214					return err
215				}
216	
217				// expand reusable caller
218				if isReusableWorkflowCaller && runJob.Status == actions_model.StatusWaiting {
219					if err := expandReusableWorkflowCaller(ctx, run, runAttempt, runJob, vars); err != nil {
220						return fmt.Errorf("inline trigger caller %d ready: %w", runJob.ID, err)
221					}
222					// refresh the caller status
223					if err := actions_model.RefreshReusableCallerStatus(ctx, runJob); err != nil {
224						return fmt.Errorf("refresh caller %d status: %w", runJob.ID, err)
225					}
226					hasWaitingCallerJobs = true
227				}
228	
229				runJobs = append(runJobs, runJob)
230			}
231	
232			runAttempt.Status = actions_model.AggregateJobStatus(runJobs)
233			if err := actions_model.UpdateRunAttempt(ctx, runAttempt, "status"); err != nil {
234				return err
235			}
236	
237			// if there is a job in the waiting status, increase tasks version.
238			if hasWaitingJobs {
239				if err := actions_model.IncreaseTaskVersion(ctx, run.OwnerID, run.RepoID); err != nil {
240					return err
241				}
242			}
243	
244			return nil
245		}); err != nil {
246			return err
247		}
248	
249		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, cancelledConcurrencyJobs)
250		EmitJobsIfReadyByJobs(cancelledConcurrencyJobs)
251	
252		// Post-commit kick for expanded callers: let job_emitter resolve its child jobs
253		if hasWaitingCallerJobs {
254			if err := EmitJobsIfReadyByRun(run.ID); err != nil {
255				log.Error("emit run %d after InsertRun: %v", run.ID, err)
256			}
257		}
258	
259		return nil
260	}
