264	package actions
265	
266	import (
267		"context"
268		"fmt"
269		"time"
270	
271		actions_model "gitea.dev/models/actions"
272		"gitea.dev/models/db"
273		repo_model "gitea.dev/models/repo"
274		"gitea.dev/models/unit"
275		"gitea.dev/modules/json"
276		"gitea.dev/modules/log"
277		"gitea.dev/modules/timeutil"
278		webhook_module "gitea.dev/modules/webhook"
279	)
280	
281	// StartScheduleTasks start the task
282	func StartScheduleTasks(ctx context.Context) error {
283		return startTasks(ctx)
284	}
285	
286	// startTasks retrieves specifications in pages, creates a schedule task for each specification,
287	// and updates the specification's next run time and previous run time.
288	// The function returns an error if there's an issue with finding or updating the specifications.
289	func startTasks(ctx context.Context) error {
290		// Set the page size
291		pageSize := 50
292	
293		// Retrieve specs in pages until all specs have been retrieved
294		now := time.Now()
295		for page := 1; ; page++ {
296			// Retrieve the specs for the current page
297			specs, _, err := actions_model.FindSpecs(ctx, actions_model.FindSpecOptions{
298				ListOptions: db.ListOptions{
299					Page:     page,
300					PageSize: pageSize,
301				},
302				Next: now.Unix(),
303			})
304			if err != nil {
305				return fmt.Errorf("find specs: %w", err)
306			}
307	
308			if err := specs.LoadRepos(ctx); err != nil {
309				return fmt.Errorf("LoadRepos: %w", err)
310			}
311	
312			// Loop through each spec and create a schedule task for it
313			for _, row := range specs {
314				if row.Repo.IsArchived {
315					// Skip if the repo is archived
316					continue
317				}
318	
319				cfg, err := row.Repo.GetUnit(ctx, unit.TypeActions)
320				if err != nil {
321					if repo_model.IsErrUnitTypeNotExist(err) {
322						// Skip the actions unit of this repo is disabled.
323						continue
324					}
325					return fmt.Errorf("GetUnit: %w", err)
326				}
327				if cfg.ActionsConfig().IsWorkflowDisabled(row.Schedule.WorkflowID) {
328					continue
329				}
330	
331				if err := CreateScheduleTask(ctx, row); err != nil {
332					log.Error("CreateScheduleTask: %v", err)
333					return err
334				}
335	
336				// Parse the spec
337				schedule, err := row.Parse()
338				if err != nil {
339					log.Error("Parse: %v", err)
340					return err
341				}
342	
343				// Update the spec's next run time and previous run time
344				row.Prev = row.Next
345				row.Next = timeutil.TimeStamp(schedule.Next(now.Add(1 * time.Minute)).Unix())
346				if err := actions_model.UpdateScheduleSpec(ctx, row, "prev", "next"); err != nil {
347					log.Error("UpdateScheduleSpec: %v", err)
348					return err
349				}
350			}
351	
352			// Stop if all specs have been retrieved
353			if len(specs) < pageSize {
354				break
355			}
356		}
357	
358		return nil
359	}
360	
361	// CreateScheduleTask creates a scheduled task from a cron action schedule spec.
362	// It creates an action run based on the schedule, inserts it into the database, and creates commit statuses for each job.
363	func CreateScheduleTask(ctx context.Context, spec *actions_model.ActionScheduleSpec) error {
364		cron := spec.Schedule
365		eventPayload := withScheduleInEventPayload(cron.EventPayload, spec.Spec)
366	
367		// Create a new action run based on the schedule
368		run := &actions_model.ActionRun{
369			Title:         cron.Title,
370			RepoID:        cron.RepoID,
371			OwnerID:       cron.OwnerID,
372			WorkflowID:    cron.WorkflowID,
373			TriggerUserID: cron.TriggerUserID,
374			Ref:           cron.Ref,
375			CommitSHA:     cron.CommitSHA,
376			Event:         cron.Event,
377			EventPayload:  eventPayload,
378			TriggerEvent:  string(webhook_module.HookEventSchedule),
379			ScheduleID:    cron.ID,
380			Status:        actions_model.StatusWaiting,
381			// schedule runs the repo's own workflow at the recorded commit
382			WorkflowRepoID:    cron.RepoID,
383			WorkflowCommitSHA: cron.CommitSHA,
384		}
385	
386		// FIXME cron.Content might be outdated if the workflow file has been changed.
387		// Load the latest sha from default branch
388		// Insert the action run and its associated jobs into the database
389		if err := PrepareRunAndInsert(ctx, cron.Content, run, nil); err != nil {
390			return err
391		}
392	
393		// Return nil if no errors occurred
394		return nil
395	}
396	
397	func withScheduleInEventPayload(eventPayload, schedule string) string {
398		if schedule == "" {
399			return eventPayload
400		}
401	
402		// eventPayload originates from json.Marshal(input.Payload) in handleSchedules,
403		// so a nil payload is stored as the literal "null" and pre-existing rows may be
404		// empty. Both cases start from a fresh map so the schedule field can still be set.
405		var event map[string]any
406		if eventPayload != "" {
407			if err := json.Unmarshal([]byte(eventPayload), &event); err != nil {
408				log.Error("withScheduleInEventPayload: unmarshal: %v", err)
409				return eventPayload
410			}
411		}
412		if event == nil {
413			event = map[string]any{}
414		}
415	
416		event["schedule"] = schedule
417		updatedPayload, err := json.Marshal(event)
418		if err != nil {
419			log.Error("withScheduleInEventPayload: marshal: %v", err)
420			return eventPayload
421		}
422	
423		return string(updatedPayload)
424	}

