 19	// ActionSchedule represents a schedule of a workflow file
 20	type ActionSchedule struct {
 21		ID            int64
 22		Title         string
 23		Specs         []string
 24		RepoID        int64                  `xorm:"index"`
 25		Repo          *repo_model.Repository `xorm:"-"`
 26		OwnerID       int64                  `xorm:"index"`
 27		WorkflowID    string
 28		TriggerUserID int64
 29		TriggerUser   *user_model.User `xorm:"-"`
 30		Ref           string
 31		CommitSHA     string
 32		Event         webhook_module.HookEventType
 33		EventPayload  string `xorm:"LONGTEXT"`
 34		Content       []byte
 35		Created       timeutil.TimeStamp `xorm:"created"`
 36		Updated       timeutil.TimeStamp `xorm:"updated"`
 37	}
