 39	func init() {
 40		db.RegisterModel(new(ActionSchedule))
 41	}
 42	
 43	// GetSchedulesMapByIDs returns the schedules by given id slice.
 44	func GetSchedulesMapByIDs(ctx context.Context, ids []int64) (map[int64]*ActionSchedule, error) {
 45		schedules := make(map[int64]*ActionSchedule, len(ids))
 46		if len(ids) == 0 {
 47			return schedules, nil
 48		}
 49		return schedules, db.GetEngine(ctx).In("id", ids).Find(&schedules)
 50	}
 51	
 52	// CreateScheduleTask creates new schedule task.
 53	func CreateScheduleTask(ctx context.Context, rows []*ActionSchedule) error {
 54		// Return early if there are no rows to insert
 55		if len(rows) == 0 {
 56			return nil
 57		}
 58	
 59		return db.WithTx(ctx, func(ctx context.Context) error {
 60			// Loop through each schedule row
 61			for _, row := range rows {
 62				row.Title = util.EllipsisDisplayString(row.Title, 255)
 63				// Create new schedule row
 64				if err := db.Insert(ctx, row); err != nil {
 65					return err
 66				}
 67	
 68				// Loop through each schedule spec and create a new spec row
 69				now := time.Now()
 70	
 71				for _, spec := range row.Specs {
 72					specRow := &ActionScheduleSpec{
 73						RepoID:     row.RepoID,
 74						ScheduleID: row.ID,
 75						Spec:       spec,
 76					}
 77					// Parse the spec and check for errors
 78					schedule, err := specRow.Parse()
 79					if err != nil {
 80						continue // skip to the next spec if there's an error
 81					}
 82	
 83					specRow.Next = timeutil.TimeStamp(schedule.Next(now).Unix())
 84	
 85					// Insert the new schedule spec row
 86					if err = db.Insert(ctx, specRow); err != nil {
 87						return err
 88					}
 89				}
 90			}
 91			return nil
 92		})
 93	}
 94	
 95	func DeleteScheduleTaskByRepo(ctx context.Context, id int64) error {
 96		return db.WithTx(ctx, func(ctx context.Context) error {
 97			if _, err := db.GetEngine(ctx).Delete(&ActionSchedule{RepoID: id}); err != nil {
 98				return err
 99			}
100	
101			if _, err := db.GetEngine(ctx).Delete(&ActionScheduleSpec{RepoID: id}); err != nil {
102				return err
103			}
104	
105			return nil
106		})
107	}
108	
109	func CleanRepoScheduleTasks(ctx context.Context, repo *repo_model.Repository) ([]*ActionRunJob, error) {
110		// If actions disabled when there is schedule task, this will remove the outdated schedule tasks
111		// There is no other place we can do this because the app.ini will be changed manually
112		if err := DeleteScheduleTaskByRepo(ctx, repo.ID); err != nil {
113			return nil, fmt.Errorf("DeleteCronTaskByRepo: %v", err)
114		}
115		// cancel running cron jobs of this repository and delete old schedules
116		jobs, err := CancelPreviousJobs(
117			ctx,
118			repo.ID,
119			repo.DefaultBranch,
120			"",
121			webhook_module.HookEventSchedule,
122		)
123		if err != nil {
124			return jobs, fmt.Errorf("CancelPreviousJobs: %v", err)
125		}
126		return jobs, nil
127	}
