 19	// ActionSchedule represents a schedule of a workflow file
 20	type ActionSchedule struct {
 21		ID            int64
 22		Title         string
 23		Specs         []string
 24		RepoID        int64                  `xorm:"index"`
 25		Repo          *repo_model.Repository `xorm:"-"`
 26		OwnerID       int64                  `xorm:"index"`
