145	// ActionScheduleSpec represents a schedule spec of a workflow file
146	type ActionScheduleSpec struct {
147		ID         int64
148		RepoID     int64                  `xorm:"index"`
149		Repo       *repo_model.Repository `xorm:"-"`
150		ScheduleID int64                  `xorm:"index"`
151		Schedule   *ActionSchedule        `xorm:"-"`
152	
153		// Next time the job will run, or the zero time if Cron has not been
154		// started or this entry's schedule is unsatisfiable
155		Next timeutil.TimeStamp `xorm:"index"`
156		// Prev is the last time this job was run, or the zero time if never.
157		Prev timeutil.TimeStamp
158		Spec string
159	
160		Created timeutil.TimeStamp `xorm:"created"`
161		Updated timeutil.TimeStamp `xorm:"updated"`
162	}
163	
164	// Parse parses the spec and returns a cron.Schedule
165	// Unlike the default cron parser, Parse uses UTC timezone as the default if none is specified.
166	func (s *ActionScheduleSpec) Parse() (cron.Schedule, error) {
167		parser := cron.NewParser(cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow | cron.Descriptor)
168		schedule, err := parser.Parse(s.Spec)
169		if err != nil {
170			return nil, err
171		}
172	
173		// If the spec has specified a timezone, use it
174		if strings.HasPrefix(s.Spec, "TZ=") || strings.HasPrefix(s.Spec, "CRON_TZ=") {
175			return schedule, nil
176		}
177	
178		specSchedule, ok := schedule.(*cron.SpecSchedule)
179		// If it's not a spec schedule, like "@every 5m", timezone is not relevant
180		if !ok {
181			return schedule, nil
182		}
183	
184		// Set the timezone to UTC
185		specSchedule.Location = time.UTC
186		return specSchedule, nil
187	}
