34	
35	type methodCtxKeyType struct{}
36	
37	var methodCtxKey methodCtxKeyType
38	
39	// withMethod sets the notification method that this context currently executes.
40	// Used for debugging/ troubleshooting purposes.
41	func withMethod(ctx context.Context, method string) context.Context {
42		// don't overwrite
43		if v := ctx.Value(methodCtxKey); v != nil {
44			if _, ok := v.(string); ok {
45				return ctx
46			}
47		}
48		return context.WithValue(ctx, methodCtxKey, method)
49	}
50	
51	// getMethod gets the notification method that this context currently executes.
52	// Default: "notify"
53	// Used for debugging/ troubleshooting purposes.
54	func getMethod(ctx context.Context) string {
55		if v := ctx.Value(methodCtxKey); v != nil {
56			if s, ok := v.(string); ok {
57				return s
58			}
59		}
60		return "notify"
61	}
62	
63	type notifyInput struct {
64		// required
65		Repo  *repo_model.Repository
66		Doer  *user_model.User
67		Event webhook_module.HookEventType
68	
69		// optional
70		Ref         git.RefName
71		Payload     api.Payloader
72		PullRequest *issues_model.PullRequest
73	}
74	
75	func newNotifyInput(repo *repo_model.Repository, doer *user_model.User, event webhook_module.HookEventType) *notifyInput {
76		return &notifyInput{
77			Repo:  repo,
78			Doer:  doer,
79			Event: event,
80		}
81	}
82	
83	func newNotifyInputForSchedules(repo *repo_model.Repository) *notifyInput {
84		// the doer here will be ignored as we force using action user when handling schedules
85		return newNotifyInput(repo, user_model.NewActionsUser(), webhook_module.HookEventSchedule)
86	}
87	
88	func (input *notifyInput) WithDoer(doer *user_model.User) *notifyInput {
89		input.Doer = doer
90		return input
91	}
92	
93	func (input *notifyInput) WithRef(ref string) *notifyInput {
94		input.Ref = git.RefName(ref)
95		return input
96	}
97	
98	func (input *notifyInput) WithPayload(payload api.Payloader) *notifyInput {
99		input.Payload = payload
100		return input
101	}
102	
103	func (input *notifyInput) WithPullRequest(pr *issues_model.PullRequest) *notifyInput {
104		input.PullRequest = pr
105		if input.Ref == "" {
106			input.Ref = git.RefName(pr.GetGitHeadRefName())
107		}
108		return input
109	}
110	
111	func (input *notifyInput) Notify(ctx context.Context) {
112		log.Trace("execute %v for event %v whose doer is %v", getMethod(ctx), input.Event, input.Doer.Name)
113	
114		if err := notify(ctx, input); err != nil {
115			log.Error("an error occurred while executing the %s actions method: %v", getMethod(ctx), err)
116		}
117	}
118	
119	func notify(ctx context.Context, input *notifyInput) error {
120		shouldDetectSchedules := input.Event == webhook_module.HookEventPush && input.Ref.BranchName() == input.Repo.DefaultBranch
121		if input.Doer.IsGiteaActions() {
122			// avoiding triggering cyclically, for example:
123			// a comment of an issue will trigger the runner to add a new comment as reply,
124			// and the new comment will trigger the runner again.
125			log.Debug("ignore executing %v for event %v whose doer is %v", getMethod(ctx), input.Event, input.Doer.Name)
126	
127			// we should update schedule tasks in this case, because
128			//   1. schedule tasks cannot be triggered by other events, so cyclic triggering will not occur
129			//   2. some schedule tasks may update the repo periodically, so the refs of schedule tasks need to be updated
130			if shouldDetectSchedules {
131				return DetectAndHandleSchedules(ctx, input.Repo)
132			}
133	
134			return nil
135		}
136		if input.Repo.IsEmpty || input.Repo.IsArchived {
137			return nil
138		}
139		if unit_model.TypeActions.UnitGlobalDisabled() {
140			if err := CleanRepoScheduleTasks(ctx, input.Repo); err != nil {
141				log.Error("CleanRepoScheduleTasks: %v", err)
142			}
143			return nil
144		}
145		if err := input.Repo.LoadUnits(ctx); err != nil {
146			return fmt.Errorf("repo.LoadUnits: %w", err)
147		} else if !input.Repo.UnitEnabled(ctx, unit_model.TypeActions) {
148			return nil
149		}
150	
151		gitRepo, err := gitrepo.OpenRepository(context.Background(), input.Repo)
152		if err != nil {
153			return fmt.Errorf("git.OpenRepository: %w", err)
154		}
155		defer gitRepo.Close()
156	
157		ref := input.Ref
158		if ref.BranchName() != input.Repo.DefaultBranch && actions_module.IsDefaultBranchWorkflow(input.Event) {
159			if ref != "" {
160				log.Warn("Event %q should only trigger workflows on the default branch, but its ref is %q. Will fall back to the default branch",
161					input.Event, ref)
162			}
163			ref = git.RefNameFromBranch(input.Repo.DefaultBranch)
164		}
165		if ref == "" {
166			log.Warn("Ref of event %q is empty, will fall back to the default branch", input.Event)
167			ref = git.RefNameFromBranch(input.Repo.DefaultBranch)
168		}
169	
170		commitID, err := gitRepo.GetRefCommitID(ref.String())
171		if err != nil {
172			return fmt.Errorf("gitRepo.GetRefCommitID: %w", err)
173		}
174	
175		// Get the commit object for the ref
176		commit, err := gitRepo.GetCommit(commitID)
177		if err != nil {
178			return fmt.Errorf("gitRepo.GetCommit: %w", err)
179		}
180	
181		if skipWorkflows(ctx, input, commit) {
182			return nil
183		}
184	
185		var detectedWorkflows []*actions_module.DetectedWorkflow
186		var filteredWorkflows []*actions_module.DetectedWorkflow
187		actionsConfig := input.Repo.MustGetUnit(ctx, unit_model.TypeActions).ActionsConfig()
188		workflows, schedules, filtered, err := actions_module.DetectWorkflows(gitRepo, commit,
189			input.Event,
190			input.Payload,
191			shouldDetectSchedules,
192		)
193		if err != nil {
194			return fmt.Errorf("DetectWorkflows: %w", err)
195		}
196	
197		log.Trace("repo %s with commit %s event %s find %d workflows and %d schedules",
198			input.Repo.RelativePath(),
199			commit.ID,
200			input.Event,
201			len(workflows),
202			len(schedules),
203		)
204	
205		for _, wf := range workflows {
206			if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
207				log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
208				continue
209			}
210	
211			if wf.TriggerEvent.Name != actions_module.GithubEventPullRequestTarget {
212				detectedWorkflows = append(detectedWorkflows, wf)
213			}
214		}
215	
216		for _, wf := range filtered {
217			if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
218				log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
219				continue
220			}
221	
222			if wf.TriggerEvent.Name != actions_module.GithubEventPullRequestTarget {
223				filteredWorkflows = append(filteredWorkflows, wf)
224			}
225		}
226	
227		if input.PullRequest != nil {
228			// detect pull_request_target workflows
229			baseRef := git.BranchPrefix + input.PullRequest.BaseBranch
230			baseCommit, err := gitRepo.GetCommit(baseRef)
231			if err != nil {
232				return fmt.Errorf("gitRepo.GetCommit: %w", err)
233			}
234			baseWorkflows, _, baseFiltered, err := actions_module.DetectWorkflows(gitRepo, baseCommit, input.Event, input.Payload, false)
235			if err != nil {
236				return fmt.Errorf("DetectWorkflows: %w", err)
237			}
238			if len(baseWorkflows) == 0 {
239				log.Trace("repo %s with commit %s couldn't find pull_request_target workflows", input.Repo.RelativePath(), baseCommit.ID)
240			} else {
241				for _, wf := range baseWorkflows {
242					if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
243						log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
244						continue
245					}
246					if wf.TriggerEvent.Name == actions_module.GithubEventPullRequestTarget {
247						detectedWorkflows = append(detectedWorkflows, wf)
248					}
249				}
250			}
251			for _, wf := range baseFiltered {
252				if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
253					log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
254					continue
255				}
256				if wf.TriggerEvent.Name == actions_module.GithubEventPullRequestTarget {
257					filteredWorkflows = append(filteredWorkflows, wf)
258				}
259			}
260		}
261	
262		if shouldDetectSchedules {
263			if err := handleSchedules(ctx, schedules, commit, input, ref); err != nil {
264				return err
265			}
266		}
267	
268		if err := handleWorkflows(ctx, detectedWorkflows, commit, input, ref); err != nil {
269			return err
270		}
271	
272		handleFilteredWorkflows(ctx, input, filteredWorkflows)
273	
274		return detectAndHandleScopedWorkflows(ctx, input, ref, gitRepo, commit)
275	}
276	
277	func skipWorkflows(ctx context.Context, input *notifyInput, commit *git.Commit) bool {
278		// skip workflow runs with a configured skip-ci string in commit message or pr title if the event is push or pull_request(_sync)
279		// https://docs.github.com/en/actions/managing-workflow-runs/skipping-workflow-runs
280		skipWorkflowEvents := []webhook_module.HookEventType{
281			webhook_module.HookEventPush,
282			webhook_module.HookEventPullRequest,
283			webhook_module.HookEventPullRequestSync,
284		}
285		if slices.Contains(skipWorkflowEvents, input.Event) {
286			for _, s := range setting.Actions.SkipWorkflowStrings {
287				if input.PullRequest != nil && strings.Contains(input.PullRequest.Issue.Title, s) {
288					log.Debug("repo %s: skipped run for pr %v because of %s string", input.Repo.RelativePath(), input.PullRequest.Issue.ID, s)
289					return true
290				}
291				if strings.Contains(commit.MessageRaw, s) {
292					log.Debug("repo %s with commit %s: skipped run because of %s string", input.Repo.RelativePath(), commit.ID, s)
293					return true
294				}
295			}
296		}
297		if input.Event == webhook_module.HookEventWorkflowRun {
298			wrun, ok := input.Payload.(*api.WorkflowRunPayload)
299			for i := 0; i < 5 && ok && wrun.WorkflowRun != nil; i++ {
300				if wrun.WorkflowRun.Event != "workflow_run" {
301					return false
302				}
303				r, err := actions_model.GetRunByRepoAndID(ctx, input.Repo.ID, wrun.WorkflowRun.ID)
304				if err != nil {
305					log.Error("GetRunByRepoAndID: %v", err)
306					return true
307				}
308				wrun, err = r.GetWorkflowRunEventPayload()
309				if err != nil {
310					log.Error("GetWorkflowRunEventPayload: %v", err)
311					return true
312				}
313			}
314			// skip workflow runs events exceeding the maximum of 5 recursive events
315			log.Debug("repo %s: skipped workflow_run because of recursive event of 5", input.Repo.RelativePath())
316			return true
317		}
318		return false
319	}
320	
321	func handleWorkflows(
322		ctx context.Context,
323		detectedWorkflows []*actions_module.DetectedWorkflow,
324		commit *git.Commit,
325		input *notifyInput,
326		ref git.RefName,
327	) error {
328		if len(detectedWorkflows) == 0 {
329			log.Trace("repo %s with commit %s couldn't find workflows", input.Repo.RelativePath(), commit.ID)
330			return nil
331		}
332	
333		p, err := json.Marshal(input.Payload)
334		if err != nil {
335			return fmt.Errorf("json.Marshal: %w", err)
336		}
337	
338		isForkPullRequest := isForkPullRequestInput(input)
339	
340		for _, dwf := range detectedWorkflows {
341			// repo-level run: the workflow content is this repo at this commit
342			if err := buildApproveAndInsertRun(ctx, input, ref, commit, string(p), isForkPullRequest, dwf, input.Repo.ID, commit.ID.String(), false); err != nil {
343				log.Error("repo %s: %v", input.Repo.RelativePath(), err)
344				continue
345			}
346		}
347		return nil
348	}
349	
350	// buildApproveAndInsertRun assembles an ActionRun for a detected workflow, runs the
351	// fork-PR approval gate, and inserts it. Repo-level and scoped runs share this path so
352	// run construction and the approval flow have a single implementation that can't drift.
353	// workflowRepoID/workflowCommitSHA point at the repo+commit the workflow content comes
354	// from (the repo itself for repo-level runs, the source repo for scoped runs).
355	func buildApproveAndInsertRun(
356		ctx context.Context,
357		input *notifyInput,
358		ref git.RefName,
359		commit *git.Commit,
360		payload string,
361		isForkPullRequest bool,
362		dwf *actions_module.DetectedWorkflow,
363		workflowRepoID int64,
364		workflowCommitSHA string,
365		isScopedRun bool,
366	) error {
367		run := &actions_model.ActionRun{
368			Title:             commit.MessageTitle(),
369			RepoID:            input.Repo.ID,
370			Repo:              input.Repo,
371			OwnerID:           input.Repo.OwnerID,
372			WorkflowID:        dwf.EntryName,
373			TriggerUserID:     input.Doer.ID,
374			TriggerUser:       input.Doer,
375			Ref:               ref.String(),
376			CommitSHA:         commit.ID.String(),
377			IsForkPullRequest: isForkPullRequest,
378			Event:             input.Event,
379			EventPayload:      payload,
380			TriggerEvent:      dwf.TriggerEvent.Name,
381			Status:            actions_model.StatusWaiting,
382			WorkflowRepoID:    workflowRepoID,
383			WorkflowCommitSHA: workflowCommitSHA,
384			IsScopedRun:       isScopedRun,
385		}
386	
387		need, err := ifNeedApproval(ctx, run, input.Repo, input.Doer)
388		if err != nil {
389			return fmt.Errorf("check if need approval for user %d: %w", input.Doer.ID, err)
390		}
391		run.NeedApproval = need
392	
393		if err := PrepareRunAndInsert(ctx, dwf.Content, run, nil); err != nil {
394			return fmt.Errorf("PrepareRunAndInsert: %w", err)
395		}
396		return nil
397	}
398	
399	// handleFilteredWorkflows posts a skipped commit status for each filtered-out workflow whose context is a required status check;
400	// a non-required one posts nothing, so it cannot leak into a pull request.
401	func handleFilteredWorkflows(ctx context.Context, input *notifyInput, filteredWorkflows []*actions_module.DetectedWorkflow) {
402		if len(filteredWorkflows) == 0 {
403			return
404		}
405		requiredGlobs, err := getAllRequiredStatusContextGlobs(ctx, input.Repo)
406		if err != nil {
407			log.Error("repo %s: required status contexts: %v", input.Repo.RelativePath(), err)
408			return
409		}
410		if len(requiredGlobs) == 0 {
411			return
412		}
413		for _, dwf := range filteredWorkflows {
414			if err := CreateSkippedCommitStatusForFilteredWorkflow(ctx, input.Repo, input.Event, dwf.TriggerEvent.Name, dwf.EntryName, dwf.Content, input.Payload, "", requiredGlobs); err != nil {
415				log.Error("repo %s: skipped commit status for workflow %s: %v", input.Repo.RelativePath(), dwf.EntryName, err)
416				continue
417			}
418		}
419	}
420	
421	func newNotifyInputFromIssue(issue *issues_model.Issue, event webhook_module.HookEventType) *notifyInput {
422		return newNotifyInput(issue.Repo, issue.Poster, event)
423	}
424	
425	func notifyRelease(ctx context.Context, doer *user_model.User, rel *repo_model.Release, action api.HookReleaseAction) {
426		if err := rel.LoadAttributes(ctx); err != nil {
427			log.Error("LoadAttributes: %v", err)
428			return
429		}
430	
431		permission, _ := access_model.GetDoerRepoPermission(ctx, rel.Repo, doer)
432	
433		newNotifyInput(rel.Repo, doer, webhook_module.HookEventRelease).
434			WithRef(git.RefNameFromTag(rel.TagName).String()).
435			WithPayload(&api.ReleasePayload{
436				Action:     action,
437				Release:    convert.ToAPIRelease(ctx, rel.Repo, rel),
438				Repository: convert.ToRepo(ctx, rel.Repo, permission),
439				Sender:     convert.ToUser(ctx, doer, nil),
440			}).
441			Notify(ctx)
442	}
443	
444	func notifyPackage(ctx context.Context, sender *user_model.User, pd *packages_model.PackageDescriptor, action api.HookPackageAction) {
445		if pd.Repository == nil {
446			// When a package is uploaded to an organization, it could trigger an event to notify.
447			// So the repository could be nil, however, actions can't support that yet.
448			// See https://github.com/go-gitea/gitea/pull/17940
449			return
450		}
451	
452		apiPackage, err := convert.ToPackage(ctx, pd, sender)
453		if err != nil {
454			log.Error("Error converting package: %v", err)
455			return
456		}
457	
458		newNotifyInput(pd.Repository, sender, webhook_module.HookEventPackage).
459			WithPayload(&api.PackagePayload{
460				Action:  action,
461				Package: apiPackage,
462				Sender:  convert.ToUser(ctx, sender, nil),
463			}).
464			Notify(ctx)
465	}
466	
467	func ifNeedApproval(ctx context.Context, run *actions_model.ActionRun, repo *repo_model.Repository, user *user_model.User) (bool, error) {
468		canWrite := func(ctx context.Context, repo *repo_model.Repository, user *user_model.User) (bool, error) {
469			perm, err := access_model.GetDoerRepoPermission(ctx, repo, user)
470			if err != nil {
471				return false, err
472			}
473			return perm.CanWrite(unit_model.TypeActions), nil
474		}
475		return ifNeedApprovalWith(ctx, run, repo, user, canWrite, issues_model.HasMergedPullRequestInRepo)
476	}
477	
478	func ifNeedApprovalWith(
479		ctx context.Context,
480		run *actions_model.ActionRun,
481		repo *repo_model.Repository,
482		user *user_model.User,
483		canWriteActions func(context.Context, *repo_model.Repository, *user_model.User) (bool, error),
484		hasMergedPR func(context.Context, int64, int64) (bool, error),
485	) (bool, error) {
486		// 1. don't need approval if it's not a fork PR
487		// 2. don't need approval if the event is `pull_request_target` since the workflow will run in the context of base branch
488		// 		see https://docs.github.com/en/actions/managing-workflow-runs/approving-workflow-runs-from-public-forks#about-workflow-runs-from-public-forks
489		if !run.IsForkPullRequest || run.TriggerEvent == actions_module.GithubEventPullRequestTarget {
490			return false, nil
491		}
492	
493		// always need approval if the user is restricted
494		if user.IsRestricted {
495			log.Trace("need approval because user %d is restricted", user.ID)
496			return true, nil
497		}
498	
499		// don't need approval if the user can write
500		if ok, err := canWriteActions(ctx, repo, user); err != nil {
501			return false, fmt.Errorf("GetDoerRepoPermission: %w", err)
502		} else if ok {
503			log.Trace("do not need approval because user %d can write", user.ID)
504			return false, nil
505		}
506	
507		// trust the user only after a merged PR — matching GitHub Actions. Approving one
508		// fork PR's run must not implicitly trust later fork PRs that replace the workflow.
509		if merged, err := hasMergedPR(ctx, repo.ID, user.ID); err != nil {
510			return false, fmt.Errorf("HasMergedPullRequestInRepo: %w", err)
511		} else if merged {
512			log.Trace("do not need approval because user %d has a merged pull request in repo %d", user.ID, repo.ID)
513			return false, nil
514		}
515	
516		// otherwise, need approval
517		log.Trace("need approval because user %d has no merged pull request in repo %d", user.ID, repo.ID)
518		return true, nil
519	}
520	
521	func handleSchedules(
522		ctx context.Context,
523		detectedWorkflows []*actions_module.DetectedWorkflow,
524		commit *git.Commit,
525		input *notifyInput,
526		ref git.RefName,
527	) error {
528		if ref.BranchName() != input.Repo.DefaultBranch {
529			log.Trace("commit branch is not default branch in repo")
530			return nil
531		}
532	
533		if count, err := db.Count[actions_model.ActionSchedule](ctx, actions_model.FindScheduleOptions{RepoID: input.Repo.ID}); err != nil {
534			log.Error("CountSchedules: %v", err)
535			return err
536		} else if count > 0 {
537			if err := CleanRepoScheduleTasks(ctx, input.Repo); err != nil {
538				log.Error("CleanRepoScheduleTasks: %v", err)
539			}
540		}
541	
542		if len(detectedWorkflows) == 0 {
543			log.Trace("repo %s with commit %s couldn't find schedules", input.Repo.RelativePath(), commit.ID)
544			return nil
545		}
546	
547		p, err := json.Marshal(input.Payload)
548		if err != nil {
549			return fmt.Errorf("json.Marshal: %w", err)
550		}
551	
552		crons := make([]*actions_model.ActionSchedule, 0, len(detectedWorkflows))
553		for _, dwf := range detectedWorkflows {
554			// Check cron job condition. Only working in default branch
555			workflow, err := model.ReadWorkflow(bytes.NewReader(dwf.Content))
556			if err != nil {
557				log.Error("ReadWorkflow: %v", err)
558				continue
559			}
560			schedules := workflow.OnSchedule()
561			if len(schedules) == 0 {
562				log.Warn("no schedule event")
563				continue
564			}
565	
566			run := &actions_model.ActionSchedule{
567				Title:         commit.MessageTitle(),
568				RepoID:        input.Repo.ID,
569				Repo:          input.Repo,
570				OwnerID:       input.Repo.OwnerID,
571				WorkflowID:    dwf.EntryName,
572				TriggerUserID: user_model.ActionsUserID,
573				TriggerUser:   user_model.NewActionsUser(),
574				Ref:           ref.String(),
575				CommitSHA:     commit.ID.String(),
576				Event:         input.Event,
577				EventPayload:  string(p),
578				Specs:         schedules,
579				Content:       dwf.Content,
580			}
581	
582			crons = append(crons, run)
583		}
584	
585		return actions_model.CreateScheduleTask(ctx, crons)
586	}
587	
588	// DetectAndHandleSchedules detects the schedule workflows on the default branch and create schedule tasks
589	func DetectAndHandleSchedules(ctx context.Context, repo *repo_model.Repository) error {
590		if repo.IsEmpty || repo.IsArchived {
591			return nil
592		}
593	
594		gitRepo, err := gitrepo.OpenRepository(context.Background(), repo)
595		if err != nil {
596			return fmt.Errorf("git.OpenRepository: %w", err)
597		}
598		defer gitRepo.Close()
599	
600		// Only detect schedule workflows on the default branch
601		commit, err := gitRepo.GetCommit(repo.DefaultBranch)
602		if err != nil {
603			return fmt.Errorf("gitRepo.GetCommit: %w", err)
604		}
605		scheduleWorkflows, err := actions_module.DetectScheduledWorkflows(gitRepo, commit)
606		if err != nil {
607			return fmt.Errorf("detect schedule workflows: %w", err)
608		}
609		if len(scheduleWorkflows) == 0 {
610			return nil
611		}
612	
613		// We need a notifyInput to call handleSchedules
614		// if repo is a mirror, commit author maybe an external user,
615		// so we use action user as the Doer of the notifyInput
616		notifyInput := newNotifyInputForSchedules(repo)
617	
618		return handleSchedules(ctx, scheduleWorkflows, commit, notifyInput, git.RefNameFromBranch(repo.DefaultBranch))
619	}
620	
621	// isForkPullRequestInput reports whether the run should be treated as a fork pull request.
622	func isForkPullRequestInput(input *notifyInput) bool {
623		pr := input.PullRequest
624		if pr == nil {
625			return false
626		}
627		switch pr.Flow {
628		case issues_model.PullRequestFlowGithub:
629			return pr.IsFromFork()
630		case issues_model.PullRequestFlowAGit:
631			// There is no fork concept in agit flow, anyone with read permission can push refs/for/<target-branch>/<topic-branch> to the repo.
632			// So we can treat it as a fork pull request because it may be from an untrusted user
633			return true
634		default:
635			// unknown flow, assume it's a fork pull request to be safe
636			return true
637		}
638	}
639	
640	// detectAndHandleScopedWorkflows detects scoped workflows registered for the consuming repo
641	func detectAndHandleScopedWorkflows(
642		ctx context.Context,
643		input *notifyInput,
644		ref git.RefName,
645		consumerGitRepo *git.Repository,
646		consumerCommit *git.Commit,
647	) error {
648		// TODO: support workflow_run and schedule
649		if input.Event == webhook_module.HookEventWorkflowRun || input.Event == webhook_module.HookEventSchedule {
650			return nil
651		}
652	
653		sources, err := actions_model.GetEffectiveScopedWorkflowSources(ctx, input.Repo.OwnerID)
654		if err != nil {
655			return fmt.Errorf("GetEffectiveScopedWorkflowSources: %w", err)
656		}
657		if len(sources) == 0 {
658			return nil
659		}
660	
661		p, err := json.Marshal(input.Payload)
662		if err != nil {
663			return fmt.Errorf("json.Marshal: %w", err)
664		}
665		isForkPullRequest := isForkPullRequestInput(input)
666		actionsConfig := input.Repo.MustGetUnit(ctx, unit_model.TypeActions).ActionsConfig()
667	
668		// A filtered-out scoped workflow only posts a skipped status when its context is a required check.
669		requiredGlobs, err := getAllRequiredStatusContextGlobs(ctx, input.Repo)
670		if err != nil {
671			log.Error("scoped workflows: required status contexts for %s: %v", input.Repo.RelativePath(), err)
672		}
673	
674		// The same source repo may be registered at both the owner and instance level; dedup
675		// the IDs and batch-load them in one query instead of one round-trip per source.
676		seen := make(container.Set[int64], len(sources))
677		for _, source := range sources {
678			seen.Add(source.SourceRepoID)
679		}
680		sourceRepoIDs := seen.Values()
681	
682		sourceRepos, err := repo_model.GetRepositoriesMapByIDs(ctx, sourceRepoIDs)
683		if err != nil {
684			return fmt.Errorf("GetRepositoriesMapByIDs: %w", err)
685		}
686	
687		for _, sourceRepoID := range sourceRepoIDs {
688			sourceRepo := sourceRepos[sourceRepoID]
689			if sourceRepo == nil {
690				// don't abort the other effective sources for this event
691				log.Error("scoped workflows: source repo %d for consumer %s not found", sourceRepoID, input.Repo.RelativePath())
692				continue
693			}
694			if sourceRepo.IsEmpty {
695				continue
696			}
697	
698			sourceCommitSHA, detected, filtered, err := detectScopedWorkflowsForSource(ctx, input, consumerGitRepo, consumerCommit, sourceRepo)
699			if err != nil {
700				log.Error("scoped workflows: source %d for consumer %s: %v", sourceRepoID, input.Repo.RelativePath(), err)
701				continue
702			}
703	
704			for _, dwf := range detected {
705				// A consuming repo can opt out of a non-required scoped workflow.
706				// A required workflow (marked required at any effective level) can never be opted out.
707				if actions_model.ScopedWorkflowOptedOut(actionsConfig, sources, sourceRepo.ID, dwf.EntryName) {
708					continue
709				}
710	
711				if err := buildApproveAndInsertRun(ctx, input, ref, consumerCommit, string(p), isForkPullRequest, dwf, sourceRepo.ID, sourceCommitSHA, true); err != nil {
712					log.Error("scoped workflows: source %s workflow %s: %v", sourceRepo.RelativePath(), dwf.EntryName, err)
713					continue
714				}
715			}
716	
717			// A filtered-out scoped workflow posts a skipped commit status for its required-check contexts.
718			if len(filtered) > 0 && len(requiredGlobs) > 0 {
719				scopedPrefix := actions_model.ScopedStatusContextPrefix(ctx, sourceRepo.ID)
720				for _, dwf := range filtered {
721					if actions_model.ScopedWorkflowOptedOut(actionsConfig, sources, sourceRepo.ID, dwf.EntryName) {
722						continue
723					}
724					if err := CreateSkippedCommitStatusForFilteredWorkflow(ctx, input.Repo, input.Event, dwf.TriggerEvent.Name, dwf.EntryName, dwf.Content, input.Payload, scopedPrefix, requiredGlobs); err != nil {
725						log.Error("scoped workflows: skipped commit status for source %s workflow %s: %v", sourceRepo.RelativePath(), dwf.EntryName, err)
726						continue
727					}
728				}
729			}
730		}
731	
732		return nil
733	}
734	
735	// detectScopedWorkflowsForSource detects the scoped workflows from the source repo at its default branch.
736	// detected are the workflows to run; filtered matched the event but were excluded by a branch/paths
737	// filter, and later post a skipped commit status only for a required-check context.
738	func detectScopedWorkflowsForSource(
739		ctx context.Context,
740		input *notifyInput,
741		consumerGitRepo *git.Repository,
742		consumerCommit *git.Commit,
743		sourceRepo *repo_model.Repository,
744	) (sourceCommitSHA string, detected, filtered []*actions_module.DetectedWorkflow, err error) {
745		// scoped workflow content is always taken from the source repo's default branch; the parse is cached per (source, default-branch SHA) and reused across consuming repos/events
746		sourceCommitSHA, parsed, err := LoadParsedScopedWorkflows(ctx, sourceRepo)
747		if err != nil {
748			return "", nil, nil, err
749		}
750		detected, filtered = actions_module.MatchScopedWorkflows(parsed, consumerGitRepo, consumerCommit, input.Event, input.Payload)
751		return sourceCommitSHA, detected, filtered, nil
752	}
