71	func validateRerun(ctx context.Context, run *actions_model.ActionRun, repo *repo_model.Repository, triggerUser *user_model.User, jobsToRerun []*actions_model.ActionRunJob) error {
72		if !run.Status.IsDone() {
73			return util.NewInvalidArgumentErrorf("this workflow run is not done")
74		}
75		if repo == nil {
76			return util.NewInvalidArgumentErrorf("repo is required")
77		}
78		if run.RepoID != repo.ID {
79			return util.NewInvalidArgumentErrorf("run %d does not belong to repo %d", run.ID, repo.ID)
80		}
81		for _, job := range jobsToRerun {
82			if job.RunID != run.ID {
83				return util.NewInvalidArgumentErrorf("job %d does not belong to workflow run %d", job.ID, run.ID)
84			}
85		}
86		if triggerUser == nil {
87			return util.NewInvalidArgumentErrorf("trigger user is required")
88		}
89		cfgUnit := repo.MustGetUnit(ctx, unit.TypeActions)
90		cfg := cfgUnit.ActionsConfig()
91		if run.IsScopedRun {
92			// a required scoped workflow can never be opted out, so a stale disabled flag must not block rerun
93			optedOut, err := actions_model.IsScopedWorkflowOptedOut(ctx, cfg, repo.OwnerID, run.WorkflowRepoID, run.WorkflowID)
94			if err != nil {
95				return err
96			}
97			if optedOut {
98				return util.NewInvalidArgumentErrorf("scoped workflow %s is disabled", run.WorkflowID)
99			}
100		} else if cfg.IsWorkflowDisabled(run.WorkflowID) {
101			return util.NewInvalidArgumentErrorf("workflow %s is disabled", run.WorkflowID)
102		}
103	
104		// Legacy runs (LatestAttemptID == 0) conceptually have only attempt 1, so they can never be at the cap.
105		// For non-legacy runs, look up the latest attempt and reject when its number is already at the configured cap.
106		if run.LatestAttemptID > 0 {
107			latestAttempt, has, err := run.GetLatestAttempt(ctx)
108			if err != nil {
109				return fmt.Errorf("GetLatestAttempt: %w", err)
110			}
111			if has && latestAttempt.Attempt >= setting.Actions.MaxRerunAttempts {
112				return util.NewInvalidArgumentErrorf("workflow run has reached the maximum of %d attempts", setting.Actions.MaxRerunAttempts)
113			}
114		}
115	
116		return nil
117	}
