    19	func ApproveRuns(ctx context.Context, repo *repo_model.Repository, doer *user_model.User, runIDs []int64) error {
    20		updatedJobs := make([]*actions_model.ActionRunJob, 0)
    21		cancelledConcurrencyJobs := make([]*actions_model.ActionRunJob, 0)
    22		// Track runs whose reusable callers were just expanded so we can re-emit after the tx commits.
    23		expandedCallerRunIDs := make(container.Set[int64])
    24	
    25		err := db.WithTx(ctx, func(ctx context.Context) (err error) {
    26			for _, runID := range runIDs {
    27				run, err := actions_model.GetRunByRepoAndID(ctx, repo.ID, runID)
    28				if err != nil {
    29					return err
    30				}
    31				run.NeedApproval = false
    32				run.ApprovedBy = doer.ID
    33				if err := actions_model.UpdateRun(ctx, run, "need_approval", "approved_by"); err != nil {
    34					return err
    35				}
    36				jobs, err := actions_model.GetLatestAttemptJobsByRepoAndRunID(ctx, repo.ID, run.ID)
    37				if err != nil {
    38					return err
    39				}
    40	
    41				for _, job := range jobs {
    42					// Skip jobs with `needs`: they stay blocked until their dependencies finish,
    43					// at which point job_emitter will evaluate and start them.
    44					if len(job.Needs) > 0 {
    45						continue
    46					}
    47					var jobsToCancel []*actions_model.ActionRunJob
    48					job.Status, jobsToCancel, err = PrepareToStartJobWithConcurrency(ctx, job)
    49					if err != nil {
    50						return err
    51					}
    52					cancelledConcurrencyJobs = append(cancelledConcurrencyJobs, jobsToCancel...)
    53					if job.Status != actions_model.StatusWaiting {
    54						continue
    55					}
    56					n, err := actions_model.UpdateRunJob(ctx, job, nil, "status")
    57					if err != nil {
    58						return err
    59					}
    60					if n == 0 {
    61						continue
    62					}
    63					updatedJobs = append(updatedJobs, job)
    64	
    65					// A top-level reusable caller was just unblocked by approval, expand it
    66					if job.IsReusableCaller && !job.IsExpanded {
    67						attempt, has, err := run.GetLatestAttempt(ctx)
    68						if err != nil {
    69							return fmt.Errorf("get latest attempt of run %d: %w", run.ID, err)
    70						}
    71						if !has {
    72							return errors.New("run has no attempt")
    73						}
    74						vars, err := actions_model.GetVariablesOfRun(ctx, run)
    75						if err != nil {
    76							return err
    77						}
    78						if err := expandReusableWorkflowCaller(ctx, run, attempt, job, vars); err != nil {
    79							return fmt.Errorf("expand caller %d on approval: %w", job.ID, err)
    80						}
    81						if err := actions_model.RefreshReusableCallerStatus(ctx, job); err != nil {
    82							return fmt.Errorf("refresh caller %d status after approval-time expansion: %w", job.ID, err)
    83						}
    84						expandedCallerRunIDs.Add(run.ID)
    85					}
    86				}
    87			}
    88			return nil
    89		})
    90		if err != nil {
    91			return err
    92		}
    93	
    94		// Re-emit AFTER the tx commits so the newly inserted callee rows transition Blocked -> Waiting.
    95		for runID := range expandedCallerRunIDs {
    96			if err := EmitJobsIfReadyByRun(runID); err != nil {
    97				log.Error("emit run %d after approval-time caller expansion: %v", runID, err)
    98			}
    99		}
   100	
   101		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, updatedJobs)
   102		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, cancelledConcurrencyJobs)
   103	
   104		EmitJobsIfReadyByJobs(cancelledConcurrencyJobs)
   105	
   106		return nil
   107	}

