393	func getWorkflowDispatchInputsFromRun(run *actions_model.ActionRun) (map[string]any, error) {
394		if run.Event != "workflow_dispatch" {
395			return map[string]any{}, nil
396		}
397		var payload api.WorkflowDispatchPayload
398		if err := json.Unmarshal([]byte(run.EventPayload), &payload); err != nil {
399			return nil, err
400		}
401		return payload.Inputs, nil
402	}
403	
404	// getInputsForJob returns the `inputs.*` top-level expression context for a job's evaluation.
405	//   - For top-level jobs, it falls back to the run's dispatch inputs (empty for non-dispatch events)
406	//   - For reusable workflow children (and nested callers), this is the direct parent caller's CallPayload.Inputs
407	func getInputsForJob(ctx context.Context, run *actions_model.ActionRun, job *actions_model.ActionRunJob) (map[string]any, error) {
408		if job.ParentJobID == 0 {
409			return getWorkflowDispatchInputsFromRun(run)
410		}
411	
412		caller, err := actions_model.GetRunJobByRunAndID(ctx, run.ID, job.ParentJobID)
413		if err != nil {
414			return nil, fmt.Errorf("load caller job %d: %w", job.ParentJobID, err)
415		}
416		if caller.CallPayload == "" {
417			// should not happen - a child job cannot reach this point if its caller's CallPayload hasn't been evaluated
418			return map[string]any{}, nil
419		}
420		var p api.WorkflowCallPayload
421		if err := json.Unmarshal([]byte(caller.CallPayload), &p); err != nil {
422			return nil, fmt.Errorf("decode caller %d payload: %w", caller.ID, err)
423		}
424		if p.Inputs == nil {
425			return map[string]any{}, nil
426		}
427		return p.Inputs, nil
428	}
