430	// evaluateJobIf evaluates a job's `if:`
431	func evaluateJobIf(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, job *actions_model.ActionRunJob, vars map[string]string, allNeedsSucceed bool) (bool, error) {
432		parsedJob, err := job.ParseJob()
433		if err != nil {
434			return false, err
435		}
436		// Empty `if:` reduces to implicit `success()` - true iff every need finished as Success.
437		if len(parsedJob.If.Value) == 0 {
438			return allNeedsSucceed, nil
439		}
440		jobResults, err := findJobNeedsAndFillJobResults(ctx, job)
441		if err != nil {
442			return false, err
443		}
444		inputs, err := getInputsForJob(ctx, run, job)
445		if err != nil {
446			return false, err
447		}
448		gitCtx := GenerateGiteaContext(ctx, run, attempt, job)
449		return jobparser.EvaluateJobIfExpression(job.JobID, parsedJob, gitCtx, jobResults, vars, inputs)
450	}
451	
452	func findJobNeedsAndFillJobResults(ctx context.Context, job *actions_model.ActionRunJob) (map[string]*jobparser.JobResult, error) {
453		taskNeeds, err := FindTaskNeeds(ctx, job)
454		if err != nil {
455			return nil, fmt.Errorf("find task needs: %w", err)
456		}
457		jobResults := make(map[string]*jobparser.JobResult, len(taskNeeds))
458		for jobID, taskNeed := range taskNeeds {
459			jobResult := &jobparser.JobResult{
460				Result:  taskNeed.Result.String(),
461				Outputs: taskNeed.Outputs,
462			}
463			jobResults[jobID] = jobResult
464		}
465		jobResults[job.JobID] = &jobparser.JobResult{
466			Needs: job.Needs,
467		}
468		return jobResults, nil
469	}
