589	// sumOtherJobSummarySizes returns the total stored size of all step summaries for a job
590	// except excludeStepIndex, computed in the database to avoid loading every row.
591	func sumOtherJobSummarySizes(ctx context.Context, repoID, runID, runAttemptID, jobID, excludeStepIndex int64) (int64, error) {
592		return db.GetEngine(ctx).
593			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index<>?", repoID, runID, runAttemptID, jobID, excludeStepIndex).
594			SumInt(new(ActionRunJobSummary), "content_size")
595	}
