34	    34	// loadReusableWorkflowSource resolves the workflow file referenced by a caller's `uses:` and returns its raw bytes,
35	    35	// along with the (repo_id, commit_sha) the file was loaded from.
36	    36	func loadReusableWorkflowSource(ctx context.Context, run *actions_model.ActionRun, caller *actions_model.ActionRunJob, ref *jobparser.UsesRef) (content []byte, sourceRepoID int64, sourceCommitSHA string, err error) {
37	    37		if err := run.LoadAttributes(ctx); err != nil {
38	    38			return nil, 0, "", err
39	    39		}
40	    40	
41	    41		switch ref.Kind {
42	    42		case jobparser.UsesKindLocalSameRepo:
43	    43			// `./` is resolved against the workflow file containing the `uses:` - i.e. the caller's own source repo + commit.
44	    44			callerRepo, err := repo_model.GetRepositoryByID(ctx, caller.WorkflowSourceRepoID)
45	    45			if err != nil {
46	    46				return nil, 0, "", fmt.Errorf("look up caller source repo %d: %w", caller.WorkflowSourceRepoID, err)
47	    47			}
48	    48			bytes, resolvedSHA, err := readWorkflowFromRepo(ctx, callerRepo, caller.WorkflowSourceCommitSHA, ref.Path)
49	    49			if err != nil {
50	    50				return nil, 0, "", err
51	    51			}
52	    52			return bytes, callerRepo.ID, resolvedSHA, nil
53	    53	
54	    54		case jobparser.UsesKindLocalCrossRepo:
55	    55			repo, err := repo_model.GetRepositoryByOwnerAndName(ctx, ref.Owner, ref.Repo)
56	    56			if err != nil {
57	    57				return nil, 0, "", fmt.Errorf("look up cross-repo workflow source %q: %w", ref.Owner+"/"+ref.Repo, err)
58	    58			}
59	    59			ok, err := access_model.CanReadWorkflowCrossRepo(ctx, repo, run)
60	    60			if err != nil {
61	    61				return nil, 0, "", err
62	    62			}
63	    63			if !ok {
64	    64				if run.IsScopedRun {
65	    65					// A scoped workflow's cross-repo "uses:" is resolved with the consuming repo's read permission,
66	    66					// so the referenced repo must be readable by every consumer. Make that explicit in the failure.
67	    67					return nil, 0, "", fmt.Errorf("no permission to read reusable workflow %s/%s: a scoped workflow's cross-repo \"uses:\" is resolved with the consuming repository %q read permission", ref.Owner, ref.Repo, run.Repo.RelativePath())
68	    68				}
69	    69				return nil, 0, "", fmt.Errorf("no permission to read reusable workflow from %s/%s", ref.Owner, ref.Repo)
70	    70			}
71	    71			bytes, resolvedSHA, err := readWorkflowFromRepo(ctx, repo, ref.Ref, ref.Path)
72	    72			if err != nil {
73	    73				return nil, 0, "", err
74	    74			}
