80	    80	// readWorkflowFromRepo loads a workflow file from `repo` at `refOrSHA` and returns its content plus the resolved commit SHA.
81	    81	func readWorkflowFromRepo(ctx context.Context, repo *repo_model.Repository, refOrSHA, path string) ([]byte, string, error) {
82	    82		gitRepo, err := gitrepo.OpenRepository(ctx, repo)
83	    83		if err != nil {
84	    84			return nil, "", fmt.Errorf("open repo %s: %w", repo.FullName(), err)
85	    85		}
86	    86		defer gitRepo.Close()
87	    87	
88	    88		commit, err := gitRepo.GetCommit(refOrSHA)
89	    89		if err != nil {
90	    90			return nil, "", fmt.Errorf("get commit %q in %s: %w", refOrSHA, repo.FullName(), err)
91	    91		}
92	    92		str, err := commit.GetFileContent(path, 1024*1024)
93	    93		if err != nil {
94	    94			return nil, "", fmt.Errorf("read %s@%s:%s: %w", repo.FullName(), refOrSHA, path, err)
95	    95		}
96	    96		return []byte(str), commit.ID.String(), nil
97	    97	}
