99	    99	// checkCallerChain walks `caller`'s ancestor chain (via ParentJobID) and:
100	   100	//   - rejects cycles (caller.CallUses appearing in any ancestor's CallUses)
101	   101	//   - enforces MaxReusableCallLevels on the number of ancestors above `caller`
102	   102	//
103	   103	// Cycle detection is intentionally *syntactic* (string equality on CallUses), not semantic.
104	   104	// So `owner/repo/lib.yml@v1` and `owner/repo/lib.yml@refs/heads/v1` resolving to the same commit are NOT treated as the same node.
105	   105	// Going semantic (Owner, Repo, Path, ResolvedSHA tuples) would require extra git reads.
106	   106	func checkCallerChain(ctx context.Context, caller *actions_model.ActionRunJob) error {
107	   107		if caller.ParentJobID == 0 {
108	   108			return nil // top-level caller: depth 0, no ancestors to walk
109	   109		}
110	   110	
111	   111		visited := make(container.Set[string])
112	   112		visited.Add(caller.CallUses)
113	   113	
114	   114		depth := 0
115	   115		current := caller
116	   116		for current.ParentJobID != 0 {
117	   117			next, err := actions_model.GetRunJobByRunAndID(ctx, current.RunID, current.ParentJobID)
118	   118			if err != nil {
119	   119				return fmt.Errorf("walk caller chain: %w", err)
120	   120			}
121	   121			current = next
122	   122			depth++
123	   123			if depth > MaxReusableCallLevels {
124	   124				return fmt.Errorf("reusable workflow call exceeds the maximum nesting level of %d at %q", MaxReusableCallLevels, caller.CallUses)
125	   125			}
126	   126			if current.IsReusableCaller && current.CallUses != "" {
127	   127				if visited.Contains(current.CallUses) {
128	   128					return fmt.Errorf("reusable workflow call cycle detected: %q", current.CallUses)
129	   129				}
130	   130				visited.Add(current.CallUses)
131	   131			}
132	   132		}
133	   133		return nil
134	   134	}
