136	   136	// expandReusableWorkflowCaller loads and parses the target reusable workflow and inserts the caller's direct child jobs.
137	   137	// It expands only ONE level: a child that is itself a reusable caller is inserted Blocked and expanded later by a subsequent resolver pass.
138	   138	// It does NOT schedule a follow-up resolver pass; the caller of this function is responsible for emitting.
139	   139	//
140	   140	// All call sites (PrepareRunAndInsert, execRerunPlan, checkJobsOfCurrentRunAttempt, ApproveRuns) invoke this inside their enclosing write transaction,
141	   141	// because the caller row update and the child-row inserts must commit atomically.
142	   142	// Be aware this is not cheap inside a tx: it does a git read, YAML parsing, and `${{ }}` expression evaluation.
143	   143	// None of the call sites is hot: each caller is expanded once per attempt.
144	   144	func expandReusableWorkflowCaller(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, caller *actions_model.ActionRunJob, vars map[string]string) error {
145	   145		// Already expanded by an earlier call, skip
146	   146		if caller.IsExpanded {
147	   147			return nil
148	   148		}
149	   149	
150	   150		// 1. Cycle + depth check via the ParentJobID chain.
151	   151		if err := checkCallerChain(ctx, caller); err != nil {
152	   152			return err
153	   153		}
154	   154	
155	   155		// 2. Parse the caller's own job (Uses, With, RawSecrets) from its WorkflowPayload.
156	   156		parsedJob, err := caller.ParseJob()
157	   157		if err != nil {
158	   158			return fmt.Errorf("parse caller job %d: %w", caller.ID, err)
159	   159		}
160	   160	
161	   161		// 3. Resolve `uses` and load called-workflow source.
162	   162		ref, err := ResolveUses(ctx, parsedJob.Uses)
163	   163		if err != nil {
164	   164			return fmt.Errorf("resolve uses %q: %w", parsedJob.Uses, err)
165	   165		}
166	   166		content, contentSourceRepoID, contentSourceCommitSHA, err := loadReusableWorkflowSource(ctx, run, caller, ref)
167	   167		if err != nil {
168	   168			return err
169	   169		}
170	   170	
171	   171		// 4. Parse the called workflow's spec (used by both secret validation and input evaluation).
172	   172		wcSpec, err := jobparser.ParseWorkflowCallSpec(content)
173	   173		if err != nil {
174	   174			return fmt.Errorf("parse called workflow spec: %w", err)
175	   175		}
176	   176	
177	   177		// 5. Resolve caller's `secrets:` and validate it against the callee's schema.
178	   178		inherit, secretsMap, err := jobparser.ParseCallerSecrets(parsedJob.RawSecrets)
179	   179		if err != nil {
180	   180			return fmt.Errorf("caller secrets %q: %w", caller.JobID, err)
181	   181		}
182	   182		// Under `secrets: inherit` the caller forwards all of its own secrets verbatim and does NOT name them individually,
183	   183		// so required-secret presence cannot be verified at expansion time and a missing required secret will surface at job runtime.
184	   184		// This matches GitHub Actions' behavior.
185	   185		if !inherit {
186	   186			if err := jobparser.ValidateCallerSecrets(wcSpec, secretsMap); err != nil {
187	   187				return fmt.Errorf("caller %q secrets: %w", caller.JobID, err)
188	   188			}
189	   189		}
190	   190		switch {
191	   191		case inherit:
192	   192			caller.CallSecrets = jobparser.SecretsInherit
193	   193		case len(secretsMap) > 0:
194	   194			mapBytes, err := json.Marshal(secretsMap)
195	   195			if err != nil {
196	   196				return fmt.Errorf("marshal caller secret map: %w", err)
197	   197			}
198	   198			caller.CallSecrets = string(mapBytes)
199	   199		}
200	   200		caller.ReusableWorkflowContent = content
201	   201	
202	   202		// 6. Evaluate caller's `with:`, then match against the callee schema.
203	   203		workflowCallInputs := map[string]any{}
204	   204		if len(wcSpec.Inputs) > 0 {
205	   205			jobResults, err := findJobNeedsAndFillJobResults(ctx, caller)
206	   206			if err != nil {
207	   207				return fmt.Errorf("find caller needs: %w", err)
208	   208			}
209	   209			parentInputs, err := getInputsForJob(ctx, run, caller)
210	   210			if err != nil {
211	   211				return err
212	   212			}
213	   213			callerGitCtx := GenerateGiteaContext(ctx, run, attempt, caller)
214	   214			evaluated, err := jobparser.EvaluateCallerWith(
215	   215				caller.JobID, parsedJob,
216	   216				callerGitCtx, jobResults, vars, parentInputs,
217	   217			)
218	   218			if err != nil {
219	   219				return fmt.Errorf("evaluate caller with: %w", err)
220	   220			}
221	   221			workflowCallInputs, err = jobparser.MatchCallerInputsAgainstSpec(wcSpec, evaluated)
222	   222			if err != nil {
223	   223				return fmt.Errorf("caller %q inputs: %w", caller.JobID, err)
224	   224			}
225	   225		}
226	   226	
227	   227		// 7. Build CallPayload (persisted in step 9).
228	   228		callPayload, err := (&api.WorkflowCallPayload{
229	   229			Workflow:   run.WorkflowID,
230	   230			Ref:        run.Ref,
231	   231			Repository: convert.ToRepo(ctx, run.Repo, access_model.Permission{AccessMode: perm_model.AccessModeNone}),
232	   232			Sender:     convert.ToUserWithAccessMode(ctx, run.TriggerUser, perm_model.AccessModeNone),
233	   233			Inputs:     workflowCallInputs,
234	   234		}).JSONPayload()
235	   235		if err != nil {
236	   236			return fmt.Errorf("build call payload: %w", err)
237	   237		}
238	   238	
239	   239		// 8. Insert direct children of this caller.
240	   240		existingChildren, err := actions_model.GetDirectChildJobsByParent(ctx, caller)
241	   241		if err != nil {
242	   242			return fmt.Errorf("get existing children of caller %d: %w", caller.ID, err)
243	   243		}
244	   244		if len(existingChildren) > 0 {
245	   245			// Should not happen - child jobs cannot be expanded before the caller gets ready
246	   246			return fmt.Errorf("invariant violation: caller %d has %d pre-existing children", caller.ID, len(existingChildren))
247	   247		}
248	   248		if err := insertCallerChildren(ctx, run, attempt, caller, content, contentSourceRepoID, contentSourceCommitSHA, vars, workflowCallInputs); err != nil {
249	   249			return err
250	   250		}
251	   251	
252	   252		// 9. Update caller-related cols.
253	   253		caller.CallPayload = string(callPayload)
254	   254		caller.IsExpanded = true
255	   255		n, err := actions_model.UpdateRunJob(ctx, caller,
256	   256			builder.Eq{"is_expanded": false},
257	   257			"call_secrets", "reusable_workflow_content", "call_payload", "is_expanded")
258	   258		if err != nil {
259	   259			return fmt.Errorf("commit caller %d expansion: %w", caller.ID, err)
260	   260		}
261	   261		if n == 0 {
262	   262			return fmt.Errorf("caller %d already expanded by another writer", caller.ID)
263	   263		}
264	   264		return nil
265	   265	}
266	   266	
267	   267	// insertCallerChildren parses the called workflow with the caller's resolved inputs and inserts each parsed job.
268	   268	func insertCallerChildren(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, caller *actions_model.ActionRunJob, content []byte, sourceRepoID int64, sourceCommitSHA string, vars map[string]string, inputs map[string]any) error {
269	   269		// Parse the called workflow with the caller's `inputs`
270	   270		gitCtx := GenerateGiteaContext(ctx, run, attempt, nil)
271	   271		if event, ok := gitCtx["event"].(map[string]any); ok {
272	   272			event["inputs"] = inputs
273	   273		}
274	   274		gitCtx["event_name"] = "workflow_call"
275	   275	
276	   276		childWorkflows, err := jobparser.Parse(content,
277	   277			jobparser.WithVars(vars),
278	   278			jobparser.WithGitContext(gitCtx.ToGitHubContext()),
279	   279			jobparser.WithInputs(inputs),
280	   280		)
281	   281		if err != nil {
282	   282			return fmt.Errorf("parse called workflow for caller %d: %w", caller.ID, err)
283	   283		}
284	   284		if len(childWorkflows) == 0 {
285	   285			return fmt.Errorf("called workflow for caller %d (uses %q) has no jobs", caller.ID, caller.CallUses)
286	   286		}
287	   287	
288	   288		priorChildren, err := actions_model.GetPriorAttemptChildrenByParent(ctx, run.ID, attempt.ID, caller.AttemptJobID)
289	   289		if err != nil {
290	   290			return fmt.Errorf("lookup prior-attempt children of caller %d: %w", caller.ID, err)
291	   291		}
292	   292	
293	   293		for _, sw := range childWorkflows {
294	   294			jobID, parsedChild := sw.Job()
295	   295			if parsedChild == nil {
296	   296				continue
297	   297			}
298	   298			needs := parsedChild.Needs()
299	   299			if err := sw.SetJob(jobID, parsedChild.EraseNeeds()); err != nil {
300	   300				return err
301	   301			}
302	   302			payload, err := sw.Marshal()
303	   303			if err != nil {
304	   304				return fmt.Errorf("marshal child %q under caller %d: %w", jobID, caller.ID, err)
305	   305			}
306	   306	
307	   307			parsedChild.Name = util.EllipsisDisplayString(parsedChild.Name, 255)
308	   308	
309	   309			// AttemptJobID: prefer a prior-attempt match by (JobID, Name) and fall back to a fresh allocator value for newly-appearing logical jobs.
310	   310			// The two-level key disambiguates matrix instances (same JobID, different Names) and distinct jobs that legally share the same Name (different JobIDs).
311	   311			var attemptJobID int64
312	   312			if priorChild, ok := priorChildren[jobID][parsedChild.Name]; ok {
313	   313				attemptJobID = priorChild.AttemptJobID
314	   314			} else {
315	   315				attemptJobID, err = actions_model.GetNextAttemptJobID(ctx, run.ID)
316	   316				if err != nil {
317	   317					return fmt.Errorf("alloc attempt_job_id for child %q: %w", jobID, err)
318	   318				}
319	   319			}
320	   320			child := &actions_model.ActionRunJob{
321	   321				RunID:                   run.ID,
322	   322				RunAttemptID:            attempt.ID,
323	   323				RepoID:                  run.RepoID,
324	   324				OwnerID:                 run.OwnerID,
325	   325				CommitSHA:               run.CommitSHA,
326	   326				IsForkPullRequest:       run.IsForkPullRequest,
327	   327				Name:                    parsedChild.Name,
328	   328				Attempt:                 attempt.Attempt,
329	   329				WorkflowPayload:         payload,
330	   330				JobID:                   jobID,
331	   331				AttemptJobID:            attemptJobID,
332	   332				Needs:                   needs,
333	   333				RunsOn:                  parsedChild.RunsOn(),
334	   334				ContinueOnError:         parsedChild.GetContinueOnError(),
335	   335				Status:                  actions_model.StatusBlocked,
336	   336				ParentJobID:             caller.ID,
337	   337				WorkflowSourceRepoID:    sourceRepoID,
338	   338				WorkflowSourceCommitSHA: sourceCommitSHA,
339	   339			}
340	   340			if perms := ExtractJobPermissionsFromWorkflow(sw, parsedChild); perms != nil {
341	   341				child.TokenPermissions = perms
342	   342			}
343	   343			if parsedChild.Uses != "" {
344	   344				child.IsReusableCaller = true
345	   345				child.CallUses = parsedChild.Uses
346	   346			}
347	   347			if err := db.Insert(ctx, child); err != nil {
348	   348				return fmt.Errorf("insert child %q under caller %d: %w", jobID, caller.ID, err)
349	   349			}
350	   350		}
351	   351		return nil
352	   352	}
353	   353	
354	   354	// ResolveUses normalizes and parses a reusable workflow `uses:` value.
355	   355	// It first rewrites an absolute URL pointing to this instance into the cross-repo form (rejecting external URLs),
356	   356	// then validates the syntax via jobparser.ParseUses.
357	   357	func ResolveUses(ctx context.Context, uses string) (*jobparser.UsesRef, error) {
358	   358		// Rewrite a local-instance URL to the equivalent cross-repo form "owner/repo/.gitea/workflows/file.yml@ref".
359	   359		if strings.HasPrefix(uses, "http://") || strings.HasPrefix(uses, "https://") {
360	   360			// ParseGiteaSiteURL returns nil for URLs that do not belong to this instance.
361	   361			gsu := httplib.ParseGiteaSiteURL(ctx, uses)
362	   362			if gsu == nil {
363	   363				return nil, fmt.Errorf("unsupported reusable workflow URL %q: an absolute URL must point to this Gitea instance (%s)", uses, setting.AppURL)
364	   364			}
365	   365			// RoutePath is the instance-relative path (AppSubURL already stripped), e.g. "/owner/repo/.gitea/workflows/file.yml@ref".
366	   366			uses = strings.TrimPrefix(gsu.RoutePath, "/")
367	   367		}
368	   368		ref, err := jobparser.ParseUses(uses)
369	   369		if err != nil {
370	   370			return nil, err
371	   371		}
372	   372		// jobparser only validates syntax; enforce the (instance-configurable) directory allowlist here.
373	   373		if !actions_module.IsWorkflowOrScopedWorkflow(ref.Path) {
374	   374			return nil, fmt.Errorf(`"uses:" path %q must be under a configured workflow directory (WORKFLOW_DIRS or SCOPED_WORKFLOW_DIRS)`, ref.Path)
375	   375		}
376	   376		return ref, nil
377	   377	}
