393	   393	func getWorkflowDispatchInputsFromRun(run *actions_model.ActionRun) (map[string]any, error) {
394	   394		if run.Event != "workflow_dispatch" {
395	   395			return map[string]any{}, nil
396	   396		}
397	   397		var payload api.WorkflowDispatchPayload
398	   398		if err := json.Unmarshal([]byte(run.EventPayload), &payload); err != nil {
399	   399			return nil, err
400	   400		}
401	   401		return payload.Inputs, nil
402	   402	}
403	   403	
404	   404	// getInputsForJob returns the `inputs.*` top-level expression context for a job's evaluation.
405	   405	//   - For top-level jobs, it falls back to the run's dispatch inputs (empty for non-dispatch events)
406	   406	//   - For reusable workflow children (and nested callers), this is the direct parent caller's CallPayload.Inputs
407	   407	func getInputsForJob(ctx context.Context, run *actions_model.ActionRun, job *actions_model.ActionRunJob) (map[string]any, error) {
408	   408		if job.ParentJobID == 0 {
409	   409			return getWorkflowDispatchInputsFromRun(run)
410	   410		}
411	   411	
412	   412		caller, err := actions_model.GetRunJobByRunAndID(ctx, run.ID, job.ParentJobID)
413	   413		if err != nil {
414	   414			return nil, fmt.Errorf("load caller job %d: %w", job.ParentJobID, err)
415	   415		}
416	   416		if caller.CallPayload == "" {
417	   417			// should not happen - a child job cannot reach this point if its caller's CallPayload hasn't been evaluated
418	   418			return map[string]any{}, nil
419	   419		}
420	   420		var p api.WorkflowCallPayload
421	   421		if err := json.Unmarshal([]byte(caller.CallPayload), &p); err != nil {
422	   422			return nil, fmt.Errorf("decode caller %d payload: %w", caller.ID, err)
423	   423		}
424	   424		if p.Inputs == nil {
425	   425			return map[string]any{}, nil
426	   426		}
427	   427		return p.Inputs, nil
428	   428	}
429	   429	
430	   430	// evaluateJobIf evaluates a job's `if:`
431	   431	func evaluateJobIf(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, job *actions_model.ActionRunJob, vars map[string]string, allNeedsSucceed bool) (bool, error) {
432	   432		parsedJob, err := job.ParseJob()
433	   433		if err != nil {
434	   434			return false, err
435	   435		}
436	   436		// Empty `if:` reduces to implicit `success()` - true iff every need finished as Success.
437	   437		if len(parsedJob.If.Value) == 0 {
438	   438			return allNeedsSucceed, nil
439	   439		}
440	   440		jobResults, err := findJobNeedsAndFillJobResults(ctx, job)
441	   441		if err != nil {
442	   442			return false, err
443	   443		}
444	   444		inputs, err := getInputsForJob(ctx, run, job)
445	   445		if err != nil {
446	   446			return false, err
447	   447		}
448	   448		gitCtx := GenerateGiteaContext(ctx, run, attempt, job)
449	   449		return jobparser.EvaluateJobIfExpression(job.JobID, parsedJob, gitCtx, jobResults, vars, inputs)
450	   450	}
451	   451	
452	   452	func findJobNeedsAndFillJobResults(ctx context.Context, job *actions_model.ActionRunJob) (map[string]*jobparser.JobResult, error) {
453	   453		taskNeeds, err := FindTaskNeeds(ctx, job)
454	   454		if err != nil {
455	   455			return nil, fmt.Errorf("find task needs: %w", err)
456	   456		}
457	   457		jobResults := make(map[string]*jobparser.JobResult, len(taskNeeds))
458	   458		for jobID, taskNeed := range taskNeeds {
459	   459			jobResult := &jobparser.JobResult{
460	   460				Result:  taskNeed.Result.String(),
461	   461				Outputs: taskNeed.Outputs,
462	   462			}
463	   463			jobResults[jobID] = jobResult
464	   464		}
465	   465		jobResults[job.JobID] = &jobparser.JobResult{
466	   466			Needs: job.Needs,
467	   467		}
468	   468		return jobResults, nil
469	   469	}
