529	   529	func GetActionRunJobSummary(ctx context.Context, repoID, runID, runAttemptID, jobID, stepIndex int64) (*ActionRunJobSummary, error) {
530	   530		var s ActionRunJobSummary
531	   531		has, err := db.GetEngine(ctx).
532	   532			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index=?", repoID, runID, runAttemptID, jobID, stepIndex).
533	   533			Get(&s)
534	   534		if err != nil {
535	   535			return nil, err
536	   536		}
537	   537		if !has {
538	   538			return nil, util.ErrNotExist
539	   539		}
540	   540		return &s, nil
541	   541	}
542	   542	
543	   543	// ErrJobSummaryAggregateExceeded is returned when a step summary upload would push the
544	   544	// aggregate size of summaries for a single job attempt over MaxJobSummaryAggregateSize.
545	   545	var ErrJobSummaryAggregateExceeded = util.NewInvalidArgumentErrorf("job summary aggregate size exceeded")
546	   546	
547	   547	func UpsertActionRunJobSummary(ctx context.Context, repoID, runID, runAttemptID, jobID, stepIndex int64, contentType string, content []byte) error {
548	   548		if runID <= 0 || jobID <= 0 || repoID <= 0 || stepIndex < 0 {
549	   549			return util.ErrInvalidArgument
550	   550		}
551	   551		if len(content) == 0 {
552	   552			// Treat empty summaries as no-op; runner may create SUMMARY.md but never write to it.
553	   553			return nil
554	   554		}
555	   555		if len(content) > MaxJobSummarySize {
556	   556			return util.ErrInvalidArgument
557	   557		}
558	   558		if contentType != JobSummaryContentTypeMarkdown {
559	   559			return util.ErrInvalidArgument
560	   560		}
561	   561	
562	   562		// The aggregate check is best-effort: a tx wouldn't actually serialize concurrent
563	   563		// step uploads (no row-level lock on the parent job), so wrapping these two
564	   564		// statements only adds round-trip cost without changing the race semantics.
565	   565		// The current step is excluded because the upsert below replaces its size with len(content).
566	   566		otherSize, err := sumOtherJobSummarySizes(ctx, repoID, runID, runAttemptID, jobID, stepIndex)
567	   567		if err != nil {
568	   568			return err
569	   569		}
570	   570		if otherSize+int64(len(content)) > MaxJobSummaryAggregateSize {
571	   571			return ErrJobSummaryAggregateExceeded
572	   572		}
573	   573	
574	   574		now := timeutil.TimeStampNow()
575	   575		return upsertActionRunJobSummary(ctx, &ActionRunJobSummary{
576	   576			RepoID:       repoID,
577	   577			RunID:        runID,
578	   578			RunAttemptID: runAttemptID,
579	   579			JobID:        jobID,
580	   580			StepIndex:    stepIndex,
581	   581			Content:      string(content),
582	   582			ContentSize:  int64(len(content)),
583	   583			ContentType:  contentType,
584	   584			Created:      now,
585	   585			Updated:      now,
586	   586		})
587	   587	}
588	   588	
589	   589	// sumOtherJobSummarySizes returns the total stored size of all step summaries for a job
590	   590	// except excludeStepIndex, computed in the database to avoid loading every row.
591	   591	func sumOtherJobSummarySizes(ctx context.Context, repoID, runID, runAttemptID, jobID, excludeStepIndex int64) (int64, error) {
592	   592		return db.GetEngine(ctx).
593	   593			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index<>?", repoID, runID, runAttemptID, jobID, excludeStepIndex).
594	   594			SumInt(new(ActionRunJobSummary), "content_size")
595	   595	}
596	   596	
597	   597	// DeleteActionRunJobSummary removes the stored summary for a specific step. Used when
598	   598	// a runner PUTs an empty body to clear a previously-uploaded step summary.
599	   599	func DeleteActionRunJobSummary(ctx context.Context, repoID, runID, runAttemptID, jobID, stepIndex int64) error {
600	   600		_, err := db.GetEngine(ctx).
601	   601			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index=?", repoID, runID, runAttemptID, jobID, stepIndex).
602	   602			Delete(new(ActionRunJobSummary))
603	   603		return err
604	   604	}
605	   605	
606	   606	func upsertActionRunJobSummary(ctx context.Context, summary *ActionRunJobSummary) error {
607	   607		engine := db.GetEngine(ctx)
608	   608		columns := "`repo_id`, `run_id`, `run_attempt_id`, `job_id`, `step_index`, `content`, `content_type`, `content_size`, `created`, `updated`"
609	   609		values := []any{
610	   610			summary.RepoID,
611	   611			summary.RunID,
612	   612			summary.RunAttemptID,
613	   613			summary.JobID,
614	   614			summary.StepIndex,
615	   615			summary.Content,
616	   616			summary.ContentType,
617	   617			summary.ContentSize,
618	   618			summary.Created,
619	   619			summary.Updated,
620	   620		}
621	   621	
622	   622		if setting.Database.Type.IsPostgreSQL() || setting.Database.Type.IsSQLite3() {
623	   623			args := append([]any{"INSERT INTO `action_run_job_summary` (" + columns + ") VALUES (?,?,?,?,?,?,?,?,?,?) " +
624	   624				"ON CONFLICT (`repo_id`, `run_id`, `run_attempt_id`, `job_id`, `step_index`) DO UPDATE SET " +
625	   625				"`content` = excluded.`content`, `content_type` = excluded.`content_type`, `content_size` = excluded.`content_size`, `updated` = excluded.`updated`"}, values...)
626	   626			_, err := engine.Exec(args...)
627	   627			return err
628	   628		}
629	   629	
630	   630		if setting.Database.Type.IsMySQL() {
631	   631			args := append([]any{
632	   632				"INSERT INTO `action_run_job_summary` (" + columns + ") VALUES (?,?,?,?,?,?,?,?,?,?) " +
633	   633					"ON DUPLICATE KEY UPDATE `content` = VALUES(`content`), `content_type` = VALUES(`content_type`), `content_size` = VALUES(`content_size`), `updated` = VALUES(`updated`)",
634	   634			}, values...)
635	   635			_, err := engine.Exec(args...)
636	   636			return err
637	   637		}
638	   638	
639	   639		if setting.Database.Type.IsMSSQL() {
640	   640			_, err := engine.Exec(`
641	   641	MERGE INTO action_run_job_summary WITH (HOLDLOCK) AS target
642	   642	USING (SELECT ? AS repo_id, ? AS run_id, ? AS run_attempt_id, ? AS job_id, ? AS step_index) AS source
643	   643	ON target.repo_id = source.repo_id
644	   644		AND target.run_id = source.run_id
645	   645		AND target.run_attempt_id = source.run_attempt_id
646	   646		AND target.job_id = source.job_id
647	   647		AND target.step_index = source.step_index
648	   648	WHEN MATCHED THEN
649	   649		UPDATE SET content = ?, content_type = ?, content_size = ?, updated = ?
650	   650	WHEN NOT MATCHED THEN
651	   651		INSERT (repo_id, run_id, run_attempt_id, job_id, step_index, content, content_type, content_size, created, updated)
652	   652		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
653	   653	`,
654	   654				summary.RepoID, summary.RunID, summary.RunAttemptID, summary.JobID, summary.StepIndex,
655	   655				summary.Content, summary.ContentType, summary.ContentSize, summary.Updated,
656	   656				summary.RepoID, summary.RunID, summary.RunAttemptID, summary.JobID, summary.StepIndex, summary.Content, summary.ContentType, summary.ContentSize, summary.Created, summary.Updated)
657	   657			return err
658	   658		}
659	   659	
660	   660		return util.ErrInvalidArgument
661	   661	}
662	   662	
663	   663	// ListActionRunJobSummaries lists the stored summaries for a run attempt, ordered by job
664	   664	// then step. A positive jobID scopes the lookup to that single job, used by the job view to
665	   665	// avoid rendering every job's summary on each poll; jobID<=0 returns all jobs in the attempt.
666	   666	func ListActionRunJobSummaries(ctx context.Context, repoID, runID, runAttemptID, jobID int64) ([]*ActionRunJobSummary, error) {
667	   667		sess := db.GetEngine(ctx).Where("repo_id=? AND run_id=? AND run_attempt_id=?", repoID, runID, runAttemptID)
668	   668		if jobID > 0 {
669	   669			sess = sess.And("job_id=?", jobID)
670	   670		}
671	   671		var summaries []*ActionRunJobSummary
672	   672		if err := sess.OrderBy("job_id ASC, step_index ASC").Find(&summaries); err != nil {
673	   673			return nil, err
674	   674		}
675	   675		return summaries, nil
676	   676	}
