472	
473	package actions
474	
475	import (
476		"context"
477	
478		"gitea.dev/models/db"
479		"gitea.dev/modules/setting"
480		"gitea.dev/modules/timeutil"
481		"gitea.dev/modules/util"
482	)
483	
484	const (
485		// JobSummaryCapability is the runner-declare capability string for job summaries.
486		JobSummaryCapability = "job-summary"
487	
488		// JobSummaryContentTypeMarkdown is the only accepted content type for job summaries.
489		JobSummaryContentTypeMarkdown = "text/markdown"
490	
491		// MaxJobSummarySize is the maximum accepted per-step summary payload size in bytes.
492		MaxJobSummarySize = 1024 * 1024 // 1 MiB
493	
494		// MaxJobSummaryAggregateSize is the maximum aggregate size of all step summaries within
495		// a single job attempt. Matches GitHub's documented per-job summary cap of 1 MiB.
496		MaxJobSummaryAggregateSize = 1024 * 1024 // 1 MiB
497	)
498	
499	// RunnerCapabilities returns the value advertised in the X-Gitea-Actions-Capabilities header.
500	// When more capabilities are added, return them comma-separated so runners can split on ", ".
501	func RunnerCapabilities() string {
502		return JobSummaryCapability
503	}
504	
505	type ActionRunJobSummary struct {
506		ID int64 `xorm:"pk autoincr"`
507	
508		RepoID       int64 `xorm:"UNIQUE(summary_key)"`
509		RunID        int64 `xorm:"UNIQUE(summary_key)"`
510		RunAttemptID int64 `xorm:"UNIQUE(summary_key) NOT NULL DEFAULT 0"`
511		JobID        int64 `xorm:"UNIQUE(summary_key)"`
512		StepIndex    int64 `xorm:"UNIQUE(summary_key)"`
513	
514		Content     string `xorm:"LONGTEXT"`
515		ContentType string `xorm:"VARCHAR(255) NOT NULL DEFAULT 'text/markdown'"`
516		// ContentSize is the byte length of Content. Stored explicitly because LENGTH()
517		// counts characters (not bytes) on PostgreSQL, SQLite and MSSQL, which would let
518		// multibyte UTF-8 content bypass the aggregate cap.
519		ContentSize int64 `xorm:"NOT NULL DEFAULT 0"`
520	
521		Created timeutil.TimeStamp `xorm:"created"`
522		Updated timeutil.TimeStamp `xorm:"updated"`
523	}
524	
525	func init() {
526		db.RegisterModel(new(ActionRunJobSummary))
527	}
528	
529	func GetActionRunJobSummary(ctx context.Context, repoID, runID, runAttemptID, jobID, stepIndex int64) (*ActionRunJobSummary, error) {
530		var s ActionRunJobSummary
531		has, err := db.GetEngine(ctx).
532			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index=?", repoID, runID, runAttemptID, jobID, stepIndex).
533			Get(&s)
534		if err != nil {
535			return nil, err
536		}
537		if !has {
538			return nil, util.ErrNotExist
539		}
540		return &s, nil
541	}
542	
543	// ErrJobSummaryAggregateExceeded is returned when a step summary upload would push the
544	// aggregate size of summaries for a single job attempt over MaxJobSummaryAggregateSize.
545	var ErrJobSummaryAggregateExceeded = util.NewInvalidArgumentErrorf("job summary aggregate size exceeded")
546	
547	func UpsertActionRunJobSummary(ctx context.Context, repoID, runID, runAttemptID, jobID, stepIndex int64, contentType string, content []byte) error {
548		if runID <= 0 || jobID <= 0 || repoID <= 0 || stepIndex < 0 {
549			return util.ErrInvalidArgument
550		}
551		if len(content) == 0 {
552			// Treat empty summaries as no-op; runner may create SUMMARY.md but never write to it.
553			return nil
554		}
555		if len(content) > MaxJobSummarySize {
556			return util.ErrInvalidArgument
557		}
558		if contentType != JobSummaryContentTypeMarkdown {
559			return util.ErrInvalidArgument
560		}
561	
562		// The aggregate check is best-effort: a tx wouldn't actually serialize concurrent
563		// step uploads (no row-level lock on the parent job), so wrapping these two
564		// statements only adds round-trip cost without changing the race semantics.
565		// The current step is excluded because the upsert below replaces its size with len(content).
566		otherSize, err := sumOtherJobSummarySizes(ctx, repoID, runID, runAttemptID, jobID, stepIndex)
567		if err != nil {
568			return err
569		}
570		if otherSize+int64(len(content)) > MaxJobSummaryAggregateSize {
571			return ErrJobSummaryAggregateExceeded
572		}
573	
574		now := timeutil.TimeStampNow()
575		return upsertActionRunJobSummary(ctx, &ActionRunJobSummary{
576			RepoID:       repoID,
577			RunID:        runID,
578			RunAttemptID: runAttemptID,
579			JobID:        jobID,
580			StepIndex:    stepIndex,
581			Content:      string(content),
582			ContentSize:  int64(len(content)),
583			ContentType:  contentType,
584			Created:      now,
585			Updated:      now,
586		})
587	}
588	
589	// sumOtherJobSummarySizes returns the total stored size of all step summaries for a job
590	// except excludeStepIndex, computed in the database to avoid loading every row.
591	func sumOtherJobSummarySizes(ctx context.Context, repoID, runID, runAttemptID, jobID, excludeStepIndex int64) (int64, error) {
592		return db.GetEngine(ctx).
593			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index<>?", repoID, runID, runAttemptID, jobID, excludeStepIndex).
594			SumInt(new(ActionRunJobSummary), "content_size")
595	}
596	
597	// DeleteActionRunJobSummary removes the stored summary for a specific step. Used when
598	// a runner PUTs an empty body to clear a previously-uploaded step summary.
599	func DeleteActionRunJobSummary(ctx context.Context, repoID, runID, runAttemptID, jobID, stepIndex int64) error {
600		_, err := db.GetEngine(ctx).
601			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND job_id=? AND step_index=?", repoID, runID, runAttemptID, jobID, stepIndex).
602			Delete(new(ActionRunJobSummary))
603		return err
604	}
605	
606	func upsertActionRunJobSummary(ctx context.Context, summary *ActionRunJobSummary) error {
607		engine := db.GetEngine(ctx)
608		columns := "`repo_id`, `run_id`, `run_attempt_id`, `job_id`, `step_index`, `content`, `content_type`, `content_size`, `created`, `updated`"
609		values := []any{
610			summary.RepoID,
611			summary.RunID,
612			summary.RunAttemptID,
613			summary.JobID,
614			summary.StepIndex,
615			summary.Content,
616			summary.ContentType,
617			summary.ContentSize,
618			summary.Created,
619			summary.Updated,
620		}
621	
622		if setting.Database.Type.IsPostgreSQL() || setting.Database.Type.IsSQLite3() {
623			args := append([]any{"INSERT INTO `action_run_job_summary` (" + columns + ") VALUES (?,?,?,?,?,?,?,?,?,?) " +
624				"ON CONFLICT (`repo_id`, `run_id`, `run_attempt_id`, `job_id`, `step_index`) DO UPDATE SET " +
625				"`content` = excluded.`content`, `content_type` = excluded.`content_type`, `content_size` = excluded.`content_size`, `updated` = excluded.`updated`"}, values...)
626			_, err := engine.Exec(args...)
627			return err
628		}
629	
630		if setting.Database.Type.IsMySQL() {
631			args := append([]any{
632				"INSERT INTO `action_run_job_summary` (" + columns + ") VALUES (?,?,?,?,?,?,?,?,?,?) " +
633					"ON DUPLICATE KEY UPDATE `content` = VALUES(`content`), `content_type` = VALUES(`content_type`), `content_size` = VALUES(`content_size`), `updated` = VALUES(`updated`)",
634			}, values...)
635			_, err := engine.Exec(args...)
636			return err
637		}
638	
639		if setting.Database.Type.IsMSSQL() {
640			_, err := engine.Exec(`
641	MERGE INTO action_run_job_summary WITH (HOLDLOCK) AS target
642	USING (SELECT ? AS repo_id, ? AS run_id, ? AS run_attempt_id, ? AS job_id, ? AS step_index) AS source
643	ON target.repo_id = source.repo_id
644		AND target.run_id = source.run_id
645		AND target.run_attempt_id = source.run_attempt_id
646		AND target.job_id = source.job_id
647		AND target.step_index = source.step_index
648	WHEN MATCHED THEN
649		UPDATE SET content = ?, content_type = ?, content_size = ?, updated = ?
650	WHEN NOT MATCHED THEN
651		INSERT (repo_id, run_id, run_attempt_id, job_id, step_index, content, content_type, content_size, created, updated)
652		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
653	`,
654				summary.RepoID, summary.RunID, summary.RunAttemptID, summary.JobID, summary.StepIndex,
655				summary.Content, summary.ContentType, summary.ContentSize, summary.Updated,
656				summary.RepoID, summary.RunID, summary.RunAttemptID, summary.JobID, summary.StepIndex, summary.Content, summary.ContentType, summary.ContentSize, summary.Created, summary.Updated)
657			return err
658		}
659	
660		return util.ErrInvalidArgument
661	}
662	
663	// ListActionRunJobSummaries lists the stored summaries for a run attempt, ordered by job
664	// then step. A positive jobID scopes the lookup to that single job, used by the job view to
665	// avoid rendering every job's summary on each poll; jobID<=0 returns all jobs in the attempt.
666	func ListActionRunJobSummaries(ctx context.Context, repoID, runID, runAttemptID, jobID int64) ([]*ActionRunJobSummary, error) {
667		sess := db.GetEngine(ctx).Where("repo_id=? AND run_id=? AND run_attempt_id=?", repoID, runID, runAttemptID)
668		if jobID > 0 {
669			sess = sess.And("job_id=?", jobID)
670		}
671		var summaries []*ActionRunJobSummary
672		if err := sess.OrderBy("job_id ASC, step_index ASC").Find(&summaries); err != nil {
673			return nil, err
674		}
675		return summaries, nil
676	}

