    16	
    17	func Parse(content []byte, options ...ParseOption) ([]*SingleWorkflow, error) {
    18		origin, err := model.ReadWorkflow(bytes.NewReader(content))
    19		if err != nil {
    20			return nil, fmt.Errorf("model.ReadWorkflow: %w", err)
    21		}
    22	
    23		workflow := &SingleWorkflow{}
    24		if err := yaml.Unmarshal(content, workflow); err != nil {
    25			return nil, fmt.Errorf("yaml.Unmarshal: %w", err)
    26		}
    27	
    28		pc := &parseContext{}
    29		for _, o := range options {
    30			o(pc)
    31		}
    32		results := map[string]*JobResult{}
    33		for id, job := range origin.Jobs {
    34			if job == nil {
    35				return nil, fmt.Errorf("needed job not found: %q", id)
    36			}
    37			results[id] = &JobResult{
    38				Needs:   job.Needs(),
    39				Result:  pc.jobResults[id],
    40				Outputs: nil, // not supported yet
    41			}
    42		}
    43	
    44		var ret []*SingleWorkflow
    45		ids, jobs, err := workflow.jobs()
    46		if err != nil {
    47			return nil, fmt.Errorf("invalid jobs: %w", err)
    48		}
    49	
    50		evaluator := NewExpressionEvaluator(exprparser.NewInterpeter(&exprparser.EvaluationEnvironment{Github: pc.gitContext, Vars: pc.vars, Inputs: pc.inputs}, exprparser.Config{}))
    51		workflow.RunName = evaluator.Interpolate(workflow.RunName)
    52	
    53		for i, id := range ids {
    54			job := jobs[i]
    55			matricxes, err := getMatrixes(origin.GetJob(id))
    56			if err != nil {
    57				return nil, fmt.Errorf("getMatrixes: %w", err)
    58			}
    59			for _, matrix := range matricxes {
    60				job := job.Clone()
    61				if job.Name == "" {
    62					job.Name = id
    63				}
    64				job.Strategy.RawMatrix = encodeMatrix(matrix)
    65				evaluator := NewExpressionEvaluator(NewInterpeter(id, origin.GetJob(id), matrix, pc.gitContext, results, pc.vars, pc.inputs))
    66				job.Name = nameWithMatrix(job.Name, matrix, evaluator)
    67				runsOn := origin.GetJob(id).RunsOn()
    68				for i, v := range runsOn {
    69					runsOn[i] = evaluator.Interpolate(v)
    70				}
    71				job.RawRunsOn = encodeRunsOn(runsOn)
    72				if err := evaluator.EvaluateYamlNode(&job.RawContinueOnError); err != nil {
    73					return nil, fmt.Errorf("evaluate continue-on-error for job %q: %w", id, err)
    74				}
    75				swf := &SingleWorkflow{
    76					Name:           workflow.Name,
    77					RawOn:          workflow.RawOn,
    78					Env:            workflow.Env,
    79					Defaults:       workflow.Defaults,
    80					RawPermissions: workflow.RawPermissions,
    81					RunName:        workflow.RunName,
    82				}
    83				if err := swf.SetJob(id, job); err != nil {
    84					return nil, fmt.Errorf("SetJob: %w", err)
    85				}
    86				ret = append(ret, swf)
    87			}
    88		}
    89		return ret, nil
    90	}
    91	
    92	func WithGitContext(context *model.GithubContext) ParseOption {
    93		return func(c *parseContext) {
    94			c.gitContext = context
    95		}
    96	}
    97	
    98	func WithVars(vars map[string]string) ParseOption {
    99		return func(c *parseContext) {
   100			c.vars = vars
   101		}
   102	}
   103	
   104	func WithInputs(inputs map[string]any) ParseOption {
   105		return func(c *parseContext) {
   106			c.inputs = inputs
   107		}
   108	}
   109	
   110	type parseContext struct {
   111		jobResults map[string]string
   112		gitContext *model.GithubContext
   113		vars       map[string]string
   114		inputs     map[string]any
   115	}
   116	
   117	type ParseOption func(c *parseContext)
   118	
   119	func getMatrixes(job *model.Job) ([]map[string]any, error) {
   120		ret, err := job.GetMatrixes()
   121		if err != nil {
   122			return nil, fmt.Errorf("GetMatrixes: %w", err)
   123		}
   124		sort.Slice(ret, func(i, j int) bool {
   125			return matrixName(ret[i]) < matrixName(ret[j])
   126		})
   127		return ret, nil
   128	}
   129	
   130	func encodeMatrix(matrix map[string]any) yaml.Node {
   131		if len(matrix) == 0 {
   132			return yaml.Node{}
   133		}
   134		value := map[string][]any{}
   135		for k, v := range matrix {
   136			value[k] = []any{v}
   137		}
   138		node := yaml.Node{}
   139		_ = node.Encode(value)
   140		return node
   141	}
   142	
   143	func encodeRunsOn(runsOn []string) yaml.Node {
   144		node := yaml.Node{}
   145		if len(runsOn) == 1 {
   146			_ = node.Encode(runsOn[0])
   147		} else {
   148			_ = node.Encode(runsOn)
   149		}
   150		return node
   151	}
   152	
   153	func nameWithMatrix(name string, m map[string]any, evaluator *ExpressionEvaluator) string {
   154		if len(m) == 0 {
   155			return name
   156		}
   157	
   158		if !strings.Contains(name, "${{") || !strings.Contains(name, "}}") {
   159			return name + " " + matrixName(m)
   160		}
   161	
   162		return evaluator.Interpolate(name)
   163	}
   164	
   165	func matrixName(m map[string]any) string {
   166		ks := make([]string, 0, len(m))
   167		for k := range m {
   168			ks = append(ks, k)
   169		}
   170		sort.Strings(ks)
   171		vs := make([]string, 0, len(m))
   172		for _, v := range ks {
   173			vs = append(vs, fmt.Sprint(m[v]))
   174		}
   175	
   176		return fmt.Sprintf("(%s)", strings.Join(vs, ", "))
   177	}
