   193	package jobparser
   194	
   195	import (
   196		"gitea.com/gitea/runner/act/exprparser"
   197		"gitea.com/gitea/runner/act/model"
   198		"go.yaml.in/yaml/v4"
   199	)
   200	
   201	// NewInterpeter returns an interpeter used in the server,
   202	// need github, needs, strategy, matrix, inputs context only,
   203	// see https://docs.github.com/en/actions/learn-github-actions/contexts#context-availability
   204	func NewInterpeter(
   205		jobID string,
   206		job *model.Job,
   207		matrix map[string]any,
   208		gitCtx *model.GithubContext,
   209		results map[string]*JobResult,
   210		vars map[string]string,
   211		inputs map[string]any,
   212	) exprparser.Interpreter {
   213		strategy := make(map[string]any)
   214		if job.Strategy != nil {
   215			strategy["fail-fast"] = job.Strategy.FailFast
   216			strategy["max-parallel"] = job.Strategy.MaxParallel
   217		}
   218	
   219		run := &model.Run{
   220			Workflow: &model.Workflow{
   221				Jobs: map[string]*model.Job{},
   222			},
   223			JobID: jobID,
   224		}
   225		for id, result := range results {
   226			need := yaml.Node{}
   227			_ = need.Encode(result.Needs)
   228			run.Workflow.Jobs[id] = &model.Job{
   229				RawNeeds: need,
   230				Result:   result.Result,
   231				Outputs:  result.Outputs,
   232			}
   233		}
   234	
   235		jobs := run.Workflow.Jobs
   236		jobNeeds := run.Job().Needs()
   237	
   238		using := map[string]exprparser.Needs{}
   239		for _, need := range jobNeeds {
   240			if v, ok := jobs[need]; ok {
   241				using[need] = exprparser.Needs{
   242					Outputs: v.Outputs,
   243					Result:  v.Result,
   244				}
   245			}
   246		}
   247	
   248		ee := &exprparser.EvaluationEnvironment{
   249			Github:   gitCtx,
   250			Env:      nil, // no need
   251			Job:      nil, // no need
   252			Steps:    nil, // no need
   253			Runner:   nil, // no need
   254			Secrets:  nil, // no need
   255			Strategy: strategy,
   256			Matrix:   matrix,
   257			Needs:    using,
   258			Inputs:   inputs,
   259			Vars:     vars,
   260		}
   261	
   262		config := exprparser.Config{
   263			Run:        run,
   264			WorkingDir: "", // WorkingDir is used for  the function hashFiles, but it's not needed in the server
   265			Context:    "job",
   266		}
   267	
   268		return exprparser.NewInterpeter(ee, config)
   269	}
   270	
   271	// JobResult is the minimum requirement of job results for Interpeter
   272	type JobResult struct {
   273		Needs   []string
   274		Result  string
   275		Outputs map[string]string
   276	}
		}
		return []*Event{
			{Name: val},
		}, nil
	case yaml.SequenceNode:
		var val []any
		err := rawOn.Decode(&val)
		if err != nil {
			return nil, err
		}
		res := make([]*Event, 0, len(val))
		for _, v := range val {
			switch t := v.(type) {
			case string:
				if t == workflowCallEvent {
					continue
				}
				res = append(res, &Event{Name: t})
			default:
				return nil, fmt.Errorf("invalid type %T", t)
			}
		}
		return res, nil
	case yaml.MappingNode:
		events, triggers, err := parseMappingNode[yaml.Node](rawOn)
		if err != nil {
			return nil, err
		}
		res := make([]*Event, 0, len(events))
		for i, k := range events {
			if k == workflowCallEvent {
				continue
			}
			v := triggers[i]
			switch v.Kind {
			case yaml.ScalarNode:
				res = append(res, &Event{
					Name: k,
				})
			case yaml.SequenceNode:
				var t []any
				err := v.Decode(&t)
				if err != nil {
					return nil, err
				}
				schedules := make([]map[string]string, len(t))
				if k == "schedule" {
					for i, tt := range t {
						vv, ok := tt.(map[string]any)
						if !ok {
							return nil, fmt.Errorf("unknown on type(schedule): %#v", v)
						}
						schedules[i] = make(map[string]string, len(vv))
						for k, vvv := range vv {
							var ok bool
							if schedules[i][k], ok = vvv.(string); !ok {
								return nil, fmt.Errorf("unknown on type(schedule): %#v", v)
							}
						}
					}
				}

				if len(schedules) == 0 {
					schedules = nil
				}
				res = append(res, &Event{
					Name:      k,
					schedules: schedules,
				})
			case yaml.MappingNode:
				acts := make(map[string][]string, len(v.Content)/2)
				var inputs []WorkflowDispatchInput
				expectedKey := true
				var act string
				for _, content := range v.Content {
					if expectedKey {
						if content.Kind != yaml.ScalarNode {
							return nil, fmt.Errorf("key type not string: %#v", content)
						}
						act = ""
						err := content.Decode(&act)
						if err != nil {
							return nil, err
						}
					} else {
						switch content.Kind {
						case yaml.SequenceNode:
							var t []string
							err := content.Decode(&t)
							if err != nil {
								return nil, err
							}
							acts[act] = t
						case yaml.ScalarNode:
							var t string
							err := content.Decode(&t)
							if err != nil {
								return nil, err
							}
							acts[act] = []string{t}
						case yaml.MappingNode:
							if k != "workflow_dispatch" || act != "inputs" {
								return nil, fmt.Errorf("map should only for workflow_dispatch but %s: %#v", act, content)
							}

							var key string
							for i, vv := range content.Content {
								if i%2 == 0 {
									if vv.Kind != yaml.ScalarNode {
										return nil, fmt.Errorf("key type not string: %#v", vv)
									}
									key = ""
									if err := vv.Decode(&key); err != nil {
										return nil, err
									}
								} else {
									if vv.Kind != yaml.MappingNode {
										return nil, fmt.Errorf("key type not map(%s): %#v", key, vv)
									}

									input := WorkflowDispatchInput{}
									if err := vv.Decode(&input); err != nil {
										return nil, err
									}
									input.Name = key
									inputs = append(inputs, input)
								}
							}
						default:
							return nil, fmt.Errorf("unknown on type: %#v", content)
						}
					}
					expectedKey = !expectedKey
				}
				if len(inputs) == 0 {
					inputs = nil
				}
				if len(acts) == 0 {
					acts = nil
				}
				res = append(res, &Event{
					Name:   k,
					acts:   acts,
					inputs: inputs,
				})
			default:
				return nil, fmt.Errorf("unknown on type: %v", v.Kind)
			}
		}
		return res, nil
	default:
		return nil, fmt.Errorf("unknown on type: %v", rawOn.Kind)
	}
}

func EvaluateJobIfExpression(jobID string, job *Job, gitCtx map[string]any, results map[string]*JobResult, vars map[string]string, inputs map[string]any) (bool, error) {
	actJob := &model.Job{
		Strategy: &model.Strategy{
			FailFastString:    job.Strategy.FailFastString,
			MaxParallelString: job.Strategy.MaxParallelString,
			RawMatrix:         job.Strategy.RawMatrix,
		},
	}
	evaluator := NewExpressionEvaluator(NewInterpeter(jobID, actJob, nil, toGitContext(gitCtx), results, vars, inputs))
	expr, err := rewriteSubExpression(job.If.Value, false)
	if err != nil {
		return false, err
	}
	result, err := evaluator.evaluate(expr, exprparser.DefaultStatusCheckSuccess)
	if err != nil {
		return false, err
	}
	return exprparser.IsTruthy(result), nil
}

// parseMappingNode parse a mapping node and preserve order.
func parseMappingNode[T any](node *yaml.Node) ([]string, []T, error) {
	if node.Kind != yaml.MappingNode {
		return nil, nil, errors.New("input node is not a mapping node")
	}

	var scalars []string
	var datas []T
	expectKey := true
	for _, item := range node.Content {
		if expectKey {
			if item.Kind != yaml.ScalarNode {
				return nil, nil, fmt.Errorf("not a valid scalar node: %v", item.Value)
			}
			scalars = append(scalars, item.Value)
			expectKey = false
		} else {
			var val T
			if err := item.Decode(&val); err != nil {
				return nil, nil, err
			}
			datas = append(datas, val)
			expectKey = true
		}
	}

	if len(scalars) != len(datas) {
		return nil, nil, fmt.Errorf("invalid definition of on: %v", node.Value)
	}

	return scalars, datas, nil
}

func asString(v any) string {
	if v == nil {
		return ""
	} else if s, ok := v.(string); ok {
		return s
	}
	return ""
}

