package actions

import (
	"fmt"
	"sort"
	"strings"
	"testing"

	actions_model "gitea.dev/models/actions"
	"gitea.dev/models/db"
	repo_model "gitea.dev/models/repo"
	"gitea.dev/models/unittest"
	actions_module "gitea.dev/modules/actions"

	"github.com/stretchr/testify/require"
)

var probeIdx int64 = 9800

type e2e struct {
	name    string
	event   string
	payload string
	inputs  map[string]any
	yaml    string
	finish  map[string]actions_model.Status // job id -> final status for jobs that start right away
	expect  string
}

func (c e2e) run(t *testing.T) {
	ctx := t.Context()
	repo := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	probeIdx++
	ev := c.event
	if ev == "" {
		ev = "push"
	}
	pl := c.payload
	if pl == "" {
		pl = "{}"
	}
	run := &actions_model.ActionRun{RepoID: 4, OwnerID: repo.OwnerID, TriggerUserID: 1, WorkflowID: fmt.Sprintf("p%d.yml", probeIdx), Ref: "refs/heads/master", CommitSHA: "abc", Event: "push", TriggerEvent: ev, EventPayload: pl, WorkflowRepoID: 4}
	if ev == "workflow_dispatch" {
		run.Event = "workflow_dispatch"
	}
	require.NoError(t, run.LoadAttributes(ctx))
	t.Logf("== %s", c.name)
	if err := actions_module.ValidateWorkflowContent([]byte(c.yaml)); err != nil {
		t.Logf("   detect-time validation error: %v", err)
	}
	if err := InsertRun(ctx, run, []byte(c.yaml), nil, c.inputs, nil); err != nil {
		t.Logf("   InsertRun error: %v", err)
		return
	}
	show := func(label string) {
		jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, run.LatestAttemptID)
		var parts []string
		for _, j := range jobs {
			parts = append(parts, fmt.Sprintf("%s=%s", j.Name, j.Status))
		}
		sort.Strings(parts)
		r := unittest.AssertExistsAndLoadBean(t, &actions_model.ActionRun{ID: run.ID})
		t.Logf("   %-14s run=%s  %s", label, r.Status, strings.Join(parts, "  "))
	}
	show("after insert:")
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, run.LatestAttemptID)
	for _, j := range jobs {
		if st, ok := c.finish[j.JobID]; ok && j.Status == actions_model.StatusWaiting {
			j.Status = st
			_, err := actions_model.UpdateRunJob(ctx, j, nil, "status")
			require.NoError(t, err)
		}
	}
	func() {
		defer func() {
			if r := recover(); r != nil {
				t.Logf("   emitter PANIC: %v", r)
			}
		}()
		if err := checkJobsByRunID(ctx, run.ID); err != nil {
			t.Logf("   emitter error: %v", err)
		}
	}()
	show("after emitter:")
	if c.expect != "" {
		t.Logf("   expected:      %s", c.expect)
	}
}

func TestProbe_E2E(t *testing.T) {
	require.NoError(t, unittest.PrepareTestDatabase())
	S, F := actions_model.StatusSuccess, actions_model.StatusFailure
	job := func(id, extra string) string {
		return "  " + id + ":\n    runs-on: ubuntu-latest\n" + extra + "    steps:\n      - run: echo\n"
	}
	wf := func(on string, jobs ...string) string { return "on: " + on + "\njobs:\n" + strings.Join(jobs, "") }
	cases := []e2e{
		{name: "control: if always(), need failed", yaml: wf("push", job("build", ""), job("report", "    needs: build\n    if: always()\n")), finish: map[string]actions_model.Status{"build": F}, expect: "report=waiting"},
		{name: "control: no if, need failed", yaml: wf("push", job("build", ""), job("deploy", "    needs: build\n")), finish: map[string]actions_model.Status{"build": F}, expect: "deploy=skipped"},
		{name: "if: !cancelled(), need failed", yaml: wf("push", job("build", ""), job("report", "    needs: build\n    if: ${{ !cancelled() }}\n")), finish: map[string]actions_model.Status{"build": F}, expect: "report=waiting"},
		{name: "if: always() && !cancelled()", yaml: wf("push", job("build", ""), job("report", "    needs: build\n    if: always() && !cancelled()\n")), finish: map[string]actions_model.Status{"build": S}, expect: "report=waiting"},
		{name: "if: failure(), need failed", yaml: wf("push", job("build", ""), job("notify", "    needs: build\n    if: failure()\n")), finish: map[string]actions_model.Status{"build": F}, expect: "notify=waiting"},
		{name: "if on matrix value, with needs", yaml: wf("push", job("build", ""), job("test", "    needs: build\n    if: matrix.os == 'linux'\n    strategy:\n      matrix:\n        os: [linux, windows]\n")), finish: map[string]actions_model.Status{"build": S}, expect: "test (linux)=waiting  test (windows)=skipped"},
		{name: "if: ${{ matrix.deploy }} via include, with needs", yaml: wf("push", job("build", ""), job("pub", "    needs: build\n    if: ${{ matrix.deploy }}\n    strategy:\n      matrix:\n        include:\n          - {target: a, deploy: true}\n          - {target: b, deploy: false}\n")), finish: map[string]actions_model.Status{"build": S}, expect: "pub (true, a)=waiting  pub (false, b)=skipped"},
		{name: "needs typo, no if", yaml: wf("push", job("build", ""), job("deploy", "    needs: [biuld]\n")), finish: map[string]actions_model.Status{}, expect: "workflow rejected, or deploy never starts before build"},
		{name: "needs typo, with if", yaml: wf("push", job("build", ""), job("deploy", "    needs: [biuld]\n    if: github.ref == 'refs/heads/master'\n")), finish: map[string]actions_model.Status{}, expect: "workflow rejected"},
		{name: "needs cycle", yaml: wf("push", job("a", "    needs: b\n"), job("b", "    needs: a\n")), expect: "workflow rejected"},
		{name: "dispatch boolean input false: if: ${{ inputs.deploy }}", event: "workflow_dispatch", payload: `{"inputs":{"deploy":"false"}}`, inputs: map[string]any{"deploy": "false"},
			yaml: "on:\n  workflow_dispatch:\n    inputs:\n      deploy:\n        type: boolean\n        default: false\njobs:\n" + job("build", "") + job("deploy", "    needs: build\n    if: ${{ inputs.deploy }}\n"), finish: map[string]actions_model.Status{"build": S}, expect: "deploy=skipped"},
		{name: "dispatch boolean input true: if: inputs.deploy == true", event: "workflow_dispatch", payload: `{"inputs":{"deploy":"true"}}`, inputs: map[string]any{"deploy": "true"},
			yaml: "on:\n  workflow_dispatch:\n    inputs:\n      deploy:\n        type: boolean\n        default: false\njobs:\n" + job("build", "") + job("deploy", "    needs: build\n    if: inputs.deploy == true\n"), finish: map[string]actions_model.Status{"build": S}, expect: "deploy=waiting"},
		{name: "dispatch boolean input false: if: ${{ !inputs.skip_tests }}", event: "workflow_dispatch", payload: `{"inputs":{"skip_tests":"false"}}`, inputs: map[string]any{"skip_tests": "false"},
			yaml: "on:\n  workflow_dispatch:\n    inputs:\n      skip_tests:\n        type: boolean\n        default: false\njobs:\n" + job("build", "") + job("test", "    needs: build\n    if: ${{ !inputs.skip_tests }}\n"), finish: map[string]actions_model.Status{"build": S}, expect: "test=waiting"},
		{name: "if: always() && !contains(needs.*.result, 'failure')", yaml: wf("push", job("a", ""), job("b", ""), job("gate", "    needs: [a, b]\n    if: always() && !contains(needs.*.result, 'failure')\n")), finish: map[string]actions_model.Status{"a": S, "b": F}, expect: "gate=skipped"},
		{name: "continue-on-error need failed, downstream has explicit if", yaml: wf("push", job("lint", "    continue-on-error: true\n"), job("deploy", "    needs: lint\n    if: github.ref == 'refs/heads/master'\n")), finish: map[string]actions_model.Status{"lint": F}, expect: "deploy=waiting (same as with no if)"},
		{name: "continue-on-error need failed, downstream checks needs.lint.result", yaml: wf("push", job("lint", "    continue-on-error: true\n"), job("warn", "    needs: lint\n    if: always() && needs.lint.result == 'failure'\n")), finish: map[string]actions_model.Status{"lint": F}, expect: "warn=waiting"},
		{name: "if with double-quoted string", yaml: wf("push", job("build", ""), job("deploy", "    needs: build\n    if: github.ref == \"refs/heads/master\"\n")), finish: map[string]actions_model.Status{"build": S}, expect: "workflow rejected, or job failed with a message"},
		{name: "if referencing workflow env", yaml: "on: push\nenv:\n  DEPLOY: 'true'\njobs:\n" + job("build", "") + job("deploy", "    needs: build\n    if: env.DEPLOY == 'true'\n"), finish: map[string]actions_model.Status{"build": S}, expect: "workflow rejected (env not allowed in job if)"},
		{name: "skipped chain: b needs a(if false); c needs b always()", yaml: wf("push", job("build", ""), job("a", "    needs: build\n    if: false\n"), job("b", "    needs: a\n"), job("c", "    needs: b\n    if: always()\n")), finish: map[string]actions_model.Status{"build": S}, expect: "a=skipped b=skipped c=waiting"},
		{name: "transitive failure: c needs b needs a(failed), c has if: success()", yaml: wf("push", job("a", ""), job("b", "    needs: a\n    if: always()\n"), job("c", "    needs: b\n")), finish: map[string]actions_model.Status{"a": F}, expect: "b=waiting"},
		{name: "runs-on from needs output", yaml: wf("push", job("pick", ""), "  build:\n    needs: pick\n    runs-on: ${{ needs.pick.outputs.runner }}\n    steps:\n      - run: echo\n"), finish: map[string]actions_model.Status{"pick": S}, expect: "build waiting with a real label"},
	}
	for _, c := range cases {
		c.run(t)
	}
	// extra: what label does the stuck job carry
	var js []*actions_model.ActionRunJob
	_ = db.GetEngine(t.Context()).Where("job_id = ? AND repo_id = 4", "build").Desc("id").Limit(1).Find(&js)
	if len(js) == 1 {
		t.Logf("last 'build' job: status=%s runs_on=%q", js[0].Status, js[0].RunsOn)
	}
}
