	t.Log("== C1 cancel a running job, runner WITHOUT cancelling support")
	{
		r := e.runner("c1", []string{"probe"})
		run := e.newRun(pipeline, nil)
		task := r.fetch()
		r.logs(task.Id, 0, 2, false)
		r.update(task.Id, NONE, nil)
		e.cancel(run.ID)
		e.dump("after cancel:", run.ID)
		t.Logf("     runner heartbeat: %s ; final report success: %s ; final logs: %s", r.update(task.Id, NONE, nil), r.update(task.Id, OK, nil), r.logs(task.Id, 2, 1, true))
		e.flush()
		e.dump("after runner wrapped up:", run.ID)
