)

const headSHA = "c7cd3cd144e6d23c9d6f3d07e52b2c1a956e0338"

type env struct {
	t    *testing.T
	ctx  context.Context
	srv  *httptest.Server
	repo *repo_model.Repository
	user *user_model.User
	idx  int64
}

type fakeRunner struct {
	e      *env
	name   string
	client runnerv1connect.RunnerServiceClient
	id     int64
}

func newEnv(t *testing.T) *env {
	require.NoError(t, unittest.PrepareTestDatabase())
	path, h := runner_api.NewRunnerServiceHandler()
	mux := http.NewServeMux()
	mux.Handle(path, h)
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	e := &env{t: t, ctx: t.Context(), srv: srv, idx: 7000}
	e.repo = unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	e.user = unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	return e
}

func (e *env) runner(name string, labels []string, caps ...string) *fakeRunner {
	tok, err := actions_model.NewRunnerToken(e.ctx, 0, 0)
	require.NoError(e.t, err)
	plain := runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL)
	resp, err := plain.Register(e.ctx, connect.NewRequest(&runnerv1.RegisterRequest{Name: name, Token: tok.Token, Labels: labels, Version: "probe", Capabilities: caps}))
	require.NoError(e.t, err)
	uuid, token := resp.Msg.Runner.Uuid, resp.Msg.Runner.Token
	ic := connect.UnaryInterceptorFunc(func(next connect.UnaryFunc) connect.UnaryFunc {
		return func(ctx context.Context, req connect.AnyRequest) (connect.AnyResponse, error) {
			req.Header().Set("x-runner-uuid", uuid)
			req.Header().Set("x-runner-token", token)
			return next(ctx, req)
		}
	})
	return &fakeRunner{e: e, name: name, id: resp.Msg.Runner.Id, client: runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL, connect.WithInterceptors(ic))}
}

func (r *fakeRunner) fetch() *runnerv1.Task {
	resp, err := r.client.FetchTask(r.e.ctx, connect.NewRequest(&runnerv1.FetchTaskRequest{TasksVersion: 0}))
	if err != nil {
		r.e.t.Logf("     [%s] FetchTask error: %v", r.name, err)
		return nil
	}
	return resp.Msg.Task
}

func (r *fakeRunner) update(taskID int64, result runnerv1.Result, outputs map[string]string) string {
	now := timestamppb.Now()
	st := &runnerv1.TaskState{Id: taskID, Result: result, StartedAt: now, Steps: []*runnerv1.StepState{{Id: 0, StartedAt: now}}}
	if result != runnerv1.Result_RESULT_UNSPECIFIED {
		st.StoppedAt = now
		st.Steps[0].Result = result
		st.Steps[0].StoppedAt = now
	}
	resp, err := r.client.UpdateTask(r.e.ctx, connect.NewRequest(&runnerv1.UpdateTaskRequest{State: st, Outputs: outputs}))
	if err != nil {
		return "RPC ERROR: " + err.Error()
	}
	return "server says " + strings.TrimPrefix(resp.Msg.State.Result.String(), "RESULT_")
}

func (r *fakeRunner) logs(taskID, index int64, n int, noMore bool) string {
	rows := make([]*runnerv1.LogRow, n)
	for i := range rows {
		rows[i] = &runnerv1.LogRow{Time: timestamppb.Now(), Content: fmt.Sprintf("line %d", index+int64(i))}
	}
	resp, err := r.client.UpdateLog(r.e.ctx, connect.NewRequest(&runnerv1.UpdateLogRequest{TaskId: taskID, Index: index, Rows: rows, NoMore: noMore}))
	if err != nil {
		return "RPC ERROR: " + err.Error()
	}
	return fmt.Sprintf("ack=%d", resp.Msg.AckIndex)
}

func (e *env) newRun(yaml string, mod func(*actions_model.ActionRun)) *actions_model.ActionRun {
	e.idx++
	run := &actions_model.ActionRun{Title: "probe", RepoID: e.repo.ID, OwnerID: e.repo.OwnerID, WorkflowID: fmt.Sprintf("probe%d.yml", e.idx), TriggerUserID: e.user.ID, Ref: "refs/heads/master", CommitSHA: headSHA, Event: "push", TriggerEvent: "push", EventPayload: "{}", WorkflowRepoID: e.repo.ID, WorkflowCommitSHA: headSHA}
	if mod != nil {
		mod(run)
	}
	if err := actions_service.PrepareRunAndInsert(e.ctx, []byte(yaml), run, nil); err != nil {
		e.t.Logf("     PrepareRunAndInsert error: %v", err)
		return nil
	}
	e.flush()
	return run
}

func (e *env) flush() {
	if err := actions_service.ProbeFlush(e.ctx); err != nil {
		e.t.Logf("     (emitter flush: %v)", err)
	}
}

func (e *env) dump(label string, runID int64) {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: runID})
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(e.ctx, run.ID, run.LatestAttemptID)
	var parts []string
	for _, j := range jobs {
		s := fmt.Sprintf("%s=%s", j.Name, j.Status)
		if j.TaskID > 0 {
			task, _ := actions_model.GetTaskByID(e.ctx, j.TaskID)
			steps, _ := actions_model.GetTaskStepsByTaskID(e.ctx, j.TaskID)
			var ss []string
			for _, st := range steps {
				ss = append(ss, st.Status.String())
			}
			s += fmt.Sprintf("[task:%s steps:%s logInStorage:%v]", task.Status, strings.Join(ss, ","), task.LogInStorage)
		}
		parts = append(parts, s)
	}
	att := ""
	if a, has, _ := run.GetLatestAttempt(e.ctx); has {
		att = fmt.Sprintf(" attempt#%d=%s", a.Attempt, a.Status)
	}
	e.t.Logf("   %-34s run=%s%s | %s", label, run.Status, att, strings.Join(parts, "  "))
}

// cancel mirrors routers/web/repo/actions/view.go Cancel()
func (e *env) cancelWith(runID int64, jobs []*actions_model.ActionRunJob) {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: runID})
	require.NoError(e.t, run.LoadAttributes(e.ctx))
	var updated []*actions_model.ActionRunJob
	err := db.WithTx(e.ctx, func(ctx context.Context) error {
		c, err := actions_model.CancelJobs(ctx, jobs)
		updated = append(updated, c...)
		return err
	})
	if err != nil {
		e.t.Logf("     cancel error: %v", err)
		return
	}
	actions_service.CreateCommitStatusForRunJobs(e.ctx, run, jobs...)
	actions_service.EmitJobsIfReadyByJobs(updated)
	e.flush()
}

func (e *env) latestJobs(runID int64) []*actions_model.ActionRunJob {
	jobs, err := actions_model.GetLatestAttemptJobsByRepoAndRunID(e.ctx, e.repo.ID, runID)
	require.NoError(e.t, err)
	return jobs
}

func (e *env) cancel(runID int64) { e.cancelWith(runID, e.latestJobs(runID)) }

func (e *env) rerun(runID int64, failedOnly bool, jobIDs ...string) {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: runID})
	jobs := e.latestJobs(runID)
	var sel []*actions_model.ActionRunJob
	if failedOnly {
		sel = actions_service.GetFailedJobsForRerun(jobs)
	}
	for _, j := range jobs {
		for _, id := range jobIDs {
			if j.JobID == id {
				sel = append(sel, j)
			}
		}
	}
	if _, err := actions_service.RerunWorkflowRunJobs(e.ctx, e.repo, run, e.user, sel); err != nil {
		e.t.Logf("     rerun refused: %v", err)
	}
	e.flush()
}

func (e *env) exec(sql string, args ...any) {
	_, err := db.GetEngine(e.ctx).Exec(append([]any{sql}, args...)...)
	require.NoError(e.t, err)
}

func ago(d time.Duration) timeutil.TimeStamp { return timeutil.TimeStamp(time.Now().Add(-d).Unix()) }

func job(id, extra string) string {
	return "  " + id + ":\n    runs-on: probe\n" + extra + "    steps:\n      - run: echo\n"
}
func wf(jobs ...string) string { return "on: push\njobs:\n" + strings.Join(jobs, "") }

const (
	OK   = runnerv1.Result_RESULT_SUCCESS
	FAIL = runnerv1.Result_RESULT_FAILURE
	NONE = runnerv1.Result_RESULT_UNSPECIFIED
)

func needsOf(t *runnerv1.Task) string {
	var parts []string
	for k, v := range t.Needs {
		parts = append(parts, fmt.Sprintf("%s:{result:%s outputs:%v}", k, strings.TrimPrefix(v.Result.String(), "RESULT_"), v.Outputs))
	}
	return strings.Join(parts, " ")
}

func TestProbe_Lifecycle(t *testing.T) {
	e := newEnv(t)
	require.True(t, actions_service.ProbeInitQueue())
	t.Logf("timeouts: zombie=%v endless=%v abandoned=%v", setting.Actions.ZombieTaskTimeout, setting.Actions.EndlessTaskTimeout, setting.Actions.AbandonedJobTimeout)
	pipeline := wf(job("build", ""), job("deploy", "    needs: build\n"), job("cleanup", "    needs: build\n    if: always()\n"))

	t.Log("== Z1 runner vanishes mid-job after sending logs; zombie cron; runner comes back")
	{
		r := e.runner("z1", []string{"probe"})
		run := e.newRun(pipeline, nil)
		task := r.fetch()
		t.Logf("     heartbeat: %s ; logs: %s", r.update(task.Id, NONE, nil), r.logs(task.Id, 0, 3, false))
		e.dump("runner working:", run.ID)
		e.exec("UPDATE action_task SET updated=? WHERE id=?", ago(11*time.Minute), task.Id)
		require.NoError(t, actions_service.StopZombieTasks(e.ctx))
		e.flush()
		e.dump("after zombie cron:", run.ID)
		t.Logf("     runner returns: late logs: %s ; final success: %s", r.logs(task.Id, 3, 2, true), r.update(task.Id, OK, nil))
		e.dump("after runner returned:", run.ID)
		e.cancel(run.ID)
	}

	t.Log("== Z2 runner vanishes before sending any log line; zombie cron")
	{
		r := e.runner("z2", []string{"probe"})
		run := e.newRun(wf(job("build", "")), nil)
		task := r.fetch()
		e.exec("UPDATE action_task SET updated=? WHERE id=?", ago(11*time.Minute), task.Id)
		require.NoError(t, actions_service.StopZombieTasks(e.ctx))
		e.flush()
		e.dump("after zombie cron:", run.ID)
		tk, _ := actions_model.GetTaskByID(e.ctx, task.Id)
		_, err := actions_module.ReadLogs(e.ctx, tk.LogInStorage, tk.LogFilename, 0, -1)
		t.Logf("     reading that job's log afterwards: err=%v", err)
		require.NoError(t, actions_service.StopZombieTasks(e.ctx))
	}

	t.Log("== Z3 long job hits the endless timeout while runner is alive")
	{
		r := e.runner("z3", []string{"probe"})
		run := e.newRun(wf(job("build", "")), nil)
		task := r.fetch()
		r.logs(task.Id, 0, 2, false)
		e.exec("UPDATE action_task SET started=? WHERE id=?", ago(4*time.Hour), task.Id)
		require.NoError(t, actions_service.StopEndlessTasks(e.ctx))
		e.flush()
		e.dump("after endless cron:", run.ID)
		t.Logf("     runner heartbeat: %s ; more logs: %s", r.update(task.Id, NONE, nil), r.logs(task.Id, 2, 1, false))
	}

	t.Log("== Z4 abandoned cron: downstream job blocked >24h while its upstream is actively running")
	{
		r := e.runner("z4", []string{"probe"})
		run := e.newRun(wf(job("build", ""), job("deploy", "    needs: build\n")), nil)
		// the run sat in the queue for a day before a runner became free
		e.exec("UPDATE action_run_job SET updated=? WHERE run_id=?", ago(25*time.Hour), run.ID)
		task := r.fetch()
		r.update(task.Id, NONE, nil)
		e.dump("build picked after 25h in queue:", run.ID)
		require.NoError(t, actions_service.CancelAbandonedJobs(e.ctx))
		e.flush()
		e.dump("after abandoned cron:", run.ID)
		t.Logf("     build finishes: %s", r.update(task.Id, OK, nil))
		e.flush()
		e.dump("build succeeded:", run.ID)
	}

	t.Log("== C1 cancel a running job, runner WITHOUT cancelling support")
	{
		r := e.runner("c1", []string{"probe"})
		run := e.newRun(pipeline, nil)
		task := r.fetch()
		r.logs(task.Id, 0, 2, false)
		r.update(task.Id, NONE, nil)
		e.cancel(run.ID)
		e.dump("after cancel:", run.ID)
		t.Logf("     runner heartbeat: %s ; final report success: %s ; final logs: %s", r.update(task.Id, NONE, nil), r.update(task.Id, OK, nil), r.logs(task.Id, 2, 1, true))
		e.flush()
		e.dump("after runner wrapped up:", run.ID)
	}

	t.Log("== C2 cancel a running job, runner WITH cancelling support; then runner vanishes")
	{
		r := e.runner("c2", []string{"probe"}, "cancelling")
		run := e.newRun(pipeline, nil)
		task := r.fetch()
		r.update(task.Id, NONE, nil)
		e.cancel(run.ID)
		e.dump("after cancel:", run.ID)
		tok := task.Context.Fields["token"].GetStringValue()
		_, tokErr := actions_model.GetRunningTaskByToken(e.ctx, tok)
		t.Logf("     while cancelling: job token accepted=%v ; runtime-token check (CheckTaskIsRunning)=%v", tokErr == nil, auth_service.CheckTaskIsRunning(e.ctx, task.Id))
		t.Logf("     runner heartbeat: %s", r.update(task.Id, NONE, nil))
		e.rerun(run.ID, false)
		e.cancel(run.ID)
		e.dump("cancel again + rerun attempt:", run.ID)
		e.exec("UPDATE action_task SET updated=? WHERE id=?", ago(11*time.Minute), task.Id)
		require.NoError(t, actions_service.StopZombieTasks(e.ctx))
		e.flush()
		e.dump("after zombie cron:", run.ID)
	}

	t.Log("== C3 cancel with cancelling support, runner finishes its cleanup and reports SUCCESS")
	{
		r := e.runner("c3", []string{"probe"}, "cancelling")
		run := e.newRun(pipeline, nil)
		task := r.fetch()
		r.update(task.Id, NONE, nil)
		e.cancel(run.ID)
		t.Logf("     runner final: %s", r.update(task.Id, OK, nil))
		e.flush()
		e.dump("after runner final:", run.ID)
	}

	t.Log("== C4 cancel races with a runner picking the job")
	{
		r := e.runner("c4", []string{"probe"})
		run := e.newRun(wf(job("build", "")), nil)
		stale := e.latestJobs(run.ID) // what the cancel request loaded
		task := r.fetch()             // runner claims it in between
		e.cancelWith(run.ID, stale)
		e.dump("after cancel returned OK:", run.ID)
		t.Logf("     runner heartbeat: %s", r.update(task.Id, NONE, nil))
		e.cancel(run.ID)
	}

	t.Log("== R1 rerun failed jobs; downstream must see pass-through outputs")
	{
		r := e.runner("r1", []string{"probe"})
		run := e.newRun(wf(job("build", "    outputs:\n      v: ${{ steps.x.outputs.v }}\n"), job("test", "    needs: build\n"), job("deploy", "    needs: [build, test]\n")), nil)
		b := r.fetch()
		r.update(b.Id, OK, map[string]string{"v": "1.2.3"})
		e.flush()
		tt := r.fetch()
		r.update(tt.Id, FAIL, nil)
		e.flush()
		e.dump("first attempt done:", run.ID)
		e.rerun(run.ID, true)
		e.dump("after 'rerun failed':", run.ID)
		t2 := r.fetch()
		if t2 != nil {
			t.Logf("     runner got job; needs = %s ; run_attempt=%v", needsOf(t2), t2.Context.Fields["run_attempt"].GetStringValue())
			r.update(t2.Id, OK, nil)
			e.flush()
			e.dump("test passed on rerun:", run.ID)
			if t3 := r.fetch(); t3 != nil {
				t.Logf("     runner got next job; needs = %s", needsOf(t3))
				r.update(t3.Id, OK, nil)
				e.flush()
			}
			e.dump("end:", run.ID)
		}
	}

	t.Log("== R2 rerun ONE job whose upstream failed (it was skipped)")
	{
		r := e.runner("r2", []string{"probe"})
		run := e.newRun(wf(job("build", ""), job("deploy", "    needs: build\n")), nil)
		b := r.fetch()
		r.update(b.Id, FAIL, nil)
		e.flush()
		e.dump("first attempt done:", run.ID)
		e.rerun(run.ID, false, "deploy")
		e.dump("after rerun of 'deploy' only:", run.ID)
		if t2 := r.fetch(); t2 != nil {
			t.Logf("     runner was handed a job; needs = %s", needsOf(t2))
			r.update(t2.Id, OK, nil)
			e.flush()
			e.dump("deploy ran:", run.ID)
		}
	}

	t.Log("== R3 hard-cancel, immediate rerun, old runner still finishing the old task")
	{
		r := e.runner("r3", []string{"probe"})
		run := e.newRun(wf(job("build", "")), nil)
		old := r.fetch()
		r.update(old.Id, NONE, nil)
		e.cancel(run.ID)
		e.rerun(run.ID, false)
		e.dump("after cancel + rerun:", run.ID)
		t.Logf("     old task final success: %s ; old task logs: %s", r.update(old.Id, OK, nil), r.logs(old.Id, 0, 2, true))
		e.flush()
		e.dump("after old task reported:", run.ID)
		if nt := r.fetch(); nt != nil {
			r.update(nt.Id, OK, nil)
			e.flush()
		}
		e.dump("end:", run.ID)
	}

	t.Log("== R4 fork-PR run awaiting approval is cancelled, then re-run")
	{
		r := e.runner("r4", []string{"probe"})
		run := e.newRun(wf(job("build", "")), func(run *actions_model.ActionRun) { run.IsForkPullRequest = true; run.NeedApproval = true })
		e.dump("awaiting approval:", run.ID)
		t.Logf("     runner offered a job: %v", r.fetch() != nil)
		e.cancel(run.ID)
		e.rerun(run.ID, false)
		e.dump("after cancel + rerun:", run.ID)
		rr := unittest.AssertExistsAndLoadBean(t, &actions_model.ActionRun{ID: run.ID})
		got := r.fetch()
		t.Logf("     need_approval still=%v approved_by=%d ; runner offered the job: %v", rr.NeedApproval, rr.ApprovedBy, got != nil)
		if got != nil {
			r.update(got.Id, OK, nil)
			e.flush()
		}
	}

	t.Log("== R5 double-click rerun")
	{
		r := e.runner("r5", []string{"probe"})
		run := e.newRun(wf(job("build", "")), nil)
		b := r.fetch()
		r.update(b.Id, FAIL, nil)
		e.flush()
		e.rerun(run.ID, false)
		e.rerun(run.ID, false)
		e.dump("after two reruns:", run.ID)
		e.cancel(run.ID)
	}
}
