package actions

import (
	"context"
	"time"

	actions_model "gitea.dev/models/actions"
	user_model "gitea.dev/models/user"
	"gitea.dev/modules/graceful"
	"gitea.dev/modules/queue"
)

func ProbeInitQueue() bool {
	if jobEmitterQueue != nil {
		return true
	}
	jobEmitterQueue = queue.CreateUniqueQueue(graceful.GetManager().ShutdownContext(), "actions_ready_job", jobEmitterQueueHandler)
	if jobEmitterQueue == nil {
		return false
	}
	go graceful.GetManager().RunWithCancel(jobEmitterQueue)
	return true
}

func ProbeFlush(ctx context.Context) error {
	return jobEmitterQueue.FlushWithContext(ctx, 10*time.Second)
}

// ProbeTwoReruns builds two rerun plans from the same state (two requests that both passed validation), then executes both.
func ProbeTwoReruns(ctx context.Context, run1, run2 *actions_model.ActionRun, u *user_model.User) (error, error) {
	p1, err := buildRerunPlan(ctx, run1, u, nil)
	if err != nil {
		return err, nil
	}
	p2, err := buildRerunPlan(ctx, run2, u, nil)
	if err != nil {
		return nil, err
	}
	_, e1 := execRerunPlan(ctx, p1)
	_, e2 := execRerunPlan(ctx, p2)
	return e1, e2
}
EOF
