package actions_test

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	runnerv1 "gitea.dev/actions-proto-go/runner/v1"
	"gitea.dev/actions-proto-go/runner/v1/runnerv1connect"
	actions_model "gitea.dev/models/actions"
	"gitea.dev/models/db"
	repo_model "gitea.dev/models/repo"
	"gitea.dev/models/unittest"
	user_model "gitea.dev/models/user"
	"gitea.dev/modules/setting"
	"gitea.dev/modules/timeutil"
	runner_api "gitea.dev/routers/api/actions/runner"
	actions_service "gitea.dev/services/actions"
	notify_service "gitea.dev/services/notify"

	"connectrpc.com/connect"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/types/known/timestamppb"
)

const headSHA = "c7cd3cd144e6d23c9d6f3d07e52b2c1a956e0338"

type countNotifier struct {
	notify_service.NullNotifier
	mu sync.Mutex
	ev []string
}

func (n *countNotifier) WorkflowJobStatusUpdate(_ context.Context, _ *repo_model.Repository, _ *user_model.User, job *actions_model.ActionRunJob, _ *actions_model.ActionTask) {
	n.mu.Lock()
	n.ev = append(n.ev, fmt.Sprintf("job(%s#%d=%s)", job.Name, job.Attempt, job.Status))
	n.mu.Unlock()
}

func (n *countNotifier) WorkflowRunStatusUpdate(_ context.Context, _ *repo_model.Repository, _ *user_model.User, run *actions_model.ActionRun) {
	n.mu.Lock()
	n.ev = append(n.ev, fmt.Sprintf("run(%s)", run.Status))
	n.mu.Unlock()
}

func (n *countNotifier) take() string {
	n.mu.Lock()
	defer n.mu.Unlock()
	s := strings.Join(n.ev, " ")
	n.ev = nil
	if s == "" {
		return "none"
	}
	return s
}

var notifier = &countNotifier{}
var registerOnce sync.Once

type env struct {
	t    *testing.T
	ctx  context.Context
	srv  *httptest.Server
	repo *repo_model.Repository
	user *user_model.User
	idx  int64
}

type fakeRunner struct {
	e      *env
	name   string
	client runnerv1connect.RunnerServiceClient
	id     int64
}

func newEnv(t *testing.T) *env {
	require.NoError(t, unittest.PrepareTestDatabase())
	require.True(t, actions_service.ProbeInitQueue())
	registerOnce.Do(func() { notify_service.RegisterNotifier(notifier) })
	path, h := runner_api.NewRunnerServiceHandler()
	mux := http.NewServeMux()
	mux.Handle(path, h)
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	e := &env{t: t, ctx: t.Context(), srv: srv, idx: time.Now().UnixNano() % 100000}
	e.repo = unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	e.user = unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	return e
}

func (e *env) runner(name string, caps ...string) *fakeRunner {
	tok, err := actions_model.NewRunnerToken(e.ctx, 0, 0)
	require.NoError(e.t, err)
	plain := runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL)
	resp, err := plain.Register(e.ctx, connect.NewRequest(&runnerv1.RegisterRequest{Name: name, Token: tok.Token, Labels: []string{"probe"}, Version: "probe", Capabilities: caps}))
	require.NoError(e.t, err)
	uuid, token := resp.Msg.Runner.Uuid, resp.Msg.Runner.Token
	ic := connect.UnaryInterceptorFunc(func(next connect.UnaryFunc) connect.UnaryFunc {
		return func(ctx context.Context, req connect.AnyRequest) (connect.AnyResponse, error) {
			req.Header().Set("x-runner-uuid", uuid)
			req.Header().Set("x-runner-token", token)
			return next(ctx, req)
		}
	})
	return &fakeRunner{e: e, name: name, id: resp.Msg.Runner.Id, client: runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL, connect.WithInterceptors(ic))}
}

func (r *fakeRunner) fetch() *runnerv1.Task {
	resp, err := r.client.FetchTask(r.e.ctx, connect.NewRequest(&runnerv1.FetchTaskRequest{TasksVersion: 0}))
	if err != nil {
		r.e.t.Logf("     [%s] FetchTask error: %v", r.name, err)
		return nil
	}
	return resp.Msg.Task
}

func (r *fakeRunner) update(taskID int64, result runnerv1.Result, outputs map[string]string) string {
	now := timestamppb.Now()
	st := &runnerv1.TaskState{Id: taskID, Result: result, StartedAt: now, Steps: []*runnerv1.StepState{{Id: 0, StartedAt: now}}}
	if result != runnerv1.Result_RESULT_UNSPECIFIED {
		st.StoppedAt = now
		st.Steps[0].Result = result
		st.Steps[0].StoppedAt = now
	}
	resp, err := r.client.UpdateTask(r.e.ctx, connect.NewRequest(&runnerv1.UpdateTaskRequest{State: st, Outputs: outputs}))
	if err != nil {
		return "RPC ERROR: " + err.Error()
	}
	return "server says " + strings.TrimPrefix(resp.Msg.State.Result.String(), "RESULT_")
}

func (r *fakeRunner) logs(taskID, index int64, n int, noMore bool) string {
	rows := make([]*runnerv1.LogRow, n)
	for i := range rows {
		rows[i] = &runnerv1.LogRow{Time: timestamppb.Now(), Content: fmt.Sprintf("line %d", index+int64(i))}
	}
	resp, err := r.client.UpdateLog(r.e.ctx, connect.NewRequest(&runnerv1.UpdateLogRequest{TaskId: taskID, Index: index, Rows: rows, NoMore: noMore}))
	if err != nil {
		return "RPC ERROR: " + err.Error()
	}
	return fmt.Sprintf("ack=%d", resp.Msg.AckIndex)
}

type probeRun struct {
	ID int64
	wf string
}

func (e *env) newRun(yaml string, mod func(*actions_model.ActionRun)) *probeRun {
	e.idx++
	wfName := fmt.Sprintf("probe%d.yml", e.idx)
	run := &actions_model.ActionRun{Title: "probe", RepoID: e.repo.ID, OwnerID: e.repo.OwnerID, WorkflowID: wfName, TriggerUserID: e.user.ID, Ref: "refs/heads/master", CommitSHA: headSHA, Event: "push", TriggerEvent: "push", EventPayload: `{"head_commit":{"id":"` + headSHA + `"}}`, WorkflowRepoID: e.repo.ID, WorkflowCommitSHA: headSHA}
	if mod != nil {
		mod(run)
	}
	if err := actions_service.PrepareRunAndInsert(e.ctx, []byte(yaml), run, nil); err != nil {
		e.t.Logf("     PrepareRunAndInsert error: %v", err)
		return nil
	}
	e.flush()
	notifier.take()
	return &probeRun{ID: run.ID, wf: wfName}
}

func (e *env) flush() {
	if err := actions_service.ProbeFlush(e.ctx); err != nil {
		e.t.Logf("     (emitter flush: %v)", err)
	}
}

var timeCols = map[string]bool{"updated": true, "started": true, "stopped": true, "created": true, "updated_unix": true, "created_unix": true}
var skipCols = map[string]bool{"workflow_payload": true, "log_indexes": true, "event_payload": true, "reusable_workflow_content": true, "token_hash": true, "token_salt": true}

func (e *env) snap(r *probeRun) map[string]string {
	out := map[string]string{}
	jobsIn := "(SELECT id FROM action_run_job WHERE run_id=" + strconv.FormatInt(r.ID, 10) + ")"
	tasksIn := "(SELECT id FROM action_task WHERE job_id IN " + jobsIn + ")"
	qs := []struct{ name, sql string }{
		{"run", "SELECT * FROM action_run WHERE id=" + strconv.FormatInt(r.ID, 10)},
		{"attempt", "SELECT * FROM action_run_attempt WHERE run_id=" + strconv.FormatInt(r.ID, 10)},
		{"job", "SELECT * FROM action_run_job WHERE run_id=" + strconv.FormatInt(r.ID, 10)},
		{"task", "SELECT * FROM action_task WHERE id IN " + tasksIn},
		{"step", "SELECT * FROM action_task_step WHERE task_id IN " + tasksIn},
		{"output", "SELECT * FROM action_task_output WHERE task_id IN " + tasksIn},
		{"commit_status", "SELECT id, state, target_url, context FROM commit_status WHERE repo_id=4 AND context LIKE '" + r.wf + "%'"},
	}
	now := time.Now().Unix()
	for _, q := range qs {
		rows, err := db.GetEngine(e.ctx).QueryString(q.sql)
		require.NoError(e.t, err)
		for _, row := range rows {
			label := q.name + "#" + row["id"]
			if n, ok := row["name"]; ok && q.name == "job" {
				label = "job[" + n + " id" + row["id"] + "]"
			}
			if q.name == "commit_status" {
				tu := row["target_url"]
				out[label+".NEW"] = fmt.Sprintf("%s -> %s (%s)", strings.TrimPrefix(row["context"], r.wf+" / "), row["state"], tu[strings.LastIndex(tu, "/jobs/")+1:])
				continue
			}
			if q.name == "output" {
				out[label+".NEW"] = row["output_key"] + "=" + row["output_value"] + " (task " + row["task_id"] + ")"
				continue
			}
			for c, v := range row {
				if skipCols[c] {
					continue
				}
				if timeCols[c] {
					if ts, _ := strconv.ParseInt(v, 10, 64); ts > 0 {
						d := now - ts
						switch {
						case d <= 2:
							v = "now"
						default:
							v = (time.Duration(d) * time.Second).String() + " ago"
						}
					}
				}
				if c == "status" {
					if n, err := strconv.Atoi(v); err == nil {
						v = actions_model.Status(n).String()
					}
				}
				out[label+"."+c] = v
			}
		}
	}
	return out
}

// act runs fn and reports every row/column it changed, the notifications it fired, and commit statuses it wrote
func (e *env) act(label string, r *probeRun, fn func() string) {
	before := e.snap(r)
	notifier.take()
	msg := fn()
	e.flush()
	after := e.snap(r)
	var changes []string
	keys := make([]string, 0, len(after))
	for k := range after {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		b, had := before[k]
		a := after[k]
		if strings.HasSuffix(k, ".NEW") {
			if !had {
				changes = append(changes, strings.TrimSuffix(k, ".NEW")+" NEW "+a)
			}
			continue
		}
		if had && a != b {
			changes = append(changes, fmt.Sprintf("%s: %s→%s", k, b, a))
		} else if !had && (strings.HasSuffix(k, ".status") || strings.HasSuffix(k, ".id")) && !strings.HasPrefix(k, "run") {
			if strings.HasSuffix(k, ".status") {
				changes = append(changes, fmt.Sprintf("%s: (new row) %s", k, a))
			}
		}
	}
	if msg != "" {
		msg = " [" + msg + "]"
	}
	e.t.Logf("   > %s%s", label, msg)
	if len(changes) == 0 {
		e.t.Logf("       writes: none")
	} else {
		for _, c := range changes {
			e.t.Logf("       write: %s", c)
		}
	}
	e.t.Logf("       notifications: %s", notifier.take())
}

func (e *env) state(label string, r *probeRun) {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(e.ctx, run.ID, run.LatestAttemptID)
	var parts []string
	for _, j := range jobs {
		s := fmt.Sprintf("%s=%s", j.Name, j.Status)
		if j.TaskID > 0 {
			task, _ := actions_model.GetTaskByID(e.ctx, j.TaskID)
			s += fmt.Sprintf("[task %d:%s]", task.ID, task.Status)
		}
		parts = append(parts, s)
	}
	att := ""
	if a, has, _ := run.GetLatestAttempt(e.ctx); has {
		att = fmt.Sprintf(" attempt#%d=%s", a.Attempt, a.Status)
	}
	// latest commit status per context
	rows, _ := db.GetEngine(e.ctx).QueryString("SELECT context, state, target_url FROM commit_status WHERE repo_id=4 AND context LIKE '" + r.wf + "%' ORDER BY id")
	latest := map[string]string{}
	for _, row := range rows {
		tu := row["target_url"]
		latest[strings.TrimPrefix(row["context"], r.wf+" / ")] = row["state"] + "(" + tu[strings.LastIndex(tu, "/jobs/")+1:] + ")"
	}
	var cs []string
	for k, v := range latest {
		cs = append(cs, k+"="+v)
	}
	sort.Strings(cs)
	e.t.Logf("   = %s: run=%s%s | %s | commit status: %s", label, run.Status, att, strings.Join(parts, " "), strings.Join(cs, " "))
}

func (e *env) latestJobs(r *probeRun) []*actions_model.ActionRunJob {
	jobs, err := actions_model.GetLatestAttemptJobsByRepoAndRunID(e.ctx, e.repo.ID, r.ID)
	require.NoError(e.t, err)
	return jobs
}

// cancel mirrors routers/web/repo/actions/view.go Cancel()
func (e *env) cancel(r *probeRun) string {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	require.NoError(e.t, run.LoadAttributes(e.ctx))
	jobs := e.latestJobs(r)
	var updated []*actions_model.ActionRunJob
	err := db.WithTx(e.ctx, func(ctx context.Context) error {
		c, err := actions_model.CancelJobs(ctx, jobs)
		updated = append(updated, c...)
		return err
	})
	if err != nil {
		return "cancel error: " + err.Error()
	}
	actions_service.CreateCommitStatusForRunJobs(e.ctx, run, jobs...)
	actions_service.EmitJobsIfReadyByJobs(updated)
	actions_service.NotifyWorkflowJobsStatusUpdate(e.ctx, updated...)
	if len(updated) > 0 {
		actions_service.NotifyWorkflowRunStatusUpdateWithReload(e.ctx, run.RepoID, run.ID)
	}
	return fmt.Sprintf("handler saw %d updated jobs", len(updated))
}

func (e *env) rerunJobs(r *probeRun, failedOnly bool, sel []*actions_model.ActionRunJob) string {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	if failedOnly {
		sel = actions_service.GetFailedJobsForRerun(e.latestJobs(r))
	}
	if _, err := actions_service.RerunWorkflowRunJobs(e.ctx, e.repo, run, e.user, sel); err != nil {
		return "refused: " + err.Error()
	}
	return "accepted"
}

func (e *env) exec(sql string, args ...any) {
	_, err := db.GetEngine(e.ctx).Exec(append([]any{sql}, args...)...)
	require.NoError(e.t, err)
}

func ago(d time.Duration) timeutil.TimeStamp { return timeutil.TimeStamp(time.Now().Add(-d).Unix()) }

// age backdates the last-updated time of every row of the run
func (e *env) age(r *probeRun, d time.Duration) {
	e.exec("UPDATE action_run SET updated=? WHERE id=?", ago(d), r.ID)
	e.exec("UPDATE action_run_attempt SET updated=? WHERE run_id=?", ago(d), r.ID)
	e.exec("UPDATE action_run_job SET updated=? WHERE run_id=?", ago(d), r.ID)
	e.exec("UPDATE action_task SET updated=? WHERE job_id IN (SELECT id FROM action_run_job WHERE run_id=?)", ago(d), r.ID)
}

func (e *env) ageStarted(r *probeRun, d time.Duration) {
	e.exec("UPDATE action_task SET started=? WHERE job_id IN (SELECT id FROM action_run_job WHERE run_id=?)", ago(d), r.ID)
}

func job(id, extra string) string {
	return "  " + id + ":\n    runs-on: probe\n" + extra + "    steps:\n      - run: echo\n"
}
func wf(jobs ...string) string { return "on: push\njobs:\n" + strings.Join(jobs, "") }

const (
	OK   = runnerv1.Result_RESULT_SUCCESS
	FAIL = runnerv1.Result_RESULT_FAILURE
	NONE = runnerv1.Result_RESULT_UNSPECIFIED
)

func cron(f func(context.Context) error, ctx context.Context) func() string {
	return func() string {
		if err := f(ctx); err != nil {
			return "cron error: " + err.Error()
		}
		return ""
	}
}

