	sort.Strings(keys)
	for _, k := range keys {
		b, had := before[k]
		a := after[k]
		if strings.HasSuffix(k, ".NEW") {
			if !had {
				changes = append(changes, strings.TrimSuffix(k, ".NEW")+" NEW "+a)
			}
			continue
		}
		if had && a != b {
			changes = append(changes, fmt.Sprintf("%s: %s→%s", k, b, a))
		} else if !had && (strings.HasSuffix(k, ".status") || strings.HasSuffix(k, ".id")) && !strings.HasPrefix(k, "run") {
			if strings.HasSuffix(k, ".status") {
				changes = append(changes, fmt.Sprintf("%s: (new row) %s", k, a))
			}
		}
	}
	if msg != "" {
		msg = " [" + msg + "]"
	}
	e.t.Logf("   > %s%s", label, msg)
	if len(changes) == 0 {
		e.t.Logf("       writes: none")
	} else {
		for _, c := range changes {
			e.t.Logf("       write: %s", c)
		}
	}
	e.t.Logf("       notifications: %s", notifier.take())
}

func (e *env) state(label string, r *probeRun) {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(e.ctx, run.ID, run.LatestAttemptID)
	var parts []string
	for _, j := range jobs {
		s := fmt.Sprintf("%s=%s", j.Name, j.Status)
		if j.TaskID > 0 {
			task, _ := actions_model.GetTaskByID(e.ctx, j.TaskID)
			s += fmt.Sprintf("[task %d:%s]", task.ID, task.Status)
		}
		parts = append(parts, s)
	}
	att := ""
	if a, has, _ := run.GetLatestAttempt(e.ctx); has {
		att = fmt.Sprintf(" attempt#%d=%s", a.Attempt, a.Status)
	}
	// latest commit status per context
	rows, _ := db.GetEngine(e.ctx).QueryString("SELECT context, state, target_url FROM commit_status WHERE repo_id=4 AND context LIKE '" + r.wf + "%' ORDER BY id")
	latest := map[string]string{}
	for _, row := range rows {
		tu := row["target_url"]
		latest[strings.TrimPrefix(row["context"], r.wf+" / ")] = row["state"] + "(" + tu[strings.LastIndex(tu, "/jobs/")+1:] + ")"
	}
	var cs []string
	for k, v := range latest {
		cs = append(cs, k+"="+v)
	}
	sort.Strings(cs)
	e.t.Logf("   = %s: run=%s%s | %s | commit status: %s", label, run.Status, att, strings.Join(parts, " "), strings.Join(cs, " "))
}

func (e *env) latestJobs(r *probeRun) []*actions_model.ActionRunJob {
	jobs, err := actions_model.GetLatestAttemptJobsByRepoAndRunID(e.ctx, e.repo.ID, r.ID)
	require.NoError(e.t, err)
	return jobs
}

// cancel mirrors routers/web/repo/actions/view.go Cancel()
func (e *env) cancel(r *probeRun) string {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	require.NoError(e.t, run.LoadAttributes(e.ctx))
	jobs := e.latestJobs(r)
	var updated []*actions_model.ActionRunJob
	err := db.WithTx(e.ctx, func(ctx context.Context) error {
		c, err := actions_model.CancelJobs(ctx, jobs)
		updated = append(updated, c...)
		return err
	})
	if err != nil {
		return "cancel error: " + err.Error()
	}
	actions_service.CreateCommitStatusForRunJobs(e.ctx, run, jobs...)
	actions_service.EmitJobsIfReadyByJobs(updated)
	actions_service.NotifyWorkflowJobsStatusUpdate(e.ctx, updated...)
	if len(updated) > 0 {
		actions_service.NotifyWorkflowRunStatusUpdateWithReload(e.ctx, run.RepoID, run.ID)
	}
	return fmt.Sprintf("handler saw %d updated jobs", len(updated))
}

func (e *env) rerunJobs(r *probeRun, failedOnly bool, sel []*actions_model.ActionRunJob) string {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	if failedOnly {
		sel = actions_service.GetFailedJobsForRerun(e.latestJobs(r))
	}
	if _, err := actions_service.RerunWorkflowRunJobs(e.ctx, e.repo, run, e.user, sel); err != nil {
		return "refused: " + err.Error()
	}
	return "accepted"
}

func (e *env) exec(sql string, args ...any) {
	_, err := db.GetEngine(e.ctx).Exec(append([]any{sql}, args...)...)
	require.NoError(e.t, err)
}

func ago(d time.Duration) timeutil.TimeStamp { return timeutil.TimeStamp(time.Now().Add(-d).Unix()) }

// age backdates the last-updated time of every row of the run
func (e *env) age(r *probeRun, d time.Duration) {
	e.exec("UPDATE action_run SET updated=? WHERE id=?", ago(d), r.ID)
	e.exec("UPDATE action_run_attempt SET updated=? WHERE run_id=?", ago(d), r.ID)
	e.exec("UPDATE action_run_job SET updated=? WHERE run_id=?", ago(d), r.ID)
	e.exec("UPDATE action_task SET updated=? WHERE job_id IN (SELECT id FROM action_run_job WHERE run_id=?)", ago(d), r.ID)
}

func (e *env) ageStarted(r *probeRun, d time.Duration) {
	e.exec("UPDATE action_task SET started=? WHERE job_id IN (SELECT id FROM action_run_job WHERE run_id=?)", ago(d), r.ID)
}

func job(id, extra string) string {
	return "  " + id + ":\n    runs-on: probe\n" + extra + "    steps:\n      - run: echo\n"
}
func wf(jobs ...string) string { return "on: push\njobs:\n" + strings.Join(jobs, "") }

const (
	OK   = runnerv1.Result_RESULT_SUCCESS
	FAIL = runnerv1.Result_RESULT_FAILURE
	NONE = runnerv1.Result_RESULT_UNSPECIFIED
)

func cron(f func(context.Context) error, ctx context.Context) func() string {
	return func() string {
		if err := f(ctx); err != nil {
			return "cron error: " + err.Error()
		}
		return ""
	}
}

