	e.age(run4, 5*time.Minute)
	e.act("runner repeats final (now SUCCESS)", run4, func() string { return r4.update(task4.Id, OK, nil) })
	e.age(run4, 26*time.Hour)
	e.ageStarted(run4, 26*time.Hour)
	e.act("zombie+endless+abandoned crons a day later", run4, func() string {
