var timeCols = map[string]bool{"updated": true, "started": true, "stopped": true, "created": true, "updated_unix": true, "created_unix": true}
var skipCols = map[string]bool{"workflow_payload": true, "log_indexes": true, "event_payload": true, "reusable_workflow_content": true, "token_hash": true, "token_salt": true}

func (e *env) snap(r *probeRun) map[string]string {
	out := map[string]string{}
	jobsIn := "(SELECT id FROM action_run_job WHERE run_id=" + strconv.FormatInt(r.ID, 10) + ")"
	tasksIn := "(SELECT id FROM action_task WHERE job_id IN " + jobsIn + ")"
	qs := []struct{ name, sql string }{
		{"run", "SELECT * FROM action_run WHERE id=" + strconv.FormatInt(r.ID, 10)},
		{"attempt", "SELECT * FROM action_run_attempt WHERE run_id=" + strconv.FormatInt(r.ID, 10)},
		{"job", "SELECT * FROM action_run_job WHERE run_id=" + strconv.FormatInt(r.ID, 10)},
		{"task", "SELECT * FROM action_task WHERE id IN " + tasksIn},
		{"step", "SELECT * FROM action_task_step WHERE task_id IN " + tasksIn},
		{"output", "SELECT * FROM action_task_output WHERE task_id IN " + tasksIn},
		{"commit_status", "SELECT id, state, target_url, context FROM commit_status WHERE repo_id=4 AND context LIKE '" + r.wf + "%'"},
	}
	now := time.Now().Unix()
	for _, q := range qs {
		rows, err := db.GetEngine(e.ctx).QueryString(q.sql)
		require.NoError(e.t, err)
		for _, row := range rows {
			label := q.name + "#" + row["id"]
			if n, ok := row["name"]; ok && q.name == "job" {
				label = "job[" + n + " id" + row["id"] + "]"
			}
			if q.name == "commit_status" {
				tu := row["target_url"]
				out[label+".NEW"] = fmt.Sprintf("%s -> %s (%s)", strings.TrimPrefix(row["context"], r.wf+" / "), row["state"], tu[strings.LastIndex(tu, "/jobs/")+1:])
				continue
			}
			if q.name == "output" {
				out[label+".NEW"] = row["output_key"] + "=" + row["output_value"] + " (task " + row["task_id"] + ")"
				continue
			}
			for c, v := range row {
				if skipCols[c] {
					continue
				}
				if timeCols[c] {
					if ts, _ := strconv.ParseInt(v, 10, 64); ts > 0 {
						d := now - ts
						switch {
						case d <= 2:
							v = "now"
						default:
							v = (time.Duration(d) * time.Second).String() + " ago"
						}
					}
				}
				if c == "status" {
					if n, err := strconv.Atoi(v); err == nil {
						v = actions_model.Status(n).String()
					}
				}
				out[label+"."+c] = v
			}
		}
	}
	return out
}

// act runs fn and reports every row/column it changed, the notifications it fired, and commit statuses it wrote
func (e *env) act(label string, r *probeRun, fn func() string) {
	before := e.snap(r)
	notifier.take()
	msg := fn()
	e.flush()
	after := e.snap(r)
	var changes []string
	keys := make([]string, 0, len(after))
	for k := range after {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		b, had := before[k]
		a := after[k]
		if strings.HasSuffix(k, ".NEW") {
			if !had {
				changes = append(changes, strings.TrimSuffix(k, ".NEW")+" NEW "+a)
			}
			continue
		}
		if had && a != b {
			changes = append(changes, fmt.Sprintf("%s: %s→%s", k, b, a))
		} else if !had && (strings.HasSuffix(k, ".status") || strings.HasSuffix(k, ".id")) && !strings.HasPrefix(k, "run") {
			if strings.HasSuffix(k, ".status") {
				changes = append(changes, fmt.Sprintf("%s: (new row) %s", k, a))
			}
		}
	}
	if msg != "" {
		msg = " [" + msg + "]"
	}
	e.t.Logf("   > %s%s", label, msg)
	if len(changes) == 0 {
		e.t.Logf("       writes: none")
	} else {
		for _, c := range changes {
			e.t.Logf("       write: %s", c)
		}
	}
	e.t.Logf("       notifications: %s", notifier.take())
}

func (e *env) state(label string, r *probeRun) {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(e.ctx, run.ID, run.LatestAttemptID)
	var parts []string
	for _, j := range jobs {
		s := fmt.Sprintf("%s=%s", j.Name, j.Status)
		if j.TaskID > 0 {
			task, _ := actions_model.GetTaskByID(e.ctx, j.TaskID)
			s += fmt.Sprintf("[task %d:%s]", task.ID, task.Status)
		}
		parts = append(parts, s)
	}
	att := ""
	if a, has, _ := run.GetLatestAttempt(e.ctx); has {
		att = fmt.Sprintf(" attempt#%d=%s", a.Attempt, a.Status)
	}
	// latest commit status per context
	rows, _ := db.GetEngine(e.ctx).QueryString("SELECT context, state, target_url FROM commit_status WHERE repo_id=4 AND context LIKE '" + r.wf + "%' ORDER BY id")
	latest := map[string]string{}
	for _, row := range rows {
		tu := row["target_url"]
		latest[strings.TrimPrefix(row["context"], r.wf+" / ")] = row["state"] + "(" + tu[strings.LastIndex(tu, "/jobs/")+1:] + ")"
	}
	var cs []string
	for k, v := range latest {
		cs = append(cs, k+"="+v)
	}
	sort.Strings(cs)
	e.t.Logf("   = %s: run=%s%s | %s | commit status: %s", label, run.Status, att, strings.Join(parts, " "), strings.Join(cs, " "))
}

func (e *env) latestJobs(r *probeRun) []*actions_model.ActionRunJob {
	jobs, err := actions_model.GetLatestAttemptJobsByRepoAndRunID(e.ctx, e.repo.ID, r.ID)
	require.NoError(e.t, err)
	return jobs
}

// cancel mirrors routers/web/repo/actions/view.go Cancel()
func (e *env) cancel(r *probeRun) string {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	require.NoError(e.t, run.LoadAttributes(e.ctx))
	jobs := e.latestJobs(r)
	var updated []*actions_model.ActionRunJob
	err := db.WithTx(e.ctx, func(ctx context.Context) error {
		c, err := actions_model.CancelJobs(ctx, jobs)
		updated = append(updated, c...)
		return err
	})
	if err != nil {
		return "cancel error: " + err.Error()
	}
	actions_service.CreateCommitStatusForRunJobs(e.ctx, run, jobs...)
	actions_service.EmitJobsIfReadyByJobs(updated)
	actions_service.NotifyWorkflowJobsStatusUpdate(e.ctx, updated...)
	if len(updated) > 0 {
		actions_service.NotifyWorkflowRunStatusUpdateWithReload(e.ctx, run.RepoID, run.ID)
	}
	return fmt.Sprintf("handler saw %d updated jobs", len(updated))
}

func (e *env) rerunJobs(r *probeRun, failedOnly bool, sel []*actions_model.ActionRunJob) string {
	run := unittest.AssertExistsAndLoadBean(e.t, &actions_model.ActionRun{ID: r.ID})
	if failedOnly {
		sel = actions_service.GetFailedJobsForRerun(e.latestJobs(r))
	}
	if _, err := actions_service.RerunWorkflowRunJobs(e.ctx, e.repo, run, e.user, sel); err != nil {
		return "refused: " + err.Error()
	}
	return "accepted"
}

func (e *env) exec(sql string, args ...any) {
	_, err := db.GetEngine(e.ctx).Exec(append([]any{sql}, args...)...)
	require.NoError(e.t, err)
}

func ago(d time.Duration) timeutil.TimeStamp { return timeutil.TimeStamp(time.Now().Add(-d).Unix()) }

// age backdates the last-updated time of every row of the run
func (e *env) age(r *probeRun, d time.Duration) {
	e.exec("UPDATE action_run SET updated=? WHERE id=?", ago(d), r.ID)
	e.exec("UPDATE action_run_attempt SET updated=? WHERE run_id=?", ago(d), r.ID)
	e.exec("UPDATE action_run_job SET updated=? WHERE run_id=?", ago(d), r.ID)
	e.exec("UPDATE action_task SET updated=? WHERE job_id IN (SELECT id FROM action_run_job WHERE run_id=?)", ago(d), r.ID)
}

func (e *env) ageStarted(r *probeRun, d time.Duration) {
	e.exec("UPDATE action_task SET started=? WHERE job_id IN (SELECT id FROM action_run_job WHERE run_id=?)", ago(d), r.ID)
}

func job(id, extra string) string {
	return "  " + id + ":\n    runs-on: probe\n" + extra + "    steps:\n      - run: echo\n"
}
func wf(jobs ...string) string { return "on: push\njobs:\n" + strings.Join(jobs, "") }

const (
	OK   = runnerv1.Result_RESULT_SUCCESS
	FAIL = runnerv1.Result_RESULT_FAILURE
	NONE = runnerv1.Result_RESULT_UNSPECIFIED
)

func cron(f func(context.Context) error, ctx context.Context) func() string {
	return func() string {
		if err := f(ctx); err != nil {
			return "cron error: " + err.Error()
		}
		return ""
	}
}

var pipeline = wf(job("build", ""), job("deploy", "    needs: build\n"), job("cleanup", "    needs: build\n    if: always()\n"))

func TestProbe_A_StuckCancelling(t *testing.T) {
	e := newEnv(t)
	t.Log("== A1 stuck 'cancelling' (runner supports cancelling, then vanishes): what does a second cancel write, and what do the crons do after")
	r := e.runner("a1", "cancelling")
	run := e.newRun(wf(job("build", "")), nil)
	task := r.fetch()
	r.update(task.Id, NONE, nil)
	e.age(run, 5*time.Minute)
	e.act("first cancel", run, func() string { return e.cancel(run) })
	e.age(run, 11*time.Minute) // runner silent for 11 minutes: the zombie cron would now collect it
	e.act("second cancel, 11 min after the runner went silent", run, func() string { return e.cancel(run) })
	e.act("zombie cron immediately after", run, cron(actions_service.StopZombieTasks, e.ctx))
	e.state("state", run)
	for i := 0; i < 3; i++ {
		e.age(run, 9*time.Minute)
		e.cancel(run)
		e.flush()
		e.age(run, 9*time.Minute)
		_ = actions_service.StopZombieTasks(e.ctx)
	}
	e.flush()
	notifier.take()
	e.state("after 3 more rounds of (9 min, cancel, 9 min, zombie cron)", run)
	e.age(run, 11*time.Minute)
	e.act("zombie cron once nobody has clicked cancel for 11 min", run, cron(actions_service.StopZombieTasks, e.ctx))
	e.state("state", run)

	t.Log("== A2 same, but an admin deletes the vanished runner, then the user cancels again")
	r2 := e.runner("a2", "cancelling")
	run2 := e.newRun(wf(job("build", "")), nil)
	task2 := r2.fetch()
	r2.update(task2.Id, NONE, nil)
	e.cancel(run2)
	e.flush()
	require.NoError(t, actions_model.DeleteRunner(e.ctx, r2.id))
	e.age(run2, 5*time.Minute)
	e.act("cancel again after runner deletion", run2, func() string { return e.cancel(run2) })
	e.state("state", run2)

	t.Log("== A3 stuck 'cancelling' kept alive by clicks: does the endless cron end it")
	r3 := e.runner("a3", "cancelling")
	run3 := e.newRun(wf(job("build", "")), nil)
	task3 := r3.fetch()
	r3.update(task3.Id, NONE, nil)
	e.cancel(run3)
	e.flush()
	e.ageStarted(run3, 4*time.Hour)
	e.act("endless cron, task started 4h ago", run3, cron(actions_service.StopEndlessTasks, e.ctx))
	e.act("endless cron again", run3, cron(actions_service.StopEndlessTasks, e.ctx))
	e.act("zombie cron after", run3, cron(actions_service.StopZombieTasks, e.ctx))
	e.act("cancel after", run3, func() string { return e.cancel(run3) })
	e.act("runner returns: final SUCCESS", run3, func() string { return r3.update(task3.Id, OK, nil) })
	e.state("state", run3)

	t.Log("== A4 'cancelling' with a live runner: runner reports final twice, then crons, then cancel")
	r4 := e.runner("a4", "cancelling")
	run4 := e.newRun(pipeline, nil)
	task4 := r4.fetch()
	r4.update(task4.Id, NONE, nil)
	e.cancel(run4)
	e.flush()
	e.age(run4, 5*time.Minute)
	e.act("runner final FAILURE", run4, func() string { return r4.update(task4.Id, FAIL, nil) })
	e.age(run4, 5*time.Minute)
	e.act("runner repeats final (now SUCCESS)", run4, func() string { return r4.update(task4.Id, OK, nil) })
	e.age(run4, 26*time.Hour)
	e.ageStarted(run4, 26*time.Hour)
	e.act("zombie+endless+abandoned crons a day later", run4, func() string {
		_ = actions_service.StopZombieTasks(e.ctx)
		_ = actions_service.StopEndlessTasks(e.ctx)
		_ = actions_service.CancelAbandonedJobs(e.ctx)
		return ""
	})
	e.act("cancel on the finished run", run4, func() string { return e.cancel(run4) })
	e.state("state", run4)
}
