213	// MatchCallerInputsAgainstSpec checks the caller's already-evaluated `with:` values against the callee's declared `on.workflow_call.inputs` schema
214	func MatchCallerInputsAgainstSpec(spec *WorkflowCallSpec, evaluated map[string]any) (map[string]any, error) {
215		resolved := make(map[string]any, len(spec.Inputs))
216	
217		// fill defaults first
218		for name, in := range spec.Inputs {
219			if in.Default.IsZero() {
220				continue
221			}
222			var defaultVal any
223			if err := in.Default.Decode(&defaultVal); err != nil {
224				return nil, fmt.Errorf("decode workflow_call input %q default: %w", name, err)
225			}
226			v, err := parseWorkflowCallInput(name, in.Type, defaultVal)
227			if err != nil {
228				return nil, err
229			}
230			resolved[name] = v
231		}
232	
233		for k, raw := range evaluated {
234			inputSpec, ok := spec.Inputs[k]
235			if !ok {
236				// ignore unknown "with:" keys
237				continue
238			}
239			converted, err := parseWorkflowCallInput(k, inputSpec.Type, raw)
240			if err != nil {
241				return nil, err
242			}
243			resolved[k] = converted
244		}
245	
246		for name, in := range spec.Inputs {
247			if !in.Required {
248				continue
249			}
250			// resolved[name] is set when caller provided it OR when spec has a non-zero default - both satisfy "required".
251			if _, ok := resolved[name]; ok {
252				continue
253			}
254			return nil, fmt.Errorf("workflow_call input %q is required", name)
255		}
256	
257		return resolved, nil
258	}
259	
260	func parseWorkflowCallInput(name string, typ InputType, v any) (any, error) {
261		switch typ {
262		case InputTypeString:
263			return toString(v), nil
264		case InputTypeBoolean:
265			// strict type matching: a boolean input only accepts a native bool, not a "true"/"false" string
266			if b, ok := v.(bool); ok {
267				return b, nil
268			}
269			return false, fmt.Errorf("workflow_call input %q expects boolean", name)
270		case InputTypeNumber:
271			// strict type matching: a number input rejects "123"/"3.14" strings.
272			if _, isString := v.(string); isString {
273				return 0.0, fmt.Errorf("workflow_call input %q expects number", name)
274			}
275			return util.ToFloat64(v)
276		default:
277			return nil, fmt.Errorf("workflow_call input %q has unsupported type %q", name, typ)
278		}
279	}
280	
281	// SecretsInherit is the literal keyword used in a caller's `secrets: inherit` directive
282	const SecretsInherit = "inherit"
283	
284	// callerSecretValueRegexp matches the `${{ secrets.NAME }}` form expected for each value in a caller's `secrets:` mapping.
285	var callerSecretValueRegexp = regexp.MustCompile(`^\s*\$\{\{\s*secrets\.([A-Za-z_][A-Za-z0-9_]*)\s*\}\}\s*$`)
286	
287	// ParseCallerSecrets decodes a caller's "secrets:" YAML node into one of two forms:
288	//   - inherit == true: the caller wrote `secrets: inherit`; mapping is nil
289	//   - inherit == false, mapping == {alias: source_name}: explicit mapping. Each value must be of the form `${{ secrets.NAME }}`.
290	//
291	// Both alias and source name are upper-cased: secret names are case-insensitive (matching GitHub),
292	// and Gitea stores secrets upper-cased, so this keeps lookups and schema validation consistent.
293	func ParseCallerSecrets(node yaml.Node) (inherit bool, mapping map[string]string, err error) {
294		if node.IsZero() {
295			return false, nil, nil
296		}
297		if node.Kind == yaml.ScalarNode && strings.TrimSpace(node.Value) == SecretsInherit {
298			return true, nil, nil
299		}
300		if node.Kind != yaml.MappingNode {
301			return false, nil, errors.New("invalid secrets: section, expected mapping or 'inherit'")
302		}
303		out := make(map[string]string, len(node.Content)/2)
304		for i := 0; i+1 < len(node.Content); i += 2 {
305			k := node.Content[i]
306			v := node.Content[i+1]
307			var sv string
308			if err := v.Decode(&sv); err != nil {
309				return false, nil, fmt.Errorf("decode secret %q: %w", k.Value, err)
310			}
311			matches := callerSecretValueRegexp.FindStringSubmatch(sv)
312			if len(matches) != 2 {
313				return false, nil, fmt.Errorf("caller secret %q value must be of the form ${{ secrets.NAME }}", k.Value)
314			}
315			out[strings.ToUpper(k.Value)] = strings.ToUpper(matches[1])
316		}
317		return false, out, nil
318	}
319	
320	// ValidateCallerSecrets checks a caller's parsed explicit-mapping `secrets:` against the called workflow's declared `on.workflow_call.secrets` schema.
321	func ValidateCallerSecrets(spec *WorkflowCallSpec, mapping map[string]string) error {
322		if spec == nil {
323			return errors.New("ValidateCallerSecrets: nil workflow_call spec")
324		}
325		// Secret names are case-insensitive, so compare declared names and caller aliases upper-cased.
326		declaredNames := make(container.Set[string], len(spec.Secrets))
327		for name := range spec.Secrets {
328			declaredNames.Add(strings.ToUpper(name))
329		}
330		provided := make(container.Set[string], len(mapping))
331		for alias := range mapping {
332			up := strings.ToUpper(alias)
333			provided.Add(up)
334			if !declaredNames.Contains(up) {
335				return fmt.Errorf("caller secret %q is not declared in the called workflow's on.workflow_call.secrets", alias)
336			}
337		}
338		for name, sec := range spec.Secrets {
339			if sec.Required && !provided.Contains(strings.ToUpper(name)) {
340				return fmt.Errorf("required secret %q is not provided by the caller", name)
341			}
342		}
343		return nil
344	}
345	
346	// EvaluateWorkflowCallOutputs evaluates a called workflow's "on.workflow_call.outputs.<name>.value" expressions against the provided contexts.
347	func EvaluateWorkflowCallOutputs(spec *WorkflowCallSpec, gitCtx *model.GithubContext, vars map[string]string, inputs map[string]any, jobOutputs JobOutputs) (map[string]string, error) {
348		if spec == nil || len(spec.Outputs) == 0 {
349			return map[string]string{}, nil
350		}
351	
352		jobsCtx := make(map[string]*model.WorkflowCallResult, len(jobOutputs))
353		for jobID, outputs := range jobOutputs {
354			jobsCtx[jobID] = &model.WorkflowCallResult{Outputs: outputs}
355		}
356	
357		// See `on.workflow_call.outputs.<output_id>.value` in https://docs.github.com/en/actions/reference/workflows-and-actions/contexts#context-availability
358		env := &exprparser.EvaluationEnvironment{
359			Github: gitCtx,
360			Jobs:   &jobsCtx,
361			Vars:   vars,
362			Inputs: inputs,
363		}
364		interpreter := exprparser.NewInterpeter(env, exprparser.Config{})
365	
366		out := make(map[string]string, len(spec.Outputs))
367		for name, o := range spec.Outputs {
368			v, err := evaluateWorkflowCallOutputValue(interpreter, o.Value)
369			if err != nil {
370				return nil, fmt.Errorf("workflow_call output %q: %w", name, err)
371			}
372			out[name] = v
373		}
374		return out, nil
375	}
376	
377	func evaluateWorkflowCallOutputValue(interpreter exprparser.Interpreter, value string) (string, error) {
378		if !strings.Contains(value, "${{") || !strings.Contains(value, "}}") {
379			return value, nil
380		}
381		expr, err := rewriteSubExpression(value, true)
382		if err != nil {
383			return "", err
384		}
385		evaluated, err := interpreter.Evaluate(expr, exprparser.DefaultStatusCheckNone)
386		if err != nil {
387			return "", err
388		}
389		return toString(evaluated), nil
390	}
391	
392	func toString(v any) string {
393		switch s := v.(type) {
394		case string:
395			return s
396		case nil:
397			return ""
398		default:
399			return fmt.Sprintf("%v", s)
400		}
401	}

