	"testing"

	runnerv1 "gitea.dev/actions-proto-go/runner/v1"
	"gitea.dev/actions-proto-go/runner/v1/runnerv1connect"
	actions_model "gitea.dev/models/actions"
	"gitea.dev/models/db"
	repo_model "gitea.dev/models/repo"
	secret_model "gitea.dev/models/secret"
	"gitea.dev/models/unittest"
	user_model "gitea.dev/models/user"
	"gitea.dev/modules/setting"
	runner_api "gitea.dev/routers/api/actions/runner"
	actions_service "gitea.dev/services/actions"

	"connectrpc.com/connect"
	"github.com/stretchr/testify/require"
	"go.yaml.in/yaml/v4"
	"google.golang.org/protobuf/types/known/timestamppb"
)

type env struct {
	t     *testing.T
	ctx   context.Context
	srv   *httptest.Server
	repo  *repo_model.Repository
	user  *user_model.User
	files map[string]string // path -> content committed
	sha   string
	idx   int
}

func newEnv(t *testing.T) *env {
	unittest.PrepareTestEnv(t)
	require.True(t, actions_service.ProbeInitQueue())
	path, h := runner_api.NewRunnerServiceHandler()
	mux := http.NewServeMux()
	mux.Handle(path, h)
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	e := &env{t: t, ctx: t.Context(), srv: srv, files: map[string]string{}}
	e.repo = unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	e.user = unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	return e
}

func (e *env) git(stdin string, env []string, args ...string) string {
	cmd := exec.Command("git", args...)
	cmd.Env = append(os.Environ(), env...)
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}
	out, err := cmd.CombinedOutput()
	require.NoError(e.t, err, "git %v: %s", args, out)
	return strings.TrimSpace(string(out))
}

// commit writes the workflow files into the repo's master branch
func (e *env) commit(files map[string]string) {
	gitDir := filepath.Join(setting.RepoRootPath, "user5", "repo4.git")
	idx := filepath.Join(e.t.TempDir(), "index")
	ge := []string{"GIT_DIR=" + gitDir, "GIT_INDEX_FILE=" + idx, "GIT_AUTHOR_NAME=p", "GIT_AUTHOR_EMAIL=p@example.com", "GIT_COMMITTER_NAME=p", "GIT_COMMITTER_EMAIL=p@example.com"}
	e.git("", ge, "read-tree", "master")
	for p, c := range files {
		tmp := filepath.Join(e.t.TempDir(), "blob")
		require.NoError(e.t, os.WriteFile(tmp, []byte(c), 0o644))
		blob := e.git("", ge, "hash-object", "-w", tmp)
		e.git("", ge, "update-index", "--add", "--cacheinfo", "100644,"+blob+","+p)
		e.files[p] = c
	}
	tree := e.git("", ge, "write-tree")
	e.sha = e.git("", ge, "commit-tree", tree, "-p", "master", "-m", "workflows")
	e.git("", ge, "update-ref", "refs/heads/master", e.sha)
}

type fakeRunner struct {
	e      *env
	client runnerv1connect.RunnerServiceClient
}

func (e *env) runner(name string) *fakeRunner {
	tok, err := actions_model.NewRunnerToken(e.ctx, 0, 0)
	require.NoError(e.t, err)
	plain := runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL)
	resp, err := plain.Register(e.ctx, connect.NewRequest(&runnerv1.RegisterRequest{Name: name, Token: tok.Token, Labels: []string{"probe"}, Version: "probe"}))
	require.NoError(e.t, err)
	uuid, token := resp.Msg.Runner.Uuid, resp.Msg.Runner.Token
	ic := connect.UnaryInterceptorFunc(func(next connect.UnaryFunc) connect.UnaryFunc {
		return func(ctx context.Context, req connect.AnyRequest) (connect.AnyResponse, error) {
			req.Header().Set("x-runner-uuid", uuid)
			req.Header().Set("x-runner-token", token)
			return next(ctx, req)
		}
	})
	return &fakeRunner{e: e, client: runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL, connect.WithInterceptors(ic))}
}

func (r *fakeRunner) fetch() (*runnerv1.Task, error) {
	resp, err := r.client.FetchTask(r.e.ctx, connect.NewRequest(&runnerv1.FetchTaskRequest{TasksVersion: 0}))
	if err != nil {
		return nil, err
	}
	return resp.Msg.Task, nil
}

func (r *fakeRunner) finish(taskID int64, result runnerv1.Result, outputs map[string]string) error {
	now := timestamppb.Now()
	st := &runnerv1.TaskState{Id: taskID, Result: result, StartedAt: now, StoppedAt: now}
	_, err := r.client.UpdateTask(r.e.ctx, connect.NewRequest(&runnerv1.UpdateTaskRequest{State: st, Outputs: outputs}))
	if err != nil {
		return err
	}
	_, err = r.client.UpdateLog(r.e.ctx, connect.NewRequest(&runnerv1.UpdateLogRequest{TaskId: taskID, Index: 0, Rows: []*runnerv1.LogRow{{Time: now, Content: "ok"}}, NoMore: true}))
	return err
}

func (e *env) flush() {
	if err := actions_service.ProbeFlush(e.ctx); err != nil {
		e.t.Logf("     (emitter flush: %v)", err)
	}
}

func (e *env) newRun(workflowFile, event, eventPayload string, inputs map[string]any) *actions_model.ActionRun {
	content := e.files[".gitea/workflows/"+workflowFile]
	if eventPayload == "" {
		eventPayload = `{"head_commit":{"id":"` + e.sha + `"}}`
	}
	run := &actions_model.ActionRun{Title: "probe", RepoID: e.repo.ID, OwnerID: e.repo.OwnerID, WorkflowID: workflowFile, TriggerUserID: e.user.ID, Ref: "refs/heads/master", CommitSHA: e.sha, Event: "push", TriggerEvent: event, EventPayload: eventPayload, WorkflowRepoID: e.repo.ID, WorkflowCommitSHA: e.sha}
	if event == "workflow_dispatch" {
		run.Event = "workflow_dispatch"
	}
	if err := actions_service.PrepareRunAndInsert(e.ctx, []byte(content), run, inputs); err != nil {
		e.t.Logf("   RUN NOT CREATED: %v", err)
		return nil
	}
	e.flush()
	return run
}

type wfDoc struct {
	Jobs map[string]struct {
		Outputs map[string]string `yaml:"outputs"`
		Steps   []struct {
			Run  string         `yaml:"run"`
			Uses string         `yaml:"uses"`
			With map[string]any `yaml:"with"`
		} `yaml:"steps"`
	} `yaml:"jobs"`
}

// sourceFileOf returns the workflow file a job's definition came from
func (e *env) sourceFileOf(run *actions_model.ActionRun, job *actions_model.ActionRunJob) string {
	if job.ParentJobID == 0 {
		return ".gitea/workflows/" + run.WorkflowID
	}
	parent, err := actions_model.GetRunJobByRunAndID(e.ctx, run.ID, job.ParentJobID)
	require.NoError(e.t, err)
	u := parent.CallUses
	if i := strings.Index(u, "@"); i > 0 {
		u = u[:i]
		u = strings.Join(strings.Split(u, "/")[2:], "/")
	}
	return strings.TrimPrefix(u, "./")
}

// drive plays the runner until nothing is offered any more
func (e *env) drive(run *actions_model.ActionRun, r *fakeRunner, fail map[string]bool, verbose bool) {
	started := 0
	for i := 0; i < 300; i++ {
		task, err := r.fetch()
		if err != nil {
			e.t.Logf("   FetchTask ERROR: %v", err)
			break
		}
		if task == nil {
			e.flush()
			if task, err = r.fetch(); err != nil || task == nil {
				if err != nil {
					e.t.Logf("   FetchTask ERROR: %v", err)
				}
				break
			}
		}
		started++
		at, _ := actions_model.GetTaskByID(e.ctx, task.Id)
		job, _ := actions_model.GetRunJobByRepoAndID(e.ctx, e.repo.ID, at.JobID)

		// 1. can the payload handed to the runner be parsed, and are the scripts what the author wrote
		var got wfDoc
		problems := []string{}
		if err := yaml.Unmarshal(task.WorkflowPayload, &got); err != nil {
			problems = append(problems, "payload does not parse: "+err.Error())
		}
		var src wfDoc
		srcFile := e.sourceFileOf(run, job)
		_ = yaml.Unmarshal([]byte(e.files[srcFile]), &src)
		gj, sj := got.Jobs[job.JobID], src.Jobs[job.JobID]
		if len(gj.Steps) != len(sj.Steps) {
			problems = append(problems, fmt.Sprintf("steps: source %d, payload %d", len(sj.Steps), len(gj.Steps)))
