	x, err := xorm.NewEngine("mysql", "root:pw@tcp(127.0.0.1:33306)/probe?charset=utf8mb4&parseTime=true")
	if err != nil {
		t.Skip(err)
	}
	x.SetMapper(names.GonicMapper{})
	if err := x.Ping(); err != nil {
		t.Skipf("mysql not reachable: %v", err)
	}
	_ = x.DropTables(new(ActionRunJob), new(ActionSchedule))
	if err := x.Sync(new(ActionRunJob), new(ActionSchedule)); err != nil {
		t.Fatal(err)
	}
	rows, _ := x.QueryString("SELECT table_name, column_name, column_type FROM information_schema.columns WHERE table_schema='probe' AND data_type LIKE '%blob%' OR (table_schema='probe' AND data_type LIKE '%text%') ORDER BY table_name, column_name")
	for _, r := range rows {
		t.Logf("column %s.%s = %s", r["TABLE_NAME"]+r["table_name"], r["COLUMN_NAME"]+r["column_name"], r["COLUMN_TYPE"]+r["column_type"])
	}
	mode, _ := x.QueryString("SELECT @@sql_mode AS m")
	t.Logf("server sql_mode = %s", mode[0]["m"])
	for _, kb := range []int{60, 64, 70, 200} {
		payload := bytes.Repeat([]byte("x"), kb*1024)
		job := &ActionRunJob{RunID: 1, RepoID: 1, Name: "j", JobID: "j", WorkflowPayload: payload, Status: StatusWaiting}
		_, err := x.Insert(job)
		got := new(ActionRunJob)
		stored := -1
		if err == nil {
			if has, _ := x.ID(job.ID).Get(got); has {
				stored = len(got.WorkflowPayload)
			}
		}
		t.Logf("job payload %3d KB: insert err=%v ; stored bytes=%d", kb, err, stored)
	}
	for _, kb := range []int{60, 70} {
		s := &ActionSchedule{RepoID: 1, WorkflowID: "w.yml", Content: bytes.Repeat([]byte("x"), kb*1024)}
		_, err := x.Insert(s)
		t.Logf("schedule workflow file %3d KB: insert err=%v", kb, err)
	}
	_, _ = x.Exec("SET SESSION sql_mode=''")
}
