// commitRef adds files on top of parent and points ref at the new commit
func (e *env) commitRef(repoRel, parent, label string, files map[string]string, refs ...string) string {
	idx := []string{"GIT_INDEX_FILE=" + filepath.Join(e.t.TempDir(), "index")}
	e.git(repoRel, idx, "read-tree", parent)
	paths := make([]string, 0, len(files))
	for p := range files {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		tmp := filepath.Join(e.t.TempDir(), "blob")
