func str(task *runnerv1.Task, key string) string {
	v := task.Context.Fields[key]
	if v == nil {
		return "<absent>"
	}
	switch v.Kind.(type) {
	case nil:
		return "<null>"
	}
	if s := v.GetStringValue(); s != "" {
		return s
	}
	out := fmt.Sprint(v.AsInterface())
	if out == "" {
		return `""`
	}
	return out
}

func dig(m map[string]any, path string) string {
	var cur any = m
	for _, p := range strings.Split(path, ".") {
		mm, ok := cur.(map[string]any)
		if !ok {
			return "<absent>"
		}
		cur, ok = mm[p]
		if !ok {
			return "<absent>"
		}
	}
	if cur == nil {
		return "<null>"
	}
	return fmt.Sprint(cur)
}

// newRuns reports the runs created since the last call
func (e *env) newRuns() []*actions_model.ActionRun {
