}

func (e *env) runner(name string) *fakeRunner {
	tok, err := actions_model.NewRunnerToken(e.ctx, 0, 0)
	require.NoError(e.t, err)
	plain := runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL)
	resp, err := plain.Register(e.ctx, connect.NewRequest(&runnerv1.RegisterRequest{Name: name, Token: tok.Token, Labels: []string{"probe"}, Version: "probe"}))
	require.NoError(e.t, err)
	uuid, token := resp.Msg.Runner.Uuid, resp.Msg.Runner.Token
	ic := connect.UnaryInterceptorFunc(func(next connect.UnaryFunc) connect.UnaryFunc {
		return func(ctx context.Context, req connect.AnyRequest) (connect.AnyResponse, error) {
			req.Header().Set("x-runner-uuid", uuid)
			req.Header().Set("x-runner-token", token)
			return next(ctx, req)
		}
	})
	return &fakeRunner{e: e, client: runnerv1connect.NewRunnerServiceClient(e.srv.Client(), e.srv.URL, connect.WithInterceptors(ic))}
}

func (r *fakeRunner) fetch() *runnerv1.Task {
	resp, err := r.client.FetchTask(r.e.ctx, connect.NewRequest(&runnerv1.FetchTaskRequest{TasksVersion: 0}))
	if err != nil {
		r.e.t.Logf("   FetchTask ERROR: %v", err)
		return nil
	}
	return resp.Msg.Task
}

func (r *fakeRunner) finish(taskID int64, result runnerv1.Result, outputs map[string]string) {
	now := timestamppb.Now()
	st := &runnerv1.TaskState{Id: taskID, Result: result, StartedAt: now, StoppedAt: now}
	_, err := r.client.UpdateTask(r.e.ctx, connect.NewRequest(&runnerv1.UpdateTaskRequest{State: st, Outputs: outputs}))
	require.NoError(r.e.t, err)
	r.e.flush()
}

func (e *env) flush() {
	if err := actions_service.ProbeFlush(e.ctx); err != nil {
		e.t.Logf("     (emitter flush: %v)", err)
	}
}

func str(task *runnerv1.Task, key string) string {
	v := task.Context.Fields[key]
	if v == nil {
		return "<absent>"
	}
	switch v.Kind.(type) {
	case nil:
		return "<null>"
	}
	if s := v.GetStringValue(); s != "" {
		return s
	}
	out := fmt.Sprint(v.AsInterface())
	if out == "" {
		return `""`
	}
	return out
}

func dig(m map[string]any, path string) string {
	var cur any = m
	for _, p := range strings.Split(path, ".") {
		mm, ok := cur.(map[string]any)
		if !ok {
			return "<absent>"
		}
		cur, ok = mm[p]
		if !ok {
			return "<absent>"
		}
	}
	if cur == nil {
		return "<null>"
	}
	return fmt.Sprint(cur)
}

// newRuns reports the runs created since the last call
func (e *env) newRuns() []*actions_model.ActionRun {
	var runs []*actions_model.ActionRun
	require.NoError(e.t, db.GetEngine(e.ctx).Where("id > ?", e.seen).Asc("id").Find(&runs))
	for _, r := range runs {
		e.seen = r.ID
		e.t.Logf("   run created: workflow=%s event=%s trigger_event=%s ref=%s sha=%s fork_pr=%v need_approval=%v status=%s workflow_commit=%s",
			r.WorkflowID, r.Event, r.TriggerEvent, r.Ref, e.sha(r.CommitSHA), r.IsForkPullRequest, r.NeedApproval, r.Status, e.sha(r.WorkflowCommitSHA))
	}
	if len(runs) == 0 {
		e.t.Logf("   NO RUN CREATED")
	}
	return runs
}

var allKeysShown bool

// drain lets the runner take every waiting job and reports what each was handed
func (e *env) drain(r *fakeRunner, eventPaths ...string) {
	e.flush()
	for i := 0; i < 20; i++ {
		task := r.fetch()
		if task == nil {
			return
		}
		at, _ := actions_model.GetTaskByID(e.ctx, task.Id)
		job, _ := actions_model.GetRunJobByRepoAndID(e.ctx, at.RepoID, at.JobID)
		run, _ := actions_model.GetRunByRepoAndID(e.ctx, job.RepoID, job.RunID)
		e.t.Logf("   -- job %q of %s (%s)", job.Name, run.WorkflowID, run.TriggerEvent)
		if !allKeysShown {
			allKeysShown = true
			keys := make([]string, 0, len(task.Context.Fields))
			for k := range task.Context.Fields {
				if k != "event" && k != "token" && k != "gitea_runtime_token" {
					keys = append(keys, k)
				}
			}
			sort.Strings(keys)
			var kv []string
			for _, k := range keys {
				kv = append(kv, k+"="+str(task, k))
			}
			e.t.Logf("      FULL CONTEXT (first job only): %s", strings.Join(kv, " | "))
		}
		e.t.Logf("      event_name=%s ref=%s ref_name=%s ref_type=%s sha=%s", str(task, "event_name"), str(task, "ref"), str(task, "ref_name"), str(task, "ref_type"), e.sha(str(task, "sha")))
		e.t.Logf("      base_ref=%s head_ref=%s actor=%s triggering_actor=%s workflow=%s run_number=%s run_attempt=%s job=%s", str(task, "base_ref"), str(task, "head_ref"), str(task, "actor"), str(task, "triggering_actor"), str(task, "workflow"), str(task, "run_number"), str(task, "run_attempt"), str(task, "job"))
		ev := map[string]any{}
		if s := task.Context.Fields["event"].GetStructValue(); s != nil {
			ev = s.AsMap()
		}
		keys := make([]string, 0, len(ev))
		for k := range ev {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		e.t.Logf("      event keys: %v", keys)
		var picked []string
		for _, p := range eventPaths {
			v := dig(ev, p)
			if len(v) == 40 {
				v = e.sha(v)
			}
			picked = append(picked, "event."+p+"="+v)
		}
		if len(picked) > 0 {
			e.t.Logf("      %s", strings.Join(picked, " | "))
		}
		var sec, vars []string
		for k := range task.Secrets {
			sec = append(sec, k)
		}
		for k := range task.Vars {
			vars = append(vars, k)
		}
		sort.Strings(sec)
		sort.Strings(vars)
		e.t.Logf("      secrets=%v vars=%v", sec, vars)
		if job.ParentJobID > 0 || strings.Contains(string(task.WorkflowPayload), "MARK") {
			for _, line := range strings.Split(string(task.WorkflowPayload), "\n") {
				if strings.Contains(line, "MARK") {
					e.t.Logf("      script the job will run: %s", strings.TrimSpace(line))
				}
			}
		}
		r.finish(task.Id, runnerv1.Result_RESULT_SUCCESS, nil)
	}
}

