on:
  push:
  pull_request:
  workflow_dispatch:
    inputs:
      level:
        type: choice
        options: [debug, info]
        default: info
      dry_run:
        type: boolean
        default: true
  schedule:
    - cron: '30 5 * * 1-5'
jobs:
  show:
    runs-on: probe
    steps:
      - run: echo show
`

const ptYml = `name: PR Target
on: pull_request_target
jobs:
  label:
    runs-on: probe
    steps:
      - run: echo label
  publish:
    uses: ./.gitea/workflows/shared.yml
    secrets: inherit
`

func sharedYml(mark string) string {
	return "on: workflow_call\njobs:\n  preview:\n    runs-on: probe\n    steps:\n      - run: echo MARK-" + mark + " && deploy --key \"${{ secrets.PROD_KEY }}\"\n"
}

func pushCommits(sha string) *repo_module.PushCommits {
	pc := &repo_module.PushCommit{Sha1: sha, Message: "probe commit", AuthorEmail: "p@example.com", AuthorName: "p", CommitterEmail: "p@example.com", CommitterName: "p", Timestamp: time.Now()}
	return &repo_module.PushCommits{Commits: []*repo_module.PushCommit{pc}, HeadCommit: pc, Len: 1}
}

func TestProbe_Context(t *testing.T) {
	e := newEnv(t)
	n := actions_service.NewNotifier()
	r := e.runner("ctx")
	repo1 := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 1})
	user2 := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	_, _ = secret_model.InsertEncryptedSecret(e.ctx, 0, 1, "PROD_KEY", "k", "")
	_, _ = actions_model.InsertVariable(e.ctx, 0, 1, "REGION", "eu", "")

	oldMaster := e.git("user2/repo1", nil, "rev-parse", "refs/heads/master")
	e.names[oldMaster] = "repo1 master before push"
	master := e.commitRef("user2/repo1", oldMaster, "repo1 master, pushed commit", map[string]string{".gitea/workflows/ctx.yml": ctxYml, ".gitea/workflows/pt.yml": ptYml, ".gitea/workflows/shared.yml": sharedYml("TRUSTED-from-base-branch")}, "refs/heads/master")

	t.Log("== T1 push to the default branch")
	n.PushCommits(e.ctx, user2, repo1, &repo_module.PushUpdateOptions{PusherID: 2, PusherName: "user2", RepoUserName: "user2", RepoName: "repo1", RefFullName: git.RefNameFromBranch("master"), OldCommitID: oldMaster, NewCommitID: master}, pushCommits(master))
	e.newRuns()
	e.drain(r, "ref", "before", "after", "head_commit.id", "pusher.login", "sender.login")

	t.Log("== T2 push of a tag")
	e.git("user2/repo1", nil, "update-ref", "refs/tags/v2.0.0", master)
	n.PushCommits(e.ctx, user2, repo1, &repo_module.PushUpdateOptions{PusherID: 2, PusherName: "user2", RepoUserName: "user2", RepoName: "repo1", RefFullName: git.RefNameFromTag("v2.0.0"), OldCommitID: strings.Repeat("0", 40), NewCommitID: master}, pushCommits(master))
	e.newRuns()
	e.drain(r, "ref")

	t.Log("== T3 schedule (registered by the push above), fired by the scheduler")
	specs, _, err := actions_model.FindSpecs(e.ctx, actions_model.FindSpecOptions{RepoID: 1})
	require.NoError(t, err)
	t.Logf("   schedule specs registered: %d", len(specs))
	// the default branch moves on without the actions notifier seeing it (e.g. a later push while the instance was busy is not needed: any commit after registration)
	later := e.commitRef("user2/repo1", master, "repo1 master, later commit", map[string]string{"README2.md": "x"}, "refs/heads/master")
	_ = later
	if len(specs) > 0 {
		require.NoError(t, actions_service.CreateScheduleTask(e.ctx, specs[0]))
		e.newRuns()
		e.drain(r, "schedule", "head_commit.id", "pusher.login", "ref")
	}
	e.git("user2/repo1", nil, "update-ref", "refs/heads/master", master)

	t.Log("== T4 schedule registered the other way (Actions re-enabled / repo un-archived), fired by the scheduler")
	require.NoError(t, actions_service.DetectAndHandleSchedules(e.ctx, repo1))
	specs, _, _ = actions_model.FindSpecs(e.ctx, actions_model.FindSpecOptions{RepoID: 1})
	if len(specs) > 0 {
		require.NoError(t, actions_service.CreateScheduleTask(e.ctx, specs[0]))
		e.newRuns()
		e.drain(r, "schedule", "repository.full_name")
	}

	t.Log("== T5 manual dispatch on master with inputs level=debug, dry_run unticked")
	gitRepo, err := gitrepo.OpenRepository(e.ctx, repo1)
	require.NoError(t, err)
	_, err = actions_service.DispatchActionWorkflow(reqctx.NewRequestContextForTest(e.ctx), user2, repo1, gitRepo, "ctx.yml", "master", 0, func(wd *act_model.WorkflowDispatch, inputs map[string]any) error {
		form := map[string]string{"level": "debug"} // what the web form posts; an unticked checkbox posts nothing
		for name, cfg := range wd.Inputs {
			if cfg.Type == "boolean" {
				inputs[name] = strconv.FormatBool(form[name] == "on")
			} else if v, ok := form[name]; ok {
				inputs[name] = v
			} else {
				inputs[name] = cfg.Default
			}
		}
		return nil
	})
	gitRepo.Close()
	if err != nil {
		t.Logf("   dispatch error: %v", err)
	}
	e.newRuns()
	e.drain(r, "inputs", "ref", "workflow", "sender.login")

	t.Log("== T6 pull request inside one repo (branch2 -> master), opened by its author")
	base := e.git("user2/repo1", nil, "rev-parse", "refs/heads/branch2")
	prHead := e.commitRef("user2/repo1", base, "PR head (same repo)", map[string]string{".gitea/workflows/ctx.yml": ctxYml, ".gitea/workflows/shared.yml": sharedYml("CHANGED-in-PR-head")}, "refs/heads/branch2", "refs/pull/3/head")
	_ = prHead
	pr, err := issues_model.GetPullRequestByID(e.ctx, 2)
	require.NoError(t, err)
	n.NewPullRequest(e.ctx, pr, nil)
	e.newRuns()
	e.drain(r, "action", "number", "pull_request.head.ref", "pull_request.head.sha", "pull_request.base.ref", "pull_request.base.sha", "pull_request.merge_base", "pull_request.head.repo.full_name", "sender.login")

	t.Log("== T7 pull request from a fork (user13/repo11:branch2 -> user12/repo10:master), opened by an outside contributor")
	require.NoError(t, db.Insert(e.ctx, &repo_model.RepoUnit{RepoID: 10, Type: unit.TypeActions}))
	_, _ = secret_model.InsertEncryptedSecret(e.ctx, 0, 10, "PROD_KEY", "k", "")
	_, _ = actions_model.InsertVariable(e.ctx, 0, 10, "REGION", "eu", "")
	baseOld := e.git("user12/repo10", nil, "rev-parse", "refs/heads/master")
	forkMaster := e.git("user13/repo11", nil, "rev-parse", "refs/heads/master")
	t.Logf("   base master == fork master: %v", baseOld == forkMaster)
	e.names[baseOld] = "fork point"
	baseMaster := e.commitRef("user12/repo10", baseOld, "BASE repo master", map[string]string{".gitea/workflows/pt.yml": ptYml, ".gitea/workflows/shared.yml": sharedYml("TRUSTED-from-base-branch")}, "refs/heads/master")
	_ = baseMaster
	forkFiles := map[string]string{".gitea/workflows/ctx.yml": ctxYml, ".gitea/workflows/shared.yml": sharedYml("ATTACKER-from-fork-PR-head")}
	forkHead := e.commitRef("user13/repo11", forkMaster, "FORK PR head", forkFiles, "refs/heads/branch2")
	forkHead2 := e.commitRef("user12/repo10", baseOld, "FORK PR head", forkFiles, "refs/pull/1/head")
	t.Logf("   fork head identical in both repos: %v", forkHead == forkHead2)
	pr3, err := issues_model.GetPullRequestByID(e.ctx, 3)
	require.NoError(t, err)
	n.NewPullRequest(e.ctx, pr3, nil)
	runs := e.newRuns()
	t.Log("   .. jobs the runner is given WITHOUT anyone approving:")
	e.drain(r, "action", "pull_request.head.ref", "pull_request.head.sha", "pull_request.base.ref", "pull_request.base.sha", "pull_request.head.repo.full_name", "pull_request.head.repo.fork", "sender.login")
	var needApproval []int64
	for _, run := range runs {
		if run.NeedApproval {
			needApproval = append(needApproval, run.ID)
		}
	}
	if len(needApproval) > 0 {
		t.Log("   .. after a maintainer approves the pull_request run:")
		repo10 := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 10})
		require.NoError(t, actions_service.ApproveRuns(e.ctx, repo10, user2, needApproval))
		e.drain(r, "action", "pull_request.head.sha", "pull_request.base.sha")
	}
}
