// ---- artifact client, as the runner's upload/download actions would call it with the job's runtime token ----

func (e *env) do(method, pathAndQuery, token string, body []byte, hdr map[string]string) (int, []byte) {
	req, err := http.NewRequestWithContext(e.ctx, method, e.srv.URL+pathAndQuery, bytes.NewReader(body))
	require.NoError(e.t, err)
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	for k, v := range hdr {
		req.Header.Set(k, v)
	}
	resp, err := e.srv.Client().Do(req)
	require.NoError(e.t, err)
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, b
}

func pathOf(raw, from string) string {
	i := strings.Index(raw, from)
	if i < 0 {
		return raw
	}
	return raw[i:]
}

func rtToken(task *runnerv1.Task) string {
	return task.Context.Fields["gitea_runtime_token"].GetStringValue()
}

func (e *env) v3Upload(task *runnerv1.Task, runID int64, name, content string) string {
	base := fmt.Sprintf("/api/actions_pipeline/_apis/pipelines/workflows/%d/artifacts", runID)
	reqBody, _ := json.Marshal(map[string]any{"Type": "actions_storage", "Name": name})
	code, b := e.do("POST", base, rtToken(task), reqBody, map[string]string{"Content-Type": "application/json"})
	if code != 200 {
		return fmt.Sprintf("get upload url HTTP %d", code)
	}
	var up struct {
		FileContainerResourceURL string `json:"fileContainerResourceUrl"`
	}
	_ = json.Unmarshal(b, &up)
	sum := md5.Sum([]byte(content))
	code, _ = e.do("PUT", pathOf(up.FileContainerResourceURL, "/api/actions_pipeline")+"?itemPath="+url.QueryEscape(name+"/file.txt"), rtToken(task), []byte(content), map[string]string{
		"Content-Range": fmt.Sprintf("bytes 0-%d/%d", len(content)-1, len(content)), "x-tfs-filelength": strconv.Itoa(len(content)), "x-actions-results-md5": base64.StdEncoding.EncodeToString(sum[:]),
	})
	if code != 200 {
		return fmt.Sprintf("upload HTTP %d", code)
	}
	code, _ = e.do("PATCH", base+"?artifactName="+url.QueryEscape(name), rtToken(task), nil, nil)
	return fmt.Sprintf("HTTP %d", code)
}

func (e *env) v3List(task *runnerv1.Task, runID int64) string {
	code, b := e.do("GET", fmt.Sprintf("/api/actions_pipeline/_apis/pipelines/workflows/%d/artifacts", runID), rtToken(task), nil, nil)
	var out struct {
		Value []struct {
			Name string `json:"name"`
		} `json:"value"`
	}
	_ = json.Unmarshal(b, &out)
	var names []string
	for _, v := range out.Value {
		names = append(names, v.Name)
	}
	return fmt.Sprintf("HTTP %d %v", code, names)
}

func (e *env) v3DownloadURL(task *runnerv1.Task, runID int64, name string) string {
	code, _ := e.do("GET", fmt.Sprintf("/api/actions_pipeline/_apis/pipelines/workflows/%d/artifacts/%x/download_url?itemPath=%s", runID, md5.Sum([]byte(name)), url.QueryEscape(name)), rtToken(task), nil, nil)
	return fmt.Sprintf("HTTP %d", code)
}

func (e *env) twirp(task *runnerv1.Task, method string, in, out proto.Message) int {
	body, _ := protojson.Marshal(in)
	code, b := e.do("POST", actions_router.ArtifactV4RouteBase+"/"+method, rtToken(task), body, map[string]string{"Content-Type": "application/json"})
	if out != nil && code == 200 {
		_ = protojson.UnmarshalOptions{DiscardUnknown: true}.Unmarshal(b, out)
	}
	return code
}

func (e *env) v4Upload(task *runnerv1.Task, runID, jobID int64, name, content string) string {
	var cr actions_router.CreateArtifactResponse
	code := e.twirp(task, "CreateArtifact", &actions_router.CreateArtifactRequest{Version: 4, Name: name, WorkflowRunBackendId: strconv.FormatInt(runID, 10), WorkflowJobRunBackendId: strconv.FormatInt(jobID, 10)}, &cr)
	if code != 200 {
		return fmt.Sprintf("CreateArtifact HTTP %d", code)
	}
	code, _ = e.do("PUT", pathOf(cr.SignedUploadUrl, actions_router.ArtifactV4RouteBase)+"&comp=appendBlock", "", []byte(content), nil)
	if code != 201 {
		return fmt.Sprintf("upload HTTP %d", code)
	}
	var fr actions_router.FinalizeArtifactResponse
	code = e.twirp(task, "FinalizeArtifact", &actions_router.FinalizeArtifactRequest{Name: name, Size: int64(len(content)), WorkflowRunBackendId: strconv.FormatInt(runID, 10), WorkflowJobRunBackendId: strconv.FormatInt(jobID, 10)}, &fr)
	return fmt.Sprintf("HTTP %d ok=%v", code, fr.Ok)
}

func (e *env) v4List(task *runnerv1.Task, runID, jobID int64) string {
	var lr actions_router.ListArtifactsResponse
	code := e.twirp(task, "ListArtifacts", &actions_router.ListArtifactsRequest{WorkflowRunBackendId: strconv.FormatInt(runID, 10), WorkflowJobRunBackendId: strconv.FormatInt(jobID, 10)}, &lr)
	var names []string
	for _, a := range lr.Artifacts {
		names = append(names, a.Name)
	}
	return fmt.Sprintf("HTTP %d %v", code, names)
}

func (e *env) v4Get(task *runnerv1.Task, runID, jobID int64, name string) string {
	var gr actions_router.GetSignedArtifactURLResponse
	code := e.twirp(task, "GetSignedArtifactURL", &actions_router.GetSignedArtifactURLRequest{Name: name, WorkflowRunBackendId: strconv.FormatInt(runID, 10), WorkflowJobRunBackendId: strconv.FormatInt(jobID, 10)}, &gr)
	return fmt.Sprintf("HTTP %d", code)
}

func (e *env) uiArtifacts(runID, attemptID int64) []string {
	arts, err := actions_model.ListUploadedArtifactsMetaByRunAttempt(e.ctx, 1, runID, attemptID)
	require.NoError(e.t, err)
	var names []string
	for _, a := range arts {
		names = append(names, a.ArtifactName)
	}
	return names
}

func (e *env) statuses(sha, wf string) string {
	sts, err := git_model.GetLatestCommitStatus(e.ctx, 1, sha, db.ListOptionsAll)
	require.NoError(e.t, err)
	var out []string
	for _, s := range sts {
