			out = append(out, fmt.Sprintf("%s=%s(%s)", strings.TrimPrefix(s.Context, "Rerun Probe / "), s.State, s.TargetURL[strings.LastIndex(s.TargetURL, "/jobs/")+1:]))
		}
	}
	sort.Strings(out)
	return strings.Join(out, "  ")
}

