	run := &actions_model.ActionRun{Title: "probe", RepoID: 1, OwnerID: repo1.OwnerID, WorkflowID: "rerun.yml", TriggerUserID: user2.ID, Ref: "refs/heads/master", CommitSHA: head, Event: "push", TriggerEvent: "push", EventPayload: `{"ref":"refs/heads/master","head_commit":{"id":"` + head + `"}}`, WorkflowRepoID: 1, WorkflowCommitSHA: head}
	require.NoError(t, actions_service.PrepareRunAndInsert(e.ctx, []byte(wf), run, nil))
	e.flush()
	jobOf := func(task *runnerv1.Task) *actions_model.ActionRunJob {
		at, _ := actions_model.GetTaskByID(e.ctx, task.Id)
		j, _ := actions_model.GetRunJobByRepoAndID(e.ctx, 1, at.JobID)
		return j
	}

	t.Log("== A1 first attempt: build uploads two artifacts (old and new upload API) and sets an output; lint passes; test fails")
	var testTask *runnerv1.Task
	for i := 0; i < 3; i++ {
		task := r.fetch()
		require.NotNil(t, task)
		j := jobOf(task)
		switch j.JobID {
		case "build":
			t.Logf("   build: upload 'dist' (v3 API): %s ; upload 'dist-v4' (v4 API): %s", e.v3Upload(task, run.ID, "dist", "binary"), e.v4Upload(task, run.ID, j.ID, "dist-v4", "binary"))
			r.finish(task.Id, runnerv1.Result_RESULT_SUCCESS, map[string]string{"version": "1.2.3"})
		case "lint":
			r.finish(task.Id, runnerv1.Result_RESULT_SUCCESS, nil)
		case "test":
			testTask = task
		}
	}
	if testTask == nil {
		testTask = r.fetch()
	}
	require.NotNil(t, testTask)
	tj := jobOf(testTask)
	t.Logf("   test (attempt 1) sees: needs.build.outputs=%v ; artifacts v3 list: %s ; v4 list: %s ; download 'dist': %s", testTask.Needs["build"].Outputs, e.v3List(testTask, run.ID), e.v4List(testTask, run.ID, tj.ID), e.v3DownloadURL(testTask, run.ID, "dist"))
	r.finish(testTask.Id, runnerv1.Result_RESULT_FAILURE, nil)
	r1 := unittest.AssertExistsAndLoadBean(t, &actions_model.ActionRun{ID: run.ID})
	attempt1 := r1.LatestAttemptID
	t.Logf("   run=%s ; run page artifacts (attempt 1): %v", r1.Status, e.uiArtifacts(run.ID, attempt1))
	t.Logf("   commit statuses: %s", e.statuses(head, "Rerun Probe"))

	t.Log("== A2 a different user clicks 'rerun failed jobs'")
	_, err := actions_service.RerunWorkflowRunJobs(e.ctx, repo1, r1, user1, actions_service.GetFailedJobsForRerun(func() []*actions_model.ActionRunJob {
		js, _ := actions_model.GetLatestAttemptJobsByRepoAndRunID(e.ctx, 1, run.ID)
		return js
	}()))
	require.NoError(t, err)
	e.flush()
	r2 := unittest.AssertExistsAndLoadBean(t, &actions_model.ActionRun{ID: run.ID})
	t.Logf("   commit statuses right after rerun: %s", e.statuses(head, "Rerun Probe"))
	t.Logf("   run page artifacts now (latest attempt): %v ; attempt 1 still has: %v", e.uiArtifacts(run.ID, r2.LatestAttemptID), e.uiArtifacts(run.ID, attempt1))
	task2 := r.fetch()
	require.NotNil(t, task2)
	j2 := jobOf(task2)
	t.Logf("   test (attempt 2) context: run_attempt=%s actor=%s triggering_actor=%s sha=%s run_id same=%v", str(task2, "run_attempt"), str(task2, "actor"), str(task2, "triggering_actor"), e.sha(str(task2, "sha")), str(task2, "run_id") == strconv.FormatInt(run.ID, 10))
	t.Logf("   test (attempt 2) sees: needs.build={%s %v} needs.lint=%s", strings.TrimPrefix(task2.Needs["build"].Result.String(), "RESULT_"), task2.Needs["build"].Outputs, strings.TrimPrefix(task2.Needs["lint"].Result.String(), "RESULT_"))
	t.Logf("   test (attempt 2) artifacts: v3 list: %s ; v4 list: %s ; download 'dist' (v3): %s ; get 'dist-v4' (v4): %s", e.v3List(task2, run.ID), e.v4List(task2, run.ID, j2.ID), e.v3DownloadURL(task2, run.ID, "dist"), e.v4Get(task2, run.ID, j2.ID, "dist-v4"))
	t.Logf("   test (attempt 2) uploads its own 'report': %s ; and re-uploads a 'dist': %s", e.v3Upload(task2, run.ID, "report", "junit"), e.v3Upload(task2, run.ID, "dist", "other-binary"))
	r.finish(task2.Id, runnerv1.Result_RESULT_SUCCESS, nil)
	r3 := unittest.AssertExistsAndLoadBean(t, &actions_model.ActionRun{ID: run.ID})
	t.Logf("   run=%s ; run page artifacts (latest attempt): %v ; attempt 1: %v", r3.Status, e.uiArtifacts(run.ID, r3.LatestAttemptID), e.uiArtifacts(run.ID, attempt1))
	t.Logf("   commit statuses at the end: %s", e.statuses(head, "Rerun Probe"))
	js, _ := actions_model.GetLatestAttemptJobsByRepoAndRunID(e.ctx, 1, run.ID)
	for _, j := range js {
		t.Logf("   attempt-2 job row %-5s id=%d status=%s own task=%d borrowed task=%d", j.JobID, j.ID, j.Status, j.TaskID, j.SourceTaskID)
	}

	t.Log("== A3 'rerun all jobs' (attempt 3): nothing is reused")
	_, err = actions_service.RerunWorkflowRunJobs(e.ctx, repo1, r3, user1, nil)
	require.NoError(t, err)
	e.flush()
	for i := 0; i < 2; i++ {
		task := r.fetch()
		if task == nil {
			break
