		"C double-quoted with tab and newline":            "        run: \"printf 'a\\tb\\\\n' # not a comment: really\\n\"\n",
		"D first line indented, written with |4 style heredoc": "        run: |\n          cat <<EOF\n            indented\n          EOF\n",
		"E script whose first line is indented (python block)": "        run: |2\n              if True:\n                  print('x')\n",
		"F trailing spaces on a line":                        "        run: |\n          echo a   \n          echo b\n",
		"G only-whitespace line in the middle":               "        run: |\n          echo a\n             \n          echo b\n",
		"H tab-indented line (Makefile recipe)":              "        run: |\n          cat > Makefile <<'EOF'\n          all:\n          \tgo build ./...\n          EOF\n",
		"I line starting with a tab":                         "        run: |\n          echo a\n          \techo tabbed\n",
		"J leading blank line":                               "        run: |\n\n          echo after-blank\n",
		"K carriage returns inside (CRLF file)":              "        run: |\r\n          echo a\r\n          echo b\r\n",
		"L script starting with a space via quotes":          "        run: \"  leading spaces\\nsecond\\n\"\n",
		"M script that is only a newline-terminated space":   "        run: \" \\n\"\n",
		"N very long single line (5000 chars)":               "        run: echo " + strings.Repeat("x ", 2500) + "\n",
		"O unicode line/paragraph separators":                "        run: \"echo a\\u2028echo b\\u0085echo c\"\n",
		"P bell / escape control characters":                 "        run: \"printf '\\e[31mred\\e[0m\\a'\"\n",
	}
	names := make([]string, 0, len(cases))
	for n := range cases {
		names = append(names, n)
	}
	for _, n := range sortStrings(names) {
		src := "on: push\njobs:\n  j:\n    runs-on: x\n    steps:\n      - name: s\n" + cases[n]
		var orig struct {
			Jobs map[string]struct {
				Steps []struct {
					Run string `yaml:"run"`
				} `yaml:"steps"`
			} `yaml:"jobs"`
		}
		if err := yaml.Unmarshal([]byte(src), &orig); err != nil {
			t.Logf("%-55s source itself invalid: %v", n, err)
			continue
		}
		wfs, err := Parse([]byte(src), WithGitContext(&model.GithubContext{}))
		if err != nil {
			t.Logf("%-55s REJECTED at detection: %v", n, err)
			continue
		}
		payload, _ := wfs[0].Marshal()
		back := orig
		back.Jobs = nil
		if _, err := Parse(payload); err != nil {
			t.Logf("%-55s STORED PAYLOAD UNREADABLE: %v", n, err)
			continue
		}
		_ = yaml.Unmarshal(payload, &back)
		if back.Jobs["j"].Steps[0].Run != orig.Jobs["j"].Steps[0].Run {
			t.Logf("%-55s SCRIPT CHANGED: %q -> %q", n, orig.Jobs["j"].Steps[0].Run, back.Jobs["j"].Steps[0].Run)
			continue
		}
		t.Logf("%-55s ok", n)
	}
}

func sortStrings(s []string) []string {
	for i := range s {
		for j := i + 1; j < len(s); j++ {
			if s[j] < s[i] {
				s[i], s[j] = s[j], s[i]
			}
		}
	}
	return s
}
