// drive lets the runner take and finish every job; fail lists job names that fail; see is called for each job handed out
func (e *env) drive(r *fakeRunner, fail map[string]bool, see func(job *actions_model.ActionRunJob, task *runnerv1.Task)) int {
	n := 0
	for i := 0; i < 100; i++ {
		task, err := r.fetch()
		if err != nil {
			e.t.Logf("   FetchTask ERROR: %v", err)
			return n
		}
		if task == nil {
			e.flush()
			if task, _ = r.fetch(); task == nil {
				return n
			}
		}
		n++
		job := e.jobOf(task)
		if see != nil {
			see(job, task)
		}
		outs := map[string]string{}
		for _, line := range strings.Split(string(task.WorkflowPayload), "\n") {
			if strings.Contains(line, "PROBEOUT") { // "      key: ${{ ... }} # PROBEOUT value"
				parts := strings.SplitN(strings.TrimSpace(line), ":", 2)
				outs[parts[0]] = strings.TrimSpace(line[strings.Index(line, "PROBEOUT")+8:])
			}
		}
		for k := range outputKeys(task.WorkflowPayload, job.JobID) {
			if _, ok := outs[k]; !ok {
				outs[k] = job.Name + "." + k
			}
		}
		r.finish(task.Id, !fail[job.Name], outs)
	}
	return n
}

func outputKeys(payload []byte, jobID string) map[string]bool {
	out := map[string]bool{}
	in := false
	for _, line := range strings.Split(string(payload), "\n") {
		t := strings.TrimSpace(line)
		if t == "outputs:" {
			in = true
			continue
		}
		if in {
			if !strings.Contains(line, "${{") {
				in = false
				continue
			}
			out[strings.SplitN(t, ":", 2)[0]] = true
		}
	}
	return out
}

