func TestProbe_Recheck1(t *testing.T) {
	e := newEnv(t)
	r := e.runner()

	t.Log("== K1 a workflow whose script starts with a blank line (run: | then an empty line), pushed by one team; another team's run queued after it")
	blank := "on: push\njobs:\n  setup:\n    runs-on: probe\n    steps:\n      - name: Install\n        run: |\n\n          npm ci\n          npm test\n"
	bad := e.newRun("blank.yml", blank, nil)
	good := e.newRun("good.yml", wf(job("build", "")), nil)
	if bad != nil {
		for i := 0; i < 2; i++ {
			tk, err := r.fetch()
			t.Logf("   runner poll %d: got a job=%v err=%v", i+1, tk != nil, err)
		}
		t.Logf("   first run:  %s", e.states(bad))
		t.Logf("   second run: %s", e.states(good))
		e.rerun(bad, false)
		e.cancel(bad)
		tk, err := r.fetch()
		t.Logf("   after someone cancels the first run: got a job=%v err=%v", tk != nil, err)
		if tk != nil {
			r.finish(tk.Id, true, nil)
		}
	}

	t.Log("== K2 same script shape inside a job that sits behind a needs")
	bad2 := e.newRun("blank2.yml", "on: push\njobs:\n  a:\n    runs-on: probe\n    steps:\n      - run: echo\n  b:\n    needs: a\n    runs-on: probe\n    steps:\n      - run: |\n\n          make deploy\n", nil)
	if bad2 != nil {
		n := e.drive(r, nil, nil)
		t.Logf("   runner finished %d job(s); %s", n, e.states(bad2))
		e.cancel(bad2)
	}

	t.Log("== K3 status functions across more than one hop: a fails, b (needs a, if: always()) passes, then c needs b")
	for _, c := range []struct{ title, cond, github string }{
		{"c has no if", "", "skipped (an ancestor failed)"},
		{"c has if: failure()", "    if: failure()\n", "runs (an ancestor failed)"},
		{"c has if: success()", "    if: success()\n", "skipped"},
	} {
		run := e.newRun("chain.yml", wf(job("a", ""), job("b", "    needs: a\n    if: always()\n"), job("c", "    needs: b\n"+c.cond)), nil)
		e.drive(r, map[string]bool{"a": true}, nil)
		t.Logf("   %-22s -> %s   [GitHub: c %s]", c.title, e.states(run), c.github)
	}

	t.Log("== K4 continue-on-error job fails")
	run := e.newRun("coe.yml", wf(job("flaky", "    continue-on-error: true\n"), job("solid", ""), job("after", "    needs: [flaky, solid]\n")), nil)
	e.drive(r, map[string]bool{"flaky": true}, func(j *actions_model.ActionRunJob, task *runnerv1.Task) {
		if j.Name == "after" {
			t.Logf("   'after' is handed needs.flaky.result=%s", strings.ToLower(strings.TrimPrefix(task.Needs["flaky"].Result.String(), "RESULT_")))
		}
	})
	sts, _ := git_model.GetLatestCommitStatus(e.ctx, e.repo.ID, e.sha, db.ListOptionsAll)
	var cs []string
	for _, s := range sts {
		if strings.HasPrefix(s.Context, "coe.yml") {
			cs = append(cs, strings.TrimPrefix(s.Context, "coe.yml / ")+"="+string(s.State))
		}
	}
	sort.Strings(cs)
	t.Logf("   %s ; commit statuses: %v", e.states(run), cs)

	t.Log("== K5 secrets after a repository changes owner while a job is queued")
	_, _ = secret_model.InsertEncryptedSecret(e.ctx, e.repo.OwnerID, 0, "OLD_OWNER_SECRET", "x", "")
	_, _ = secret_model.InsertEncryptedSecret(e.ctx, 2, 0, "NEW_OWNER_SECRET", "x", "")
	_, _ = actions_model.InsertVariable(e.ctx, e.repo.OwnerID, 0, "OLD_OWNER_VAR", "x", "")
	_, _ = actions_model.InsertVariable(e.ctx, 2, 0, "NEW_OWNER_VAR", "x", "")
	e.newRun("own.yml", wf(job("build", "")), nil)
	_, err := db.GetEngine(e.ctx).Exec("UPDATE repository SET owner_id=2, owner_name='user2' WHERE id=?", e.repo.ID)
	require.NoError(t, err)
	e.drive(r, nil, func(j *actions_model.ActionRunJob, task *runnerv1.Task) {
		var vars []string
		for k := range task.Vars {
			vars = append(vars, k)
		}
		sort.Strings(vars)
		t.Logf("   job queued under the old owner, picked after the transfer: secrets=%v vars=%v", secretsOf(task), vars)
	})
	_, _ = db.GetEngine(e.ctx).Exec("UPDATE repository SET owner_id=?, owner_name='user5' WHERE id=?", e.repo.OwnerID, e.repo.ID)
	_ = access_model.Permission{}
	_ = unit.TypeCode
}
